pub struct ProjectContextMaterialSession {
    store: LocalEncryptedContextMaterialStore,
    tenant_id: TenantId,
    project_id: ProjectId,
    device_id: DeviceId,
    keyring_revision: u64,
    active_key_version: u64,
    readable_key_versions: BTreeSet<u64>,
    unavailable_historical_key_versions: BTreeSet<u64>,
}

impl ProjectContextMaterialSession {
    pub fn project_id(&self) -> &ProjectId {
        &self.project_id
    }

    /// Canonical project root for process-local adapters. The path is never
    /// included in Debug output or persisted as Runtime evidence.
    pub fn project_root(&self) -> &Path {
        self.store.project_root()
    }

    pub const fn keyring_revision(&self) -> u64 {
        self.keyring_revision
    }

    pub const fn active_key_version(&self) -> u64 {
        self.active_key_version
    }

    pub fn readable_key_versions(&self) -> &BTreeSet<u64> {
        &self.readable_key_versions
    }

    pub fn unavailable_historical_key_versions(&self) -> &BTreeSet<u64> {
        &self.unavailable_historical_key_versions
    }

    pub fn put_text(
        &self,
        text: &str,
    ) -> Result<ContextMaterialDescriptor, ContextMaterialStoreError> {
        self.store.put_text(text)
    }

    pub fn snapshot_project_file(
        &self,
        relative_path: &Path,
    ) -> Result<ContextMaterialDescriptor, ContextMaterialStoreError> {
        self.store.snapshot_project_file(relative_path)
    }

    pub fn snapshot_query(
        &self,
        snapshot: &ContextQuerySnapshot,
    ) -> Result<ContextMaterialDescriptor, ContextMaterialStoreError> {
        self.store.snapshot_query(snapshot)
    }

    pub fn load_text(
        &self,
        storage_ref: &str,
    ) -> Result<Option<ResolvedContextMaterial>, ContextMaterialStoreError> {
        self.store.load_text(storage_ref)
    }
}

impl fmt::Debug for ProjectContextMaterialSession {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ProjectContextMaterialSession")
            .field(
                "tenant_scope_digest",
                &sha256(self.tenant_id.as_str().as_bytes()),
            )
            .field(
                "project_scope_digest",
                &sha256(self.project_id.as_str().as_bytes()),
            )
            .field(
                "device_scope_digest",
                &sha256(self.device_id.as_str().as_bytes()),
            )
            .field("keyring_revision", &self.keyring_revision)
            .field("active_key_version", &self.active_key_version)
            .field("readable_key_versions", &self.readable_key_versions)
            .field(
                "unavailable_historical_key_versions",
                &self.unavailable_historical_key_versions,
            )
            // The encrypted material store owns live key bytes and is
            // intentionally omitted from diagnostic output.
            .finish_non_exhaustive()
    }
}

impl ContextMaterialResolver for ProjectContextMaterialSession {
    fn resolve(
        &self,
        reference: &ContextMaterialReference,
    ) -> Result<Option<ResolvedContextMaterial>, ContextAssemblyError> {
        self.store.resolve(reference)
    }
}

