#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct LocalMissionRuntimeIds {
    pub workspace_id: ContextWorkspaceId,
    pub working_set_id: ContextWorkingSetId,
    pub continuation_ledger_id: ContextContinuationLedgerId,
    pub compaction_id: ContextCompactionRecordId,
    pub checkpoint_id: ContextCheckpointId,
    pub capsule_id: ContextCapsuleId,
    pub branch_id: ContextBranchId,
    pub worker_lease_id: WorkerLeaseId,
    pub worker_id: WorkerId,
    pub mailbox_id: ContextWorkerMailboxId,
    pub assembly_id: ContextAssemblyId,
}

impl LocalMissionRuntimeIds {
    pub fn for_mission(mission_id: &MissionId, generation: u64) -> Self {
        let scoped =
            |kind: &str| format!("local-runtime:{kind}:{}:{generation}", mission_id.as_str());
        Self {
            workspace_id: ContextWorkspaceId::from_stable(scoped("workspace")),
            working_set_id: ContextWorkingSetId::from_stable(scoped("working-set")),
            continuation_ledger_id: ContextContinuationLedgerId::from_stable(scoped(
                "continuation",
            )),
            compaction_id: ContextCompactionRecordId::from_stable(scoped("compaction")),
            checkpoint_id: ContextCheckpointId::from_stable(scoped("checkpoint")),
            capsule_id: ContextCapsuleId::from_stable(scoped("capsule")),
            branch_id: ContextBranchId::from_stable(scoped("branch")),
            worker_lease_id: WorkerLeaseId::from_stable(scoped("lease")),
            worker_id: WorkerId::from_stable(scoped("worker")),
            mailbox_id: ContextWorkerMailboxId::from_stable(scoped("mailbox")),
            assembly_id: ContextAssemblyId::from_stable(scoped("assembly")),
        }
    }
}

