#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ConversationSyncSnapshot {
    pub sync_version: u64,
    pub identity: ConversationIdentitySnapshot,
    pub connection: ConnectionSnapshot,
    pub consents: Vec<ConsentRecord>,
    pub conversation: Conversation,
}

impl ConversationSyncSnapshot {
    fn validate_for(
        &self,
        project: &Project,
        mission: &Mission,
        object_id: &str,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        if self.sync_version == 0
            || self.sync_version != self.conversation.revision
            || self.conversation.tenant_id != project.tenant_id
            || self.conversation.project_id != project.id
            || self.conversation.id.as_str() != object_id
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        self.conversation.validate_snapshot(
            &self.identity,
            &self.connection,
            mission,
            &self.consents,
            now,
        )?;
        Ok(())
    }
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CreatorWorkSyncSnapshot {
    pub sync_version: u64,
    pub identities: Vec<CreatorIdentitySnapshot>,
    pub hiring: CreatorHiring,
    pub task: CreatorTask,
}

impl CreatorWorkSyncSnapshot {
    fn validate_for(
        &self,
        project: &Project,
        mission: &Mission,
        object_id: &str,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        if self.sync_version == 0
            || self.hiring.tenant_id != project.tenant_id
            || self.hiring.project_id != project.id
            || self.task.tenant_id != project.tenant_id
            || self.task.project_id != project.id
            || self.task.id.as_str() != object_id
            || self.task.hiring_award.hiring_id != self.hiring.id
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        let mut partner_ids = BTreeSet::new();
        for identity in &self.identities {
            let candidate = self
                .hiring
                .candidates
                .iter()
                .find(|candidate| candidate.partner_id == identity.partner.id)
                .ok_or(ApplicationError::InvalidSyncDocument)?;
            identity.validate_for_candidate(&project.tenant_id, &project.id, candidate)?;
            if !partner_ids.insert(identity.partner.id.clone()) {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        if self.hiring.candidates.len() != self.identities.len()
            || self
                .hiring
                .candidates
                .iter()
                .any(|candidate| !partner_ids.contains(&candidate.partner_id))
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        self.task.validate_snapshot(&self.hiring, mission, now)?;
        Ok(())
    }
}

/// Self-contained, encrypted VM-11 projection. Every referenced identity,
/// relationship and provider binding travels with the immutable ledger so a
/// receiving device never has to trust unrelated demo/local state.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct OutcomeLedgerSyncSnapshot {
    pub sync_version: u64,
    pub missions: Vec<Mission>,
    pub connections: Vec<ConnectionSnapshot>,
    pub companies: Vec<Company>,
    pub people: Vec<Person>,
    pub partners: Vec<Partner>,
    pub identity_links: Vec<IdentityLink>,
    pub consents: Vec<ConsentRecord>,
    pub campaigns: Vec<Campaign>,
    pub opportunities: Vec<Opportunity>,
    pub ledger: OutcomeLedger,
}

/// Minimal, authenticated worker grant. The payload contains exact referenced
/// Truth revisions and typed IDs/digests, never credentials, connection tokens,
/// browser profiles, a parent prompt, or direct Effect execution authority.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ContextCapsuleSyncSnapshot {
    pub sync_version: u64,
    pub workspace: ContextWorkspace,
    pub branch_lineage: Vec<ContextBranch>,
    pub worker_lease: WorkerLease,
    pub facts: Vec<TruthFact>,
    pub capsule: ContextCapsule,
}

impl ContextCapsuleSyncSnapshot {
    fn validate_for(
        &self,
        project: &Project,
        mission: &Mission,
        object_id: &str,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        if self.sync_version == 0
            || self.capsule.id.as_str() != object_id
            || self.workspace.tenant_id != project.tenant_id
            || self.workspace.project_id != project.id
            || self.workspace.mission_id != mission.id
            || self.capsule.tenant_id != project.tenant_id
            || self.capsule.project_id != project.id
            || self.capsule.mission_id != mission.id
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        self.workspace.validate_for(mission, now)?;
        validate_context_branch_lineage(&self.workspace, &self.branch_lineage, now)?;
        let branch = self
            .branch_lineage
            .last()
            .ok_or(ApplicationError::InvalidSyncDocument)?;
        if branch.id != self.capsule.branch_id {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        self.worker_lease
            .validate_for(&self.workspace, branch, now)?;
        self.capsule.validate_for(
            &self.workspace,
            branch,
            &self.worker_lease,
            mission,
            &self.facts,
            now,
        )?;
        Ok(())
    }
}

impl OutcomeLedgerSyncSnapshot {
    #[allow(
        clippy::too_many_lines,
        reason = "the exact sync closure validator audits every reference class in one fail-closed boundary"
    )]
    fn validate_for(&self, project: &Project, object_id: &str) -> Result<(), ApplicationError> {
        if self.sync_version == 0
            || self.ledger.tenant_id != project.tenant_id
            || self.ledger.project_id != project.id
            || object_id != project.id.as_str()
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        self.ledger.validate()?;
        for event in &self.ledger.events {
            // Persisted v16 records may be readable for migration, but they can
            // never cross the encrypted sync boundary without source proof.
            event.validate()?;
        }

        let mission_map = self
            .missions
            .iter()
            .map(|mission| (mission.id.clone(), mission))
            .collect::<BTreeMap<_, _>>();
        let connection_map = self
            .connections
            .iter()
            .map(|connection| (connection.id.clone(), connection))
            .collect::<BTreeMap<_, _>>();
        let company_map = self
            .companies
            .iter()
            .map(|company| (company.id.clone(), company))
            .collect::<BTreeMap<_, _>>();
        let person_map = self
            .people
            .iter()
            .map(|person| (person.id.clone(), person))
            .collect::<BTreeMap<_, _>>();
        let partner_map = self
            .partners
            .iter()
            .map(|partner| (partner.id.clone(), partner))
            .collect::<BTreeMap<_, _>>();
        let identity_map = self
            .identity_links
            .iter()
            .map(|link| (link.id.clone(), link))
            .collect::<BTreeMap<_, _>>();
        let consent_map = self
            .consents
            .iter()
            .map(|consent| (consent.id.clone(), consent))
            .collect::<BTreeMap<_, _>>();
        let campaign_map = self
            .campaigns
            .iter()
            .map(|campaign| (campaign.id.clone(), campaign))
            .collect::<BTreeMap<_, _>>();
        let opportunity_map = self
            .opportunities
            .iter()
            .map(|opportunity| (opportunity.id.clone(), opportunity))
            .collect::<BTreeMap<_, _>>();
        if mission_map.len() != self.missions.len()
            || connection_map.len() != self.connections.len()
            || company_map.len() != self.companies.len()
            || person_map.len() != self.people.len()
            || partner_map.len() != self.partners.len()
            || identity_map.len() != self.identity_links.len()
            || consent_map.len() != self.consents.len()
            || campaign_map.len() != self.campaigns.len()
            || opportunity_map.len() != self.opportunities.len()
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }

        for mission in &self.missions {
            validate_synced_mission_snapshot(mission, project, mission.id.as_str())?;
        }
        for connection in &self.connections {
            connection.validate()?;
            require_sync_scope(project, &connection.tenant_id, &connection.project_id)?;
        }
        for company in &self.companies {
            company.validate()?;
            require_sync_scope(project, &company.tenant_id, &company.project_id)?;
        }
        for person in &self.people {
            person.validate()?;
            require_sync_scope(project, &person.tenant_id, &person.project_id)?;
        }
        for partner in &self.partners {
            partner.validate()?;
            require_sync_scope(project, &partner.tenant_id, &partner.project_id)?;
        }
        for link in &self.identity_links {
            link.validate()?;
            require_sync_scope(project, &link.tenant_id, &link.project_id)?;
            if link.status != IdentityLinkStatus::Confirmed {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        for consent in &self.consents {
            consent.validate()?;
            require_sync_scope(project, &consent.tenant_id, &consent.project_id)?;
        }
        for campaign in &self.campaigns {
            campaign.validate()?;
            require_sync_scope(project, &campaign.tenant_id, &campaign.project_id)?;
        }
        for opportunity in &self.opportunities {
            opportunity.validate()?;
            require_sync_scope(project, &opportunity.tenant_id, &opportunity.project_id)?;
        }

        let mut expected_missions = BTreeSet::new();
        let mut expected_connections = BTreeSet::new();
        let mut expected_identities = BTreeSet::new();
        let mut expected_campaigns = BTreeSet::new();
        let mut expected_opportunities = BTreeSet::new();
        let mut expected_partners = BTreeSet::new();
        for event in &self.ledger.events {
            expected_missions.insert(event.mission_id.clone());
            if let Some(connection_id) = &event.connection_id {
                expected_connections.insert(connection_id.clone());
                let connection = connection_map
                    .get(connection_id)
                    .ok_or(ApplicationError::InvalidSyncDocument)?;
                if connection.provider != event.provider
                    || Some(&connection.account_id) != event.account_id.as_ref()
                {
                    return Err(ApplicationError::InvalidSyncDocument);
                }
            }
            if let Some(identity_link_id) = &event.identity_link_id {
                expected_identities.insert(identity_link_id.clone());
                let link = identity_map
                    .get(identity_link_id)
                    .ok_or(ApplicationError::InvalidSyncDocument)?;
                if let Some(account_id) = &event.account_id
                    && !link.confirms_external_identity(&event.provider, account_id)
                {
                    return Err(ApplicationError::InvalidSyncDocument);
                }
            }
            if let Some(campaign_id) = &event.campaign_id {
                expected_campaigns.insert(campaign_id.clone());
            }
            if let Some(opportunity_id) = &event.opportunity_id {
                expected_opportunities.insert(opportunity_id.clone());
            }
            if let Some(partner_id) = &event.partner_id {
                expected_partners.insert(partner_id.clone());
            }
        }
        for attribution in &self.ledger.attributions {
            if let Some(touchpoint) = &attribution.touchpoint {
                expected_missions.insert(touchpoint.mission_id.clone());
            }
        }
        for commission in &self.ledger.commissions {
            expected_partners.insert(commission.partner_id.clone());
        }
        if expected_connections != connection_map.keys().cloned().collect()
            || expected_identities != identity_map.keys().cloned().collect()
            || expected_campaigns != campaign_map.keys().cloned().collect()
            || expected_opportunities != opportunity_map.keys().cloned().collect()
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }

        let mut expected_people = BTreeSet::new();
        let mut expected_companies = BTreeSet::new();
        let mut expected_consents = BTreeSet::new();
        for link in &self.identity_links {
            match &link.subject {
                IdentitySubject::Person(id) => {
                    expected_people.insert(id.clone());
                }
                IdentitySubject::Company(id) => {
                    expected_companies.insert(id.clone());
                }
                IdentitySubject::Partner(id) => {
                    expected_partners.insert(id.clone());
                }
            }
        }
        for campaign in &self.campaigns {
            expected_missions.insert(campaign.mission_id.clone());
            for recipient in &campaign.recipients {
                expected_people.insert(recipient.person_id.clone());
                expected_consents.insert(recipient.consent_record_id.clone());
                let consent = consent_map
                    .get(&recipient.consent_record_id)
                    .ok_or(ApplicationError::InvalidSyncDocument)?;
                if consent.person_id != recipient.person_id
                    || consent.purpose != campaign.purpose
                    || consent.channel != campaign.channel
                    || !consent.market.eq_ignore_ascii_case(&campaign.market)
                {
                    return Err(ApplicationError::InvalidSyncDocument);
                }
            }
        }
        for opportunity in &self.opportunities {
            expected_companies.insert(opportunity.company_id.clone());
            expected_people.extend(
                opportunity
                    .buying_committee
                    .iter()
                    .map(|member| member.person_id.clone()),
            );
        }
        for partner in &self.partners {
            if let Some(person_id) = &partner.person_id {
                expected_people.insert(person_id.clone());
            }
            if let Some(company_id) = &partner.company_id {
                expected_companies.insert(company_id.clone());
            }
        }
        for person in &self.people {
            if let Some(company_id) = &person.company_id {
                expected_companies.insert(company_id.clone());
            }
        }
        if expected_missions != mission_map.keys().cloned().collect()
            || expected_partners != partner_map.keys().cloned().collect()
            || expected_people != person_map.keys().cloned().collect()
            || expected_companies != company_map.keys().cloned().collect()
            || expected_consents != consent_map.keys().cloned().collect()
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }

        for person in &self.people {
            if person
                .company_id
                .as_ref()
                .is_some_and(|id| !company_map.contains_key(id))
            {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        for partner in &self.partners {
            if partner
                .person_id
                .as_ref()
                .is_some_and(|id| !person_map.contains_key(id))
                || partner
                    .company_id
                    .as_ref()
                    .is_some_and(|id| !company_map.contains_key(id))
            {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        for opportunity in &self.opportunities {
            if !company_map.contains_key(&opportunity.company_id)
                || opportunity
                    .buying_committee
                    .iter()
                    .any(|member| !person_map.contains_key(&member.person_id))
            {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        Ok(())
    }
}

fn require_sync_scope(
    project: &Project,
    tenant_id: &TenantId,
    project_id: &ProjectId,
) -> Result<(), ApplicationError> {
    if tenant_id == &project.tenant_id && project_id == &project.id {
        Ok(())
    } else {
        Err(ApplicationError::InvalidSyncDocument)
    }
}

impl ConnectionMetadataSyncSnapshot {
    fn validate_for(&self, project: &Project, object_id: &str) -> Result<(), ApplicationError> {
        self.connection.validate()?;
        if self.sync_version == 0
            || self.connection.tenant_id != project.tenant_id
            || self.connection.project_id != project.id
            || self.connection.id.as_str() != object_id
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        Ok(())
    }
}

impl WorkProductSyncSnapshot {
    fn validate_for(&self, project: &Project, object_id: &str) -> Result<(), ApplicationError> {
        self.manifest.validate_against(&self.work_product)?;
        if self.manifest.tenant_id != project.tenant_id
            || self.manifest.project_id != project.id
            || self.manifest.work_product_id.as_str() != object_id
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        Ok(())
    }
}

impl ProjectMetadataSnapshot {
    #[must_use]
    pub fn from_project(project: &Project) -> Self {
        Self {
            tenant_id: project.tenant_id.clone(),
            project_id: project.id.clone(),
            name: project.name.clone(),
            description: project.description.clone(),
            storage_mode: project.storage_mode.clone(),
            data_cell: project.data_cell,
            revision: project.revision,
        }
    }

    fn validate_for(&self, project: &Project, object_id: &str) -> Result<(), ApplicationError> {
        if self.tenant_id != project.tenant_id
            || self.project_id != project.id
            || self.project_id.as_str() != object_id
            || self.name.trim().is_empty()
            || self.storage_mode != StorageMode::LocalEncryptedSync
            || self.storage_mode != project.storage_mode
            || self.data_cell.is_none()
            || self.data_cell != project.data_cell
            || self.revision == 0
        {
            return Err(ApplicationError::InvalidSyncDocument);
        }
        Ok(())
    }

    fn project_over(&self, local: &Project) -> Result<Project, ApplicationError> {
        self.validate_for(local, local.id.as_str())?;
        Ok(Project {
            tenant_id: self.tenant_id.clone(),
            id: self.project_id.clone(),
            name: self.name.clone(),
            description: self.description.clone(),
            storage_mode: self.storage_mode.clone(),
            data_cell: self.data_cell,
            workspace_roots: local.workspace_roots.clone(),
            revision: self.revision,
        })
    }
}

impl fmt::Debug for SyncDocument {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("SyncDocument")
            .field("schema_version", &self.schema_version)
            .field("tenant_id", &self.tenant_id)
            .field("project_id", &self.project_id)
            .field("object_id", &self.object_id)
            .field("object_kind", &self.object_kind)
            .field("body", &"[REDACTED]")
            .finish()
    }
}

