#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum MissionCheckpointDispatchState {
    Ready,
    Blocked,
    WaitingUser,
    WaitingApproval,
    Verifying,
}

impl TryFrom<MissionCheckpointStatus> for MissionCheckpointDispatchState {
    type Error = ApplicationError;

    fn try_from(status: MissionCheckpointStatus) -> Result<Self, Self::Error> {
        match status {
            MissionCheckpointStatus::Running => Ok(Self::Ready),
            MissionCheckpointStatus::Blocked => Ok(Self::Blocked),
            MissionCheckpointStatus::WaitingUser => Ok(Self::WaitingUser),
            MissionCheckpointStatus::WaitingApproval => Ok(Self::WaitingApproval),
            MissionCheckpointStatus::Verifying => Ok(Self::Verifying),
            MissionCheckpointStatus::Pending
            | MissionCheckpointStatus::Ready
            | MissionCheckpointStatus::Completed
            | MissionCheckpointStatus::Skipped => {
                Err(ApplicationError::MissionCheckpointDispatchUnavailable)
            }
        }
    }
}

/// Content-free proof of the exact current Catalog Checkpoint route. A
/// `Ready` Checkpoint is first started with its route-bound Task in the same
/// durable boundary used by `begin_mission_checkpoint`; callers may then
/// select only the returned executor. This proof does not claim that an
/// Application, Effect Broker, Runtime, or Human handler completed any work.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct MissionCheckpointDispatch {
    pub project_id: ProjectId,
    pub mission_id: MissionId,
    pub mission_revision: u64,
    pub cycle: u64,
    pub checkpoint_id: String,
    pub checkpoint_revision: u64,
    pub capability_id: String,
    pub executor: MissionCheckpointExecutor,
    pub oracle_ids: BTreeSet<String>,
    pub completion_policy: MissionCheckpointCompletionPolicy,
    /// Present only for an Application route. `Implemented` means the exact
    /// versioned handler is present in both the machine registry and this
    /// binary; absence from the allow-list is explicitly `NotImplemented`.
    #[serde(default)]
    pub application_handler_status: Option<ApplicationCheckpointHandlerStatus>,
    #[serde(default)]
    pub application_handler_id: Option<String>,
    pub state: MissionCheckpointDispatchState,
}

const VM11_EVENT_INGEST_HANDLER_ID: &str = "vm11.event_ingest/v1";

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum CompiledApplicationCheckpointHandler {
    Vm11EventIngest,
}

fn compiled_application_checkpoint_handler(
    handler_id: &str,
) -> Option<CompiledApplicationCheckpointHandler> {
    match handler_id {
        VM11_EVENT_INGEST_HANDLER_ID => Some(CompiledApplicationCheckpointHandler::Vm11EventIngest),
        _ => None,
    }
}

fn application_checkpoint_handler_projection(
    definition: &MissionDefinition,
    checkpoint_id: &str,
    route: &MissionCheckpointRoute,
) -> Result<(Option<ApplicationCheckpointHandlerStatus>, Option<String>), ApplicationError> {
    if route.executor != MissionCheckpointExecutor::Application {
        return Ok((None, None));
    }
    let catalog = Catalog::load()?;
    let catalog_digest = catalog.snapshot()?.digest;
    if definition.catalog_digest != catalog_digest {
        return Ok((
            Some(ApplicationCheckpointHandlerStatus::CatalogRevisionMismatch),
            None,
        ));
    }
    let Some(handler) = catalog.application_handler(
        &definition.manifest_id,
        definition.manifest_version,
        checkpoint_id,
    ) else {
        return Ok((
            Some(ApplicationCheckpointHandlerStatus::NotImplemented),
            None,
        ));
    };
    if compiled_application_checkpoint_handler(&handler.handler_id).is_none() {
        return Err(
            ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                handler_id: handler.handler_id.clone(),
            },
        );
    }
    Ok((
        Some(ApplicationCheckpointHandlerStatus::Implemented),
        Some(handler.handler_id.clone()),
    ))
}

fn current_checkpoint_dispatch_projection(
    mission: &Mission,
) -> Result<Option<MissionCheckpointDispatch>, ApplicationError> {
    let Some(definition) = mission.definition.as_ref() else {
        return Err(ApplicationError::MissionCheckpointDispatchUnavailable);
    };
    let Some(checkpoint) = definition.current_checkpoint() else {
        return Ok(None);
    };
    let route = checkpoint
        .route
        .as_ref()
        .filter(|route| route.is_contracted())
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let completion_policy = route
        .completion_policy
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let state = MissionCheckpointDispatchState::try_from(checkpoint.status)?;
    let (application_handler_status, application_handler_id) =
        application_checkpoint_handler_projection(definition, &checkpoint.id, route)?;
    if state == MissionCheckpointDispatchState::Ready
        && !mission.tasks.iter().any(|task| {
            task.status == TaskStatus::Running && task.capability == route.capability_id
        })
    {
        return Err(ApplicationError::MissionCheckpointDispatchUnavailable);
    }
    Ok(Some(MissionCheckpointDispatch {
        project_id: mission.project_id.clone(),
        mission_id: mission.id.clone(),
        mission_revision: mission.revision,
        cycle: definition.cycle,
        checkpoint_id: checkpoint.id.clone(),
        checkpoint_revision: checkpoint.revision,
        capability_id: route.capability_id.clone(),
        executor: route.executor,
        oracle_ids: route.oracle_ids.clone(),
        completion_policy,
        application_handler_status,
        application_handler_id,
        state,
    }))
}

type StartedCatalogCheckpoint = (String, u64, String, MissionCheckpointExecutor, TaskId, u64);

fn start_ready_catalog_checkpoint_in_memory(
    mission: &mut Mission,
    now: DateTime<Utc>,
) -> Result<Option<StartedCatalogCheckpoint>, ApplicationError> {
    let next = mission.definition.as_ref().and_then(|definition| {
        definition
            .current_checkpoint()
            .filter(|checkpoint| checkpoint.status == MissionCheckpointStatus::Ready)
            .and_then(|checkpoint| {
                checkpoint.route.as_ref().map(|route| {
                    (
                        definition.cycle,
                        checkpoint.id.clone(),
                        route.capability_id.clone(),
                        route.executor,
                    )
                })
            })
    });
    let Some((cycle, checkpoint_id, capability_id, executor)) = next else {
        return Ok(None);
    };
    let task_id = TaskId::from_stable(format!(
        "mission-checkpoint-task:{}:{checkpoint_id}:cycle:{cycle}",
        mission.id
    ));
    mission.begin_checkpoint_with_task(
        &checkpoint_id,
        Task {
            id: task_id.clone(),
            title: format!("Checkpoint: {checkpoint_id}"),
            status: TaskStatus::Running,
            capability: capability_id.clone(),
        },
        now,
    )?;
    let checkpoint_revision = mission
        .definition
        .as_ref()
        .and_then(MissionDefinition::current_checkpoint)
        .filter(|checkpoint| checkpoint.id == checkpoint_id)
        .map(|checkpoint| checkpoint.revision)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    Ok(Some((
        checkpoint_id,
        checkpoint_revision,
        capability_id,
        executor,
        task_id,
        cycle,
    )))
}

fn completed_application_checkpoint_replay(
    mission: &Mission,
    command: &ExecuteApplicationMissionCheckpoint,
) -> Result<Option<ApplicationMissionCheckpointExecution>, ApplicationError> {
    let Some(completion) = mission
        .definition
        .as_ref()
        .and_then(|definition| {
            definition.checkpoints.iter().find(|checkpoint| {
                checkpoint.id == command.checkpoint_id
                    && checkpoint.status == MissionCheckpointStatus::Completed
            })
        })
        .and_then(|checkpoint| checkpoint.completion.as_ref())
    else {
        return Ok(None);
    };
    let Some(evidence) = completion.application_evidence.as_ref() else {
        return Err(ApplicationError::ApplicationCheckpointReplayMismatch);
    };
    if evidence.handler_id != VM11_EVENT_INGEST_HANDLER_ID
        || evidence.dispatch_mission_revision != command.expected_mission_revision
        || evidence.dispatch_checkpoint_revision != command.expected_checkpoint_revision
        || evidence.checkpoint_id != command.checkpoint_id
    {
        return Err(ApplicationError::ApplicationCheckpointReplayMismatch);
    }
    let outcome_ledger_revision = evidence
        .sources
        .iter()
        .find(|source| source.source_kind == "outcome_ledger")
        .map(|source| source.source_revision)
        .ok_or(ApplicationError::ApplicationCheckpointReplayMismatch)?;
    Ok(Some(ApplicationMissionCheckpointExecution::Completed {
        completed_checkpoint_id: command.checkpoint_id.clone(),
        completion_evidence_digest: completion.evidence_digest.clone(),
        outcome_ledger_revision,
        replayed: true,
        next_dispatch: current_checkpoint_dispatch_projection(mission)?,
    }))
}

fn blocked_application_checkpoint_replay(
    store: &ProjectStore,
    mission: &Mission,
    command: &ExecuteApplicationMissionCheckpoint,
) -> Result<Option<ApplicationMissionCheckpointExecution>, ApplicationError> {
    if mission.stage != MissionStage::Blocked {
        return Ok(None);
    }
    let Some(event) = store
        .events_for_mission(&command.project_id, &command.mission_id)?
        .into_iter()
        .rev()
        .find(|event| {
            event.event_type == "mission.application_checkpoint_blocked"
                && event
                    .payload
                    .get("handlerId")
                    .and_then(serde_json::Value::as_str)
                    == Some(VM11_EVENT_INGEST_HANDLER_ID)
                && event
                    .payload
                    .get("checkpointId")
                    .and_then(serde_json::Value::as_str)
                    == Some(command.checkpoint_id.as_str())
                && event
                    .payload
                    .get("dispatchMissionRevision")
                    .and_then(serde_json::Value::as_u64)
                    == Some(command.expected_mission_revision)
                && event
                    .payload
                    .get("dispatchCheckpointRevision")
                    .and_then(serde_json::Value::as_u64)
                    == Some(command.expected_checkpoint_revision)
        })
    else {
        return Ok(None);
    };
    let code = event
        .payload
        .get("code")
        .and_then(serde_json::Value::as_str)
        .filter(|code| {
            mission
                .block
                .as_ref()
                .is_some_and(|block| block.code == *code)
        })
        .ok_or(ApplicationError::ApplicationCheckpointReplayMismatch)?;
    let outcome_ledger_revision = event
        .payload
        .get("outcomeLedgerRevision")
        .and_then(serde_json::Value::as_u64)
        .ok_or(ApplicationError::ApplicationCheckpointReplayMismatch)?;
    Ok(Some(ApplicationMissionCheckpointExecution::Blocked {
        checkpoint_id: command.checkpoint_id.clone(),
        code: code.into(),
        outcome_ledger_revision,
        replayed: true,
    }))
}

fn vm11_event_ingest_application_evidence(
    mission: &Mission,
    route: &MissionCheckpointRoute,
    command: &ExecuteApplicationMissionCheckpoint,
    ledger: &OutcomeLedger,
    now: DateTime<Utc>,
) -> Result<MissionCheckpointApplicationEvidence, ApplicationError> {
    let definition = mission
        .definition
        .as_ref()
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let checkpoint = definition
        .checkpoints
        .iter()
        .find(|checkpoint| checkpoint.id == command.checkpoint_id)
        .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
    let contract_digest = canonical_sha256(&serde_json::to_value(&mission.contract)?)?;
    let outcome_projection_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-vm11-event-ingest-source/v1",
        "tenantId": ledger.tenant_id,
        "projectId": ledger.project_id,
        "ledgerRevision": ledger.revision,
        "events": ledger.events.iter().map(|event| serde_json::json!({
            "eventId": event.id,
            "missionId": event.mission_id,
            "kind": event.kind,
            "provider": event.provider,
            "connectionId": event.connection_id,
            "accountId": event.account_id,
            "occurredAt": event.occurred_at,
            "receivedAt": event.received_at,
            "evidenceDigest": event.evidence_digest,
            "rawPayloadDigest": event.raw_payload_digest,
            "sourceVerification": event.source_verification.as_ref().map(|verification| serde_json::json!({
                "method": verification.method,
                "verifier": verification.verifier,
                "independent": verification.independent,
                "verifiedAt": verification.verified_at,
                "evidenceDigest": verification.evidence_digest,
            })),
        })).collect::<Vec<_>>(),
    }))?;
    let operating_state_digest = canonical_sha256(&serde_json::json!({
        "schemaVersion": "hartevo-application-checkpoint-state/v1",
        "tenantId": mission.tenant_id,
        "projectId": mission.project_id,
        "missionId": mission.id,
        "manifestId": definition.manifest_id,
        "manifestVersion": definition.manifest_version,
        "catalogDigest": definition.catalog_digest,
        "cycle": definition.cycle,
        "checkpointId": checkpoint.id,
        "dispatchMissionRevision": command.expected_mission_revision,
        "dispatchCheckpointRevision": command.expected_checkpoint_revision,
        "verificationMissionRevision": mission.revision,
        "verificationCheckpointRevision": checkpoint.revision,
        "capabilityId": route.capability_id,
        "executor": route.executor,
        "completionPolicy": route.completion_policy,
    }))?;
    let sources = BTreeSet::from([
        MissionCheckpointOracleSource {
            source_kind: "mission_contract".into(),
            source_id: mission.id.to_string(),
            source_revision: command.expected_mission_revision,
            projection_digest: contract_digest,
            oracle_ids: BTreeSet::from(["goal".into()]),
        },
        MissionCheckpointOracleSource {
            source_kind: "mission_checkpoint".into(),
            source_id: format!("{}:{}", mission.id, checkpoint.id),
            source_revision: command.expected_checkpoint_revision,
            projection_digest: operating_state_digest,
            oracle_ids: BTreeSet::from(["operating_state".into()]),
        },
        MissionCheckpointOracleSource {
            source_kind: "outcome_ledger".into(),
            source_id: ledger.project_id.to_string(),
            source_revision: ledger.revision,
            projection_digest: outcome_projection_digest,
            oracle_ids: BTreeSet::from(["outcome".into(), "truth".into()]),
        },
    ]);
    Ok(MissionCheckpointApplicationEvidence {
        schema_version: MissionCheckpointApplicationEvidence::SCHEMA_VERSION,
        handler_id: VM11_EVENT_INGEST_HANDLER_ID.into(),
        tenant_id: mission.tenant_id.clone(),
        project_id: mission.project_id.clone(),
        mission_id: mission.id.clone(),
        manifest_id: definition.manifest_id.clone(),
        manifest_version: definition.manifest_version,
        catalog_digest: definition.catalog_digest.clone(),
        cycle: definition.cycle,
        checkpoint_id: checkpoint.id.clone(),
        dispatch_mission_revision: command.expected_mission_revision,
        dispatch_checkpoint_revision: command.expected_checkpoint_revision,
        verification_mission_revision: mission.revision,
        verification_checkpoint_revision: checkpoint.revision,
        capability_id: route.capability_id.clone(),
        executor: route.executor,
        completion_policy: route
            .completion_policy
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?,
        sources,
        observed_at: now,
    })
}

