    pub fn prepare_browser_file_upload(
        &mut self,
        broker: &mut FileBroker,
        command: PrepareBrowserFileUpload,
        now: DateTime<Utc>,
        scanner: &mut impl FileSafetyScanner,
    ) -> Result<BrowserFileGrant, ApplicationError> {
        let project = self.store.load_project(&command.project_id)?;
        let workspace = self
            .store
            .load_browser_workspace(&command.project_id, &command.workspace_id)?;
        let grant = broker.prepare_upload(
            command.grant_id,
            &project,
            &workspace,
            &command.lease_proof,
            &command.source_path,
            command.expected_type,
            command.authorization_evidence_digest,
            command.expires_at,
            now,
            scanner,
        )?;
        if let Err(persistence) = self.store.create_browser_file_grant_atomic(&grant) {
            if let Err(cleanup) = broker.discard_unpersisted_prepared_grant(&grant) {
                return Err(
                    ApplicationError::BrowserFilePreparationReconciliationRequired {
                        grant_id: grant.id.clone(),
                        persistence: Box::new(persistence),
                        cleanup,
                    },
                );
            }
            return Err(ApplicationError::Storage(persistence));
        }
        Ok(grant)
    }

    pub fn claim_browser_file_upload(
        &mut self,
        broker: &mut FileBroker,
        command: ClaimBrowserFileUpload,
        now: DateTime<Utc>,
    ) -> Result<FileUploadHandle, ApplicationError> {
        let workspace = self
            .store
            .load_browser_workspace(&command.project_id, &command.workspace_id)?;
        let plan = broker.plan_claim_upload(
            &command.grant_id,
            command.claim_id,
            &workspace,
            &command.lease_proof,
            &command.action_payload_digest,
            command.expected_revision,
            now,
        )?;
        let next = plan.grant().clone();
        self.store
            .update_browser_file_grant_atomic(&next, command.expected_revision)?;
        broker.commit_claim_upload(plan).map_err(|source| {
            ApplicationError::BrowserFileBrokerReconciliationRequired {
                grant_id: next.id,
                source,
            }
        })
    }

    pub fn complete_browser_file_upload(
        &mut self,
        broker: &mut FileBroker,
        command: CompleteBrowserFileUpload,
        now: DateTime<Utc>,
    ) -> Result<BrowserFileGrant, ApplicationError> {
        let workspace = self
            .store
            .load_browser_workspace(&command.project_id, &command.workspace_id)?;
        let plan = broker.plan_complete_upload(
            &command.grant_id,
            &command.claim_id,
            &workspace,
            &command.lease_proof,
            command.expected_revision,
            command.completion_evidence_digest,
            now,
        )?;
        let next = plan.grant().clone();
        self.store
            .update_browser_file_grant_atomic(&next, command.expected_revision)?;
        broker.commit_terminal_transition(plan).map_err(|source| {
            ApplicationError::BrowserFileBrokerReconciliationRequired {
                grant_id: next.id,
                source,
            }
        })
    }

    pub fn expire_browser_file_upload(
        &mut self,
        broker: &mut FileBroker,
        command: &ExpireBrowserFileUpload,
        now: DateTime<Utc>,
    ) -> Result<BrowserFileGrant, ApplicationError> {
        let plan = broker.plan_expire_grant(&command.grant_id, command.expected_revision, now)?;
        let next = plan.grant().clone();
        if next.project_id != command.project_id {
            return Err(ApplicationError::Browser(BrowserError::InvalidFileGrant));
        }
        self.store
            .update_browser_file_grant_atomic(&next, command.expected_revision)?;
        broker.commit_terminal_transition(plan).map_err(|source| {
            ApplicationError::BrowserFileBrokerReconciliationRequired {
                grant_id: next.id,
                source,
            }
        })
    }

