    pub fn start_mission(
        &mut self,
        command: StartMission,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let project = self.store.load_project(&command.project_id)?;
        let contract = compile_contract(&command.prompt, now);
        let title = command
            .title
            .unwrap_or_else(|| concise_title(&command.prompt));
        let mut mission = Mission::compile(
            project.tenant_id,
            command.id,
            command.project_id,
            title,
            contract,
            now,
        )?;
        mission.start_research(
            [Task {
                id: command.research_task_id,
                title: "核对市场证据并形成工作产物".into(),
                status: TaskStatus::Running,
                capability: "research.discover".into(),
            }],
            now,
        )?;
        self.store.create_mission_atomic(
            &mission,
            &[
                PendingEvent::new(
                    "mission.started",
                    serde_json::json!({"stage": mission.stage}),
                    now,
                ),
                PendingEvent::new(
                    "goal.confirmed",
                    serde_json::json!({
                        "goal": mission.contract.goal,
                        "constraints": mission.contract.constraints
                    }),
                    now,
                ),
            ],
        )?;
        Ok(mission)
    }

    #[allow(
        clippy::too_many_lines,
        reason = "Catalog dispatch compiles and persists the exact Mission definition, first checkpoint, contract, Conversation, and content-free evidence boundary"
    )]
    pub fn start_catalog_mission(
        &mut self,
        command: StartCatalogMission,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let project = self.store.load_project(&command.project_id)?;
        let catalog = Catalog::load()?;
        let snapshot = catalog.snapshot()?;
        let manifest = catalog
            .mission(command.manifest_id.trim())
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let contract = compile_catalog_contract(&catalog, manifest, &command, now)?;
        let checkpoint_routes = manifest
            .checkpoint_routes
            .iter()
            .map(|route| {
                Ok((
                    route.checkpoint_id.clone(),
                    MissionCheckpointRoute::contracted(
                        route.capability_id.clone(),
                        MissionCheckpointExecutor::try_from(route.executor.as_str())?,
                        route.oracle_ids.iter().cloned(),
                        MissionCheckpointCompletionPolicy::try_from(
                            route.completion_policy.as_str(),
                        )?,
                    )?,
                ))
            })
            .collect::<Result<Vec<_>, MissionError>>()?;
        let definition = MissionDefinition::from_routed_linear_manifest(
            manifest.id.clone(),
            manifest.version,
            snapshot.digest.clone(),
            command.mode.clone(),
            manifest.capability_ids.iter().cloned(),
            manifest.required_artifacts.iter().cloned(),
            manifest.oracle_ids.iter().cloned(),
            checkpoint_routes,
        )?;
        let title = command
            .title
            .unwrap_or_else(|| format!("{} · {}", manifest.id, concise_title(command.goal.trim())));
        let first_checkpoint_id = manifest
            .checkpoint_ids
            .first()
            .cloned()
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let (first_capability, first_executor) = definition
            .checkpoints
            .first()
            .and_then(|checkpoint| checkpoint.route.as_ref())
            .map(|route| (route.capability_id.clone(), route.executor))
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let mut mission = Mission::compile_catalog(
            project.tenant_id,
            command.id,
            command.project_id,
            title,
            contract,
            definition,
            now,
        )?;
        mission.start_research(
            [Task {
                id: command.first_task_id,
                title: format!("Checkpoint: {first_checkpoint_id}"),
                status: TaskStatus::Running,
                capability: first_capability.clone(),
            }],
            now,
        )?;
        let conversation = MissionConversation::start(
            MissionConversationId::from_stable(format!(
                "mission-conversation:{}",
                mission.id.as_str()
            )),
            MissionConversationMessageId::from_stable(format!(
                "mission-message:goal:{}",
                mission.id.as_str()
            )),
            &mission,
            mission.contract.goal.clone(),
            format!("mission-start:{}", mission.id.as_str()),
            now,
        )?;
        let initial_message = conversation
            .messages
            .first()
            .expect("validated Mission Conversation has an initial message");
        let contract_digest = canonical_sha256(&serde_json::to_value(&mission.contract)?)?;
        self.store.create_catalog_mission_with_conversation_atomic(
            &mission,
            &conversation,
            &[
                PendingEvent::new(
                    "mission.catalog_bound",
                    serde_json::json!({
                        "manifestId": manifest.id,
                        "manifestVersion": manifest.version,
                        "catalogDigest": snapshot.digest,
                        "contractDigest": contract_digest,
                        "mode": mission.contract.mode,
                    }),
                    now,
                ),
                PendingEvent::new(
                    "mission.checkpoint_started",
                    serde_json::json!({
                        "checkpointId": first_checkpoint_id,
                        "cycle": 1,
                        "checkpointRevision": 2,
                        "capabilityId": first_capability,
                        "executor": first_executor,
                    }),
                    now,
                ),
                PendingEvent::new(
                    "mission.conversation_started",
                    serde_json::json!({
                        "conversationId": conversation.id,
                        "messageId": initial_message.id,
                        "sequence": initial_message.sequence,
                        "contentDigest": initial_message.content_digest,
                        "missionRevision": initial_message.mission_revision,
                        "checkpointId": initial_message.checkpoint_id,
                    }),
                    now,
                ),
            ],
        )?;
        Ok(mission)
    }

    /// Resolves the exact current Catalog Checkpoint and, when the DAG exposes
    /// a `Ready` node, starts that node with its route-bound Task before
    /// returning a revision-fenced dispatch proof. No executor is invoked by
    /// this method and no non-Runtime route may be inferred as Runtime work.
    pub fn dispatch_current_mission_checkpoint(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        now: DateTime<Utc>,
    ) -> Result<MissionCheckpointDispatch, ApplicationError> {
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        let current_status = mission
            .definition
            .as_ref()
            .and_then(MissionDefinition::current_checkpoint)
            .map(|checkpoint| checkpoint.status)
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        if current_status == MissionCheckpointStatus::Ready {
            let checkpoint_id = mission
                .definition
                .as_ref()
                .and_then(MissionDefinition::current_checkpoint)
                .map(|checkpoint| checkpoint.id.clone())
                .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
            mission = self.begin_mission_checkpoint(project_id, mission_id, &checkpoint_id, now)?;
        }

        current_checkpoint_dispatch_projection(&mission)?
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)
    }

    /// Executes one exact Application-routed Checkpoint. Unsupported routes
    /// return `NotImplemented` without mutating the Mission; they are never
    /// completed by a caller-supplied digest. VM-11 `event_ingest` is the first
    /// production handler and is fenced to the immutable Outcome Ledger
    /// revision inspected by the handler.
    #[allow(
        clippy::too_many_lines,
        reason = "the first Application handler keeps replay, empty-source blocking, source-fenced Oracle materialization, completion, and next-route handoff in one auditable boundary"
    )]
    pub fn execute_application_mission_checkpoint(
        &mut self,
        command: ExecuteApplicationMissionCheckpoint,
        now: DateTime<Utc>,
    ) -> Result<ApplicationMissionCheckpointExecution, ApplicationError> {
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        if let Some(replay) = completed_application_checkpoint_replay(&mission, &command)? {
            return Ok(replay);
        }
        if let Some(replay) =
            blocked_application_checkpoint_replay(&self.store, &mission, &command)?
        {
            return Ok(replay);
        }

        let dispatch = current_checkpoint_dispatch_projection(&mission)?
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        if dispatch.executor != MissionCheckpointExecutor::Application {
            return Err(ApplicationError::ApplicationCheckpointExecutorMismatch {
                executor: dispatch.executor,
            });
        }
        if dispatch.checkpoint_id != command.checkpoint_id
            || dispatch.mission_revision != command.expected_mission_revision
            || dispatch.checkpoint_revision != command.expected_checkpoint_revision
        {
            return Err(ApplicationError::ApplicationCheckpointCommandMismatch);
        }
        let Some(handler_id) = dispatch.application_handler_id.as_deref() else {
            if dispatch.application_handler_status
                == Some(ApplicationCheckpointHandlerStatus::NotImplemented)
            {
                return Ok(ApplicationMissionCheckpointExecution::NotImplemented { dispatch });
            }
            if dispatch.application_handler_status
                == Some(ApplicationCheckpointHandlerStatus::CatalogRevisionMismatch)
            {
                return Err(ApplicationError::ApplicationCheckpointCatalogRevisionMismatch);
            }
            return Err(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: "missing-registered-handler-id".into(),
                },
            );
        };
        let Some(compiled_handler) = compiled_application_checkpoint_handler(handler_id) else {
            return Err(
                ApplicationError::ApplicationCheckpointHandlerRegistryMismatch {
                    handler_id: handler_id.into(),
                },
            );
        };
        match compiled_handler {
            CompiledApplicationCheckpointHandler::Vm11EventIngest => {}
        }

        let outcome_ledger = match self.store.load_outcome_ledger(&command.project_id) {
            Ok(ledger) => Some(ledger),
            Err(StorageError::ScopedRecordNotFound {
                kind: "outcome ledger",
                ..
            }) => None,
            Err(error) => return Err(error.into()),
        };
        let outcome_ledger_revision = outcome_ledger.as_ref().map_or(0, |ledger| ledger.revision);
        if outcome_ledger
            .as_ref()
            .is_none_or(|ledger| ledger.events.is_empty())
        {
            let code = if outcome_ledger.is_some() {
                "outcome_events_unavailable"
            } else {
                "outcome_ledger_unavailable"
            };
            if mission.stage == MissionStage::Blocked
                && mission
                    .block
                    .as_ref()
                    .is_some_and(|block| block.code == code)
            {
                return Ok(ApplicationMissionCheckpointExecution::Blocked {
                    checkpoint_id: command.checkpoint_id,
                    code: code.into(),
                    outcome_ledger_revision,
                    replayed: true,
                });
            }
            let expected_mission_revision = mission.revision;
            let block = hartevo_domain_kernel::MissionBlock {
                code: code.into(),
                detail: if outcome_ledger.is_some() {
                    "No verified OutcomeEvent is available; event_ingest remains blocked without inventing an outcome."
                        .into()
                } else {
                    "The project OutcomeLedger has not been initialized; event_ingest remains blocked without a substitute snapshot."
                        .into()
                },
                recoverable: true,
                observed_at: now,
            };
            mission.block_checkpoint(&command.checkpoint_id, &block, MissionStage::Blocked)?;
            let events = [PendingEvent::new(
                "mission.application_checkpoint_blocked",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": command.checkpoint_id,
                    "capabilityId": dispatch.capability_id,
                    "handlerId": VM11_EVENT_INGEST_HANDLER_ID,
                    "dispatchMissionRevision": command.expected_mission_revision,
                    "dispatchCheckpointRevision": command.expected_checkpoint_revision,
                    "code": code,
                    "recoverable": true,
                    "outcomeLedgerRevision": outcome_ledger_revision,
                }),
                now,
            )];
            self.store.update_mission_atomic_with_outcome_ledger_fence(
                &mission,
                expected_mission_revision,
                outcome_ledger.as_ref().map(|ledger| ledger.revision),
                &events,
            )?;
            return Ok(ApplicationMissionCheckpointExecution::Blocked {
                checkpoint_id: command.checkpoint_id,
                code: code.into(),
                outcome_ledger_revision,
                replayed: false,
            });
        }

        let outcome_ledger = outcome_ledger.expect("non-empty ledger checked");
        outcome_ledger.validate()?;
        let expected_mission_revision = mission.revision;
        if mission.stage == MissionStage::Blocked {
            mission.resume(now)?;
        }
        mission.begin_checkpoint_verification(&command.checkpoint_id, now)?;
        let definition = mission
            .definition
            .as_ref()
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        let checkpoint = definition
            .checkpoints
            .iter()
            .find(|checkpoint| checkpoint.id == command.checkpoint_id)
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        let route = checkpoint
            .route
            .as_ref()
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        let application_evidence = vm11_event_ingest_application_evidence(
            &mission,
            route,
            &command,
            &outcome_ledger,
            now,
        )?;
        let evidence_digest = application_evidence.digest();
        mission.complete_checkpoint(
            &command.checkpoint_id,
            MissionCheckpointCompletion {
                oracle_ids: route.oracle_ids.clone(),
                work_product_ids: BTreeSet::new(),
                effect_ids: BTreeSet::new(),
                application_evidence: Some(application_evidence),
                evidence_digest: evidence_digest.clone(),
                verified_at: now,
            },
        )?;
        let completed_checkpoint_revision = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == command.checkpoint_id)
            })
            .map(|checkpoint| checkpoint.revision)
            .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
        let next_started = start_ready_catalog_checkpoint_in_memory(&mut mission, now)?;
        let next_dispatch = current_checkpoint_dispatch_projection(&mission)?;
        let mut events = vec![PendingEvent::new(
            "mission.application_checkpoint_completed",
            serde_json::json!({
                "missionId": mission.id,
                "checkpointId": command.checkpoint_id,
                "checkpointRevision": completed_checkpoint_revision,
                "capabilityId": dispatch.capability_id,
                "handlerId": VM11_EVENT_INGEST_HANDLER_ID,
                "oracleIds": dispatch.oracle_ids,
                "sourceKind": "outcome_ledger",
                "sourceRevision": outcome_ledger.revision,
                "sourceEventCount": outcome_ledger.events.len(),
                "evidenceDigest": evidence_digest,
            }),
            now,
        )];
        if let Some((checkpoint_id, checkpoint_revision, capability_id, executor, task_id, cycle)) =
            next_started
        {
            events.push(PendingEvent::new(
                "mission.checkpoint_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint_id,
                    "checkpointRevision": checkpoint_revision,
                    "capabilityId": capability_id,
                    "executor": executor,
                    "cycle": cycle,
                    "taskId": task_id,
                }),
                now,
            ));
        }
        self.store.update_mission_atomic_with_outcome_ledger_fence(
            &mission,
            expected_mission_revision,
            Some(outcome_ledger.revision),
            &events,
        )?;
        Ok(ApplicationMissionCheckpointExecution::Completed {
            completed_checkpoint_id: command.checkpoint_id,
            completion_evidence_digest: evidence_digest,
            outcome_ledger_revision: outcome_ledger.revision,
            replayed: false,
            next_dispatch,
        })
    }

    pub fn begin_mission_checkpoint(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        checkpoint_id: &str,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        let expected_revision = mission.revision;
        let (cycle, capability) = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == checkpoint_id)
                    .and_then(|checkpoint| {
                        checkpoint
                            .route
                            .as_ref()
                            .map(|route| (definition.cycle, route.capability_id.clone()))
                    })
            })
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let task = Task {
            id: TaskId::from_stable(format!(
                "mission-checkpoint-task:{}:{checkpoint_id}:cycle:{cycle}",
                mission.id
            )),
            title: format!("Checkpoint: {checkpoint_id}"),
            status: TaskStatus::Running,
            capability,
        };
        let task_id = task.id.clone();
        mission.begin_checkpoint_with_task(checkpoint_id, task, now)?;
        let checkpoint = mission
            .definition
            .as_ref()
            .and_then(|definition| definition.current_checkpoint())
            .filter(|checkpoint| checkpoint.id == checkpoint_id)
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new(
                "mission.checkpoint_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint.id,
                    "checkpointRevision": checkpoint.revision,
                    "capabilityId": checkpoint.route.as_ref().map(|route| &route.capability_id),
                    "executor": checkpoint.route.as_ref().map(|route| route.executor),
                    "cycle": mission.definition.as_ref().map(|definition| definition.cycle),
                    "taskId": task_id,
                }),
                now,
            )],
        )?;
        Ok(mission)
    }

    pub fn begin_mission_checkpoint_verification(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        checkpoint_id: &str,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let mut mission = self.store.load_mission(project_id, mission_id)?;
        if mission.definition.as_ref().is_some_and(|definition| {
            definition.current_checkpoint().is_some_and(|checkpoint| {
                checkpoint.id == checkpoint_id
                    && checkpoint.route.as_ref().is_some_and(|route| {
                        route.completion_policy
                            == Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
                    })
            })
        }) {
            return Err(ApplicationError::HumanCheckpointConfirmationRequired);
        }
        let expected_revision = mission.revision;
        mission.begin_checkpoint_verification(checkpoint_id, now)?;
        let checkpoint = mission
            .definition
            .as_ref()
            .and_then(|definition| definition.active_checkpoint())
            .filter(|checkpoint| checkpoint.id == checkpoint_id)
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new(
                "mission.checkpoint_verification_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint.id,
                    "checkpointRevision": checkpoint.revision,
                    "capabilityId": checkpoint.route.as_ref().map(|route| &route.capability_id),
                    "executor": checkpoint.route.as_ref().map(|route| route.executor),
                    "cycle": mission.definition.as_ref().map(|definition| definition.cycle),
                }),
                now,
            )],
        )?;
        Ok(mission)
    }

    pub fn complete_mission_checkpoint(
        &mut self,
        project_id: &ProjectId,
        mission_id: &MissionId,
        checkpoint_id: &str,
        completion: MissionCheckpointCompletion,
    ) -> Result<Mission, ApplicationError> {
        let mission = self.store.load_mission(project_id, mission_id)?;
        if let Some(route) = mission.definition.as_ref().and_then(|definition| {
            definition
                .current_checkpoint()
                .filter(|checkpoint| checkpoint.id == checkpoint_id)
                .and_then(|checkpoint| checkpoint.route.as_ref())
        }) {
            if route.completion_policy == Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
            {
                return Err(ApplicationError::HumanCheckpointConfirmationRequired);
            }
            if route.executor == MissionCheckpointExecutor::Application {
                return Err(ApplicationError::ApplicationCheckpointExecutionRequired);
            }
        }
        self.complete_mission_checkpoint_trusted(mission, checkpoint_id, completion)
    }

    fn complete_mission_checkpoint_trusted(
        &mut self,
        mut mission: Mission,
        checkpoint_id: &str,
        completion: MissionCheckpointCompletion,
    ) -> Result<Mission, ApplicationError> {
        let expected_revision = mission.revision;
        let completed_at = completion.verified_at;
        let evidence_digest = completion.evidence_digest.clone();
        let oracle_ids = completion.oracle_ids.clone();
        let work_product_count = completion.work_product_ids.len();
        let effect_count = completion.effect_ids.len();
        mission.complete_checkpoint(checkpoint_id, completion)?;
        let completed_checkpoint = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == checkpoint_id)
            })
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        self.store.update_mission_atomic(
            &mission,
            expected_revision,
            &[PendingEvent::new(
                "mission.checkpoint_completed",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": completed_checkpoint.id,
                    "checkpointRevision": completed_checkpoint.revision,
                    "capabilityId": completed_checkpoint.route.as_ref().map(|route| &route.capability_id),
                    "executor": completed_checkpoint.route.as_ref().map(|route| route.executor),
                    "cycle": mission.definition.as_ref().map(|definition| definition.cycle),
                    "oracleIds": oracle_ids,
                    "evidenceDigest": evidence_digest,
                    "workProductCount": work_product_count,
                    "effectCount": effect_count,
                    "nextCheckpointId": mission.definition.as_ref().and_then(|definition| definition.current_checkpoint().map(|checkpoint| &checkpoint.id)),
                }),
                completed_at,
            )],
        )?;
        Ok(mission)
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the Human Checkpoint boundary binds replay, dual revisions, exact WorkProducts, confirmation evidence, completion, and next-route handoff in one transaction"
    )]
    pub fn confirm_human_mission_checkpoint(
        &mut self,
        command: ConfirmHumanMissionCheckpoint,
        now: DateTime<Utc>,
    ) -> Result<HumanMissionCheckpointConfirmation, ApplicationError> {
        let mut mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        let mut conversation = self
            .store
            .load_mission_conversation(&command.project_id, &command.mission_id)?;
        let normalized_body = command.body.trim();

        if let Some(existing) = conversation
            .messages
            .iter()
            .find(|message| message.idempotency_key == command.idempotency_key.trim())
            .cloned()
        {
            let checkpoint = mission
                .definition
                .as_ref()
                .and_then(|definition| {
                    definition
                        .checkpoints
                        .iter()
                        .find(|checkpoint| checkpoint.id == command.checkpoint_id)
                })
                .ok_or(ApplicationError::HumanCheckpointConfirmationReplayMismatch)?;
            let completion = checkpoint
                .completion
                .as_ref()
                .ok_or(ApplicationError::HumanCheckpointConfirmationReplayMismatch)?;
            if existing.id != command.message_id
                || existing.role != MissionConversationRole::User
                || existing.kind != MissionConversationMessageKind::CheckpointConfirmation
                || existing.body != normalized_body
                || existing.mission_revision != command.expected_mission_revision
                || existing.checkpoint_id.as_deref() != Some(command.checkpoint_id.as_str())
                || checkpoint.status != MissionCheckpointStatus::Completed
                || checkpoint.revision <= command.expected_checkpoint_revision
                || checkpoint.route.as_ref().is_none_or(|route| {
                    route.executor != MissionCheckpointExecutor::Human
                        || route.completion_policy
                            != Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
                        || completion.oracle_ids != route.oracle_ids
                })
                || completion.work_product_ids != command.work_product_ids
            {
                return Err(ApplicationError::HumanCheckpointConfirmationReplayMismatch);
            }
            return Ok(HumanMissionCheckpointConfirmation {
                mission: mission.clone(),
                conversation,
                message: existing,
                completed_checkpoint_id: command.checkpoint_id,
                completion_evidence_digest: completion.evidence_digest.clone(),
                next_dispatch: current_checkpoint_dispatch_projection(&mission)?,
            });
        }

        if mission.revision != command.expected_mission_revision {
            return Err(ApplicationError::MissionRevisionMismatch {
                expected: command.expected_mission_revision,
                actual: mission.revision,
            });
        }
        if conversation.revision != command.expected_conversation_revision {
            return Err(ApplicationError::MissionConversationRevisionMismatch {
                expected: command.expected_conversation_revision,
                actual: conversation.revision,
            });
        }
        let (cycle, checkpoint_revision, route) = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition.current_checkpoint().and_then(|checkpoint| {
                    checkpoint.route.clone().map(|route| {
                        (
                            definition.cycle,
                            checkpoint.revision,
                            (checkpoint.id.clone(), checkpoint.status, route),
                        )
                    })
                })
            })
            .map(|(cycle, revision, (checkpoint_id, status, route))| {
                (cycle, revision, checkpoint_id, status, route)
            })
            .and_then(|(cycle, revision, checkpoint_id, status, route)| {
                (checkpoint_id == command.checkpoint_id
                    && status == MissionCheckpointStatus::Running)
                    .then_some((cycle, revision, route))
            })
            .ok_or(ApplicationError::HumanCheckpointConfirmationUnavailable)?;
        if checkpoint_revision != command.expected_checkpoint_revision {
            return Err(ApplicationError::MissionCheckpointRevisionMismatch {
                checkpoint_id: command.checkpoint_id,
                expected: command.expected_checkpoint_revision,
                actual: checkpoint_revision,
            });
        }
        if !route.is_contracted()
            || route.executor != MissionCheckpointExecutor::Human
            || route.completion_policy != Some(MissionCheckpointCompletionPolicy::HumanConfirmation)
        {
            return Err(ApplicationError::HumanCheckpointConfirmationUnavailable);
        }
        let requires_work_product = route.oracle_ids.contains("work_product");
        if requires_work_product == command.work_product_ids.is_empty() {
            return Err(ApplicationError::HumanCheckpointWorkProductMismatch);
        }
        let work_product_proofs = command
            .work_product_ids
            .iter()
            .map(|work_product_id| {
                mission
                    .work_products
                    .iter()
                    .find(|work_product| {
                        &work_product.id == work_product_id
                            && matches!(
                                work_product.status,
                                WorkProductStatus::ReadyForReview | WorkProductStatus::Accepted
                            )
                    })
                    .map(|work_product| {
                        serde_json::json!({
                            "id": work_product.id,
                            "revision": work_product.revision,
                            "status": work_product.status,
                            "contentDigest": work_product.content_digest,
                        })
                    })
                    .ok_or(ApplicationError::HumanCheckpointWorkProductMismatch)
            })
            .collect::<Result<Vec<_>, _>>()?;

        let expected_mission_revision = mission.revision;
        let expected_conversation_revision = conversation.revision;
        let (message, appended) = conversation.append_user_message(
            command.message_id,
            MissionConversationMessageKind::CheckpointConfirmation,
            command.body,
            command.idempotency_key,
            &mission,
            now,
        )?;
        if !appended {
            return Err(ApplicationError::HumanCheckpointConfirmationReplayMismatch);
        }
        let evidence_digest = canonical_sha256(&serde_json::json!({
            "schemaVersion": "hartevo-human-checkpoint-confirmation/v1",
            "tenantId": mission.tenant_id,
            "projectId": mission.project_id,
            "missionId": mission.id,
            "missionRevision": expected_mission_revision,
            "catalogDigest": mission.definition.as_ref().map(|definition| &definition.catalog_digest),
            "manifestVersion": mission.definition.as_ref().map(|definition| definition.manifest_version),
            "cycle": cycle,
            "checkpointId": command.checkpoint_id,
            "checkpointRevision": checkpoint_revision,
            "capabilityId": route.capability_id,
            "executor": route.executor,
            "completionPolicy": route.completion_policy,
            "oracleIds": route.oracle_ids,
            "conversationId": conversation.id,
            "conversationRevision": conversation.revision,
            "messageId": message.id,
            "messageSequence": message.sequence,
            "messageContentDigest": message.content_digest,
            "idempotencyKey": message.idempotency_key,
            "workProducts": work_product_proofs,
        }))?;

        mission.begin_checkpoint_verification(&command.checkpoint_id, now)?;
        mission.complete_checkpoint(
            &command.checkpoint_id,
            MissionCheckpointCompletion {
                oracle_ids: route.oracle_ids.clone(),
                work_product_ids: command.work_product_ids,
                effect_ids: BTreeSet::new(),
                application_evidence: None,
                evidence_digest: evidence_digest.clone(),
                verified_at: now,
            },
        )?;
        let completed_checkpoint_revision = mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|checkpoint| checkpoint.id == command.checkpoint_id)
            })
            .map(|checkpoint| checkpoint.revision)
            .ok_or(ApplicationError::HumanCheckpointConfirmationUnavailable)?;

        let next_checkpoint_to_start = mission.definition.as_ref().and_then(|definition| {
            definition
                .current_checkpoint()
                .filter(|checkpoint| checkpoint.status == MissionCheckpointStatus::Ready)
                .and_then(|checkpoint| {
                    checkpoint.route.as_ref().map(|next_route| {
                        (
                            definition.cycle,
                            checkpoint.id.clone(),
                            next_route.capability_id.clone(),
                            next_route.executor,
                        )
                    })
                })
        });
        let next_started = if let Some((next_cycle, checkpoint_id, capability_id, executor)) =
            next_checkpoint_to_start
        {
            let task_id = TaskId::from_stable(format!(
                "mission-checkpoint-task:{}:{checkpoint_id}:cycle:{next_cycle}",
                mission.id
            ));
            mission.begin_checkpoint_with_task(
                &checkpoint_id,
                Task {
                    id: task_id.clone(),
                    title: format!("Checkpoint: {checkpoint_id}"),
                    status: TaskStatus::Running,
                    capability: capability_id.clone(),
                },
                now,
            )?;
            let revision = mission
                .definition
                .as_ref()
                .and_then(MissionDefinition::current_checkpoint)
                .filter(|checkpoint| checkpoint.id == checkpoint_id)
                .map(|checkpoint| checkpoint.revision)
                .ok_or(ApplicationError::MissionCheckpointDispatchUnavailable)?;
            Some((
                checkpoint_id,
                revision,
                capability_id,
                executor,
                task_id,
                next_cycle,
            ))
        } else {
            None
        };
        let next_dispatch = current_checkpoint_dispatch_projection(&mission)?;

        let mut events = vec![
            PendingEvent::new(
                "mission.human_checkpoint_confirmed",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": command.checkpoint_id,
                    "checkpointRevision": completed_checkpoint_revision,
                    "conversationId": conversation.id,
                    "conversationRevision": conversation.revision,
                    "messageId": message.id,
                    "messageSequence": message.sequence,
                    "messageContentDigest": message.content_digest,
                    "oracleIds": route.oracle_ids,
                    "workProductCount": work_product_proofs.len(),
                    "evidenceDigest": evidence_digest,
                }),
                now,
            ),
            PendingEvent::new(
                "mission.checkpoint_completed",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": command.checkpoint_id,
                    "checkpointRevision": completed_checkpoint_revision,
                    "capabilityId": route.capability_id,
                    "executor": route.executor,
                    "cycle": cycle,
                    "oracleIds": route.oracle_ids,
                    "evidenceDigest": evidence_digest,
                    "workProductCount": work_product_proofs.len(),
                    "effectCount": 0,
                    "nextCheckpointId": next_dispatch.as_ref().map(|dispatch| &dispatch.checkpoint_id),
                }),
                now,
            ),
        ];
        if let Some((checkpoint_id, revision, capability_id, executor, task_id, next_cycle)) =
            &next_started
        {
            events.push(PendingEvent::new(
                "mission.checkpoint_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "checkpointId": checkpoint_id,
                    "checkpointRevision": revision,
                    "capabilityId": capability_id,
                    "executor": executor,
                    "cycle": next_cycle,
                    "taskId": task_id,
                }),
                now,
            ));
        }
        self.store
            .complete_human_checkpoint_with_conversation_atomic(
                &mission,
                expected_mission_revision,
                &conversation,
                expected_conversation_revision,
                &events,
            )?;
        Ok(HumanMissionCheckpointConfirmation {
            mission,
            conversation,
            message,
            completed_checkpoint_id: command.checkpoint_id,
            completion_evidence_digest: evidence_digest,
            next_dispatch,
        })
    }

    pub fn append_mission_conversation_message(
        &mut self,
        command: AppendMissionConversationMessage,
        now: DateTime<Utc>,
    ) -> Result<MissionConversation, ApplicationError> {
        let mission = self
            .store
            .load_mission(&command.project_id, &command.mission_id)?;
        let mut conversation = self
            .store
            .load_mission_conversation(&command.project_id, &command.mission_id)?;
        let stored_revision = conversation.revision;
        let (message, appended) = conversation.append_user_message(
            command.message_id,
            command.kind,
            command.body,
            command.idempotency_key,
            &mission,
            now,
        )?;
        if !appended {
            return Ok(conversation);
        }
        if stored_revision != command.expected_conversation_revision {
            return Err(ApplicationError::MissionConversationRevisionMismatch {
                expected: command.expected_conversation_revision,
                actual: stored_revision,
            });
        }
        if let Some(previous_user_generation) = conversation
            .messages
            .iter()
            .rev()
            .skip(1)
            .find(|message| message.role == MissionConversationRole::User)
            .map(|message| message.sequence)
        {
            self.retire_previous_local_runtime_authority(
                &mission,
                previous_user_generation,
                message.sequence,
                now,
            )?;
        }
        self.store.append_mission_conversation_atomic(
            &conversation,
            command.expected_conversation_revision,
            &[PendingEvent::new(
                "mission.conversation_message_recorded",
                serde_json::json!({
                    "conversationId": conversation.id,
                    "messageId": message.id,
                    "sequence": message.sequence,
                    "role": message.role,
                    "kind": message.kind,
                    "contentDigest": message.content_digest,
                    "missionRevision": message.mission_revision,
                    "checkpointId": message.checkpoint_id,
                    "authorityChanged": false,
                }),
                now,
            )],
        )?;
        Ok(conversation)
    }

    #[allow(
        clippy::too_many_lines,
        reason = "generation retirement validates and revokes the complete branch, lease, capsule, handle, mailbox, and turn authority closure"
    )]
    fn retire_previous_local_runtime_authority(
        &mut self,
        mission: &Mission,
        previous_user_generation: u64,
        next_conversation_sequence: u64,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        let turn = self
            .latest_runtime_turn_for_mission(&mission.project_id, &mission.id)?
            .filter(|turn| turn.scope.worker_generation == previous_user_generation);
        let Some(turn) = turn else {
            return self.retire_local_runtime_authority_without_turn(
                mission,
                previous_user_generation,
                next_conversation_sequence,
                now,
            );
        };
        if turn.status.is_active() && turn.status != RuntimeTurnStatus::Uncertain {
            return Err(ApplicationError::RuntimeGenerationHasActiveTurn);
        }
        let mut handle = self.store.load_worker_handle(
            &turn.scope.project_id,
            &turn.scope.workspace_id,
            &turn.scope.worker_id,
        )?;
        let mut branch = self
            .store
            .load_context_branch(&turn.scope.project_id, &turn.scope.branch_id)?;
        let mut lease = self
            .store
            .load_worker_lease(&turn.scope.project_id, &turn.scope.worker_lease_id)?;
        let mut capsule = self
            .store
            .load_context_capsule(&turn.scope.project_id, &turn.scope.capsule_id)?;
        let already_terminal = matches!(
            (branch.status, lease.status, capsule.status, handle.status),
            (
                ContextBranchStatus::Completed | ContextBranchStatus::Merged,
                WorkerLeaseStatus::Released,
                ContextCapsuleStatus::Accepted,
                WorkerHandleStatus::Completed
            ) | (
                ContextBranchStatus::Abandoned,
                WorkerLeaseStatus::Revoked | WorkerLeaseStatus::Expired,
                ContextCapsuleStatus::Cancelled | ContextCapsuleStatus::Expired,
                WorkerHandleStatus::Cancelled | WorkerHandleStatus::Failed
            )
        );
        if already_terminal {
            return Ok(());
        }
        if !matches!(
            turn.status,
            RuntimeTurnStatus::Completed
                | RuntimeTurnStatus::Interrupted
                | RuntimeTurnStatus::Failed
                | RuntimeTurnStatus::Uncertain
        ) || !matches!(
            handle.status,
            WorkerHandleStatus::Attached | WorkerHandleStatus::Detached
        ) || branch.status != ContextBranchStatus::Active
            || lease.status != WorkerLeaseStatus::Active
            || !matches!(
                capsule.status,
                ContextCapsuleStatus::Issued | ContextCapsuleStatus::Claimed
            )
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let expected_branch_revision = branch.revision;
        let expected_lease_revision = lease.revision;
        let expected_capsule_revision = capsule.revision;
        let expected_handle_revision = handle.revision;
        let conflict_digest = sha256(
            format!(
                "conversation-generation-superseded:{}:{}:{}",
                turn.id, previous_user_generation, next_conversation_sequence
            )
            .as_bytes(),
        );
        branch.abandon(&conflict_digest, now)?;
        if now >= lease.expires_at {
            lease.expire(now)?;
        } else {
            let lease_token_digest = lease.lease_token_digest.clone();
            lease.revoke(lease.generation, &lease_token_digest, now)?;
        }
        if now > capsule.expires_at {
            capsule.expire(now)?;
            handle.fail(&capsule, now)?;
        } else {
            capsule.cancel(now)?;
            handle.cancel(&capsule, now)?;
        }
        self.store.retire_runtime_turn_authority(
            &turn,
            &branch,
            expected_branch_revision,
            &lease,
            expected_lease_revision,
            &capsule,
            expected_capsule_revision,
            &handle,
            expected_handle_revision,
            &[PendingEvent::new(
                "context.runtime_turn_authority_retired",
                serde_json::json!({
                    "runtimeTurnAttemptId": turn.id,
                    "missionId": mission.id,
                    "workspaceId": turn.scope.workspace_id,
                    "workerId": turn.scope.worker_id,
                    "retiredGeneration": previous_user_generation,
                    "nextConversationSequence": next_conversation_sequence,
                    "turnStatus": turn.status,
                    "branchStatus": branch.status,
                    "leaseStatus": lease.status,
                    "capsuleStatus": capsule.status,
                    "handleStatus": handle.status,
                    "externalEffectReplayed": false,
                }),
                now,
            )],
            now,
        )?;
        Ok(())
    }

    #[allow(
        clippy::too_many_lines,
        reason = "the pre-turn crash fence resolves and revokes every deterministic local Runtime authority aggregate"
    )]
    fn retire_local_runtime_authority_without_turn(
        &mut self,
        mission: &Mission,
        previous_user_generation: u64,
        next_conversation_sequence: u64,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        let ids = LocalMissionRuntimeIds::for_mission(&mission.id, previous_user_generation);
        let workspace = match self
            .store
            .load_context_workspace(&mission.project_id, &ids.workspace_id)
        {
            Ok(workspace) => workspace,
            Err(StorageError::ScopedRecordNotFound { .. }) => return Ok(()),
            Err(error) => return Err(error.into()),
        };
        if workspace.project_id != mission.project_id
            || workspace.mission_id != mission.id
            || workspace.generation != previous_user_generation
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let recovery =
            self.latest_runtime_recovery_for_mission(&mission.project_id, &mission.id)?;
        if recovery
            .as_ref()
            .is_some_and(|recovery| recovery.worker_generation > previous_user_generation)
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let recovery =
            recovery.filter(|recovery| recovery.worker_generation == previous_user_generation);
        let mut branch = self
            .store
            .load_context_branch(&mission.project_id, &ids.branch_id)?;
        let mut lease = self
            .store
            .load_worker_lease(&mission.project_id, &ids.worker_lease_id)?;
        let mut capsule = self
            .store
            .load_context_capsule(&mission.project_id, &ids.capsule_id)?;
        let mut handle = self.store.load_worker_handle(
            &mission.project_id,
            &ids.workspace_id,
            &ids.worker_id,
        )?;
        if handle.branch_id != ids.branch_id
            || handle.lease_id != ids.worker_lease_id
            || handle.capsule_id != ids.capsule_id
            || handle.mission_id != mission.id
            || handle.generation != previous_user_generation
            || branch.workspace_id != ids.workspace_id
            || branch.generation != previous_user_generation
            || lease.workspace_id != ids.workspace_id
            || lease.worker_id != ids.worker_id
            || lease.generation != previous_user_generation
            || capsule.workspace_id != ids.workspace_id
            || capsule.worker_id != ids.worker_id
            || capsule.worker_generation != previous_user_generation
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        if let Some(recovery) = &recovery {
            if recovery.project_id != mission.project_id
                || recovery.mission_id != mission.id
                || recovery.workspace_id != ids.workspace_id
                || recovery.worker_id != ids.worker_id
                || recovery.worker_generation != previous_user_generation
            {
                return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
            }
            let checkpoint = self
                .store
                .load_context_checkpoint(&mission.project_id, &recovery.checkpoint_id)?;
            recovery.validate_for(&handle, &checkpoint, now)?;
        } else if handle.status != WorkerHandleStatus::Attached {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let already_terminal = matches!(
            (branch.status, lease.status, capsule.status, handle.status),
            (
                ContextBranchStatus::Completed | ContextBranchStatus::Merged,
                WorkerLeaseStatus::Released,
                ContextCapsuleStatus::Accepted,
                WorkerHandleStatus::Completed
            ) | (
                ContextBranchStatus::Abandoned,
                WorkerLeaseStatus::Revoked | WorkerLeaseStatus::Expired,
                ContextCapsuleStatus::Cancelled | ContextCapsuleStatus::Expired,
                WorkerHandleStatus::Cancelled | WorkerHandleStatus::Failed
            )
        );
        if already_terminal {
            return Ok(());
        }
        if !matches!(
            handle.status,
            WorkerHandleStatus::Attached | WorkerHandleStatus::Detached
        ) || branch.status != ContextBranchStatus::Active
            || lease.status != WorkerLeaseStatus::Active
            || !matches!(
                capsule.status,
                ContextCapsuleStatus::Issued | ContextCapsuleStatus::Claimed
            )
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        let expected_branch_revision = branch.revision;
        let expected_lease_revision = lease.revision;
        let expected_capsule_revision = capsule.revision;
        let expected_handle_revision = handle.revision;
        let source_digest = recovery.as_ref().map_or_else(
            || sha256(ids.workspace_id.as_str().as_bytes()),
            |recovery| sha256(recovery.id.as_str().as_bytes()),
        );
        let conflict_digest = sha256(
            format!(
                "conversation-generation-superseded:no-turn:{source_digest}:{previous_user_generation}:{next_conversation_sequence}"
            )
            .as_bytes(),
        );
        branch.abandon(&conflict_digest, now)?;
        if now >= lease.expires_at {
            lease.expire(now)?;
        } else {
            let lease_token_digest = lease.lease_token_digest.clone();
            lease.revoke(lease.generation, &lease_token_digest, now)?;
        }
        if now > capsule.expires_at {
            capsule.expire(now)?;
            handle.fail(&capsule, now)?;
        } else {
            capsule.cancel(now)?;
            handle.cancel(&capsule, now)?;
        }
        let authority_source = if recovery.is_some() {
            "runtime_recovery_without_turn"
        } else {
            "prepared_context_without_recovery"
        };
        let runtime_process_may_require_cleanup = recovery.as_ref().is_some_and(|recovery| {
            matches!(
                recovery.status,
                RuntimeRecoveryStatus::Spawned
                    | RuntimeRecoveryStatus::Healthy
                    | RuntimeRecoveryStatus::ThreadBound
                    | RuntimeRecoveryStatus::Attached
            )
        });
        self.store.retire_context_generation_authority(
            &mission.id,
            previous_user_generation,
            &branch,
            expected_branch_revision,
            &lease,
            expected_lease_revision,
            &capsule,
            expected_capsule_revision,
            &handle,
            expected_handle_revision,
            &[PendingEvent::new(
                "context.runtime_generation_authority_retired",
                serde_json::json!({
                    "missionId": mission.id,
                    "workspaceId": ids.workspace_id,
                    "workerId": ids.worker_id,
                    "runtimeRecoveryId": recovery.as_ref().map(|recovery| &recovery.id),
                    "recoveryStatus": recovery.as_ref().map(|recovery| recovery.status),
                    "runtimeTurnAttemptId": null,
                    "retiredGeneration": previous_user_generation,
                    "nextConversationSequence": next_conversation_sequence,
                    "authoritySource": authority_source,
                    "runtimeProcessMayRequireCleanup": runtime_process_may_require_cleanup,
                    "branchStatus": branch.status,
                    "leaseStatus": lease.status,
                    "capsuleStatus": capsule.status,
                    "handleStatus": handle.status,
                    "externalEffectReplayed": false,
                }),
                now,
            )],
            now,
        )?;
        Ok(())
    }

