    pub fn start_creator_work_mission(
        &mut self,
        command: StartCreatorWorkMission,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let project = self.store.load_project(&command.project_id)?;
        let mut contract = MissionContract::bootstrap(
            command.goal,
            [
                "partner.read".into(),
                "identity.resolve".into(),
                "consent.evaluate".into(),
                "partner.engage".into(),
                "creator.task.publish".into(),
                "creator.task.accept".into(),
                "deliverable.upload".into(),
                "deliverable.review".into(),
                "settlement.reserve".into(),
                "attribution.compute".into(),
                "settlement.compute".into(),
                "settlement.payout".into(),
                "outcome.review".into(),
            ],
            now,
        );
        match command.mode {
            OperatingMode::Campaign => {
                contract.mode = OperatingMode::Campaign;
                contract.cadence = None;
            }
            OperatingMode::ContinuousRelationship => {
                contract.mode = OperatingMode::ContinuousRelationship;
                contract.cadence = Some(Cadence {
                    interval_seconds: 7 * 24 * 60 * 60,
                    anchor_at: now,
                    trigger: CadenceTriggerKind::IntervalOrEvent,
                    event_topics: BTreeSet::from(["creator_work.event".into()]),
                });
            }
            _ => return Err(ApplicationError::InvalidCreatorWorkOperatingMode),
        }
        contract.valid_until = now + Duration::days(180);
        contract.non_goals = vec![
            "contact public creator candidates without explicit permission".into(),
            "pay before exact deliverable acceptance and verification".into(),
            "describe a provider funding reservation as statutory escrow".into(),
            "grant contracted usage rights from review access or provider acceptance alone".into(),
        ];
        contract.constraints = vec![Constraint::RequireApproval {
            effect_classes: vec![
                EffectClass::ExternalWrite,
                EffectClass::Spend,
                EffectClass::Payment,
            ],
        }];
        contract.forbidden_capabilities = BTreeSet::from([
            "creator.public_candidate.auto_contact".into(),
            "settlement.payout_without_acceptance".into(),
        ]);
        let mut mission = Mission::compile(
            project.tenant_id,
            command.id,
            command.project_id,
            command.title,
            contract,
            now,
        )?;
        mission.start_research(
            [Task {
                id: command.task_id,
                title: "冻结达人任务、悬赏、验收与权利合同".into(),
                status: TaskStatus::Running,
                capability: "creator.task.publish".into(),
            }],
            now,
        )?;
        self.store.create_mission_atomic(
            &mission,
            &[PendingEvent::new(
                "creator_work.mission_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "contractRevision": mission.revision,
                }),
                now,
            )],
        )?;
        Ok(mission)
    }

    pub fn start_relationship_mission(
        &mut self,
        command: StartRelationshipMission,
        now: DateTime<Utc>,
    ) -> Result<Mission, ApplicationError> {
        let project = self.store.load_project(&command.project_id)?;
        let mut contract = MissionContract::bootstrap(
            command.goal,
            [
                "webhook.ingest".into(),
                "conversation.classify".into(),
                "conversation.reply".into(),
                "conversation.handoff".into(),
                "crm.write".into(),
                "worker.manage".into(),
            ],
            now,
        );
        contract.mode = OperatingMode::ContinuousRelationship;
        contract.cadence = Some(Cadence {
            interval_seconds: 0,
            anchor_at: now,
            trigger: CadenceTriggerKind::EventDriven,
            event_topics: BTreeSet::from(["conversation.inbound".into()]),
        });
        contract.valid_until = now + Duration::days(180);
        contract.constraints = vec![Constraint::RequireApproval {
            effect_classes: vec![EffectClass::Outreach, EffectClass::ExternalWrite],
        }];
        contract.forbidden_capabilities = BTreeSet::from([
            "inbox.reply_without_conversation_guard".into(),
            "relationship.resume_without_human_evidence".into(),
        ]);
        let mut mission = Mission::compile(
            project.tenant_id,
            command.id,
            command.project_id,
            command.title,
            contract,
            now,
        )?;
        mission.start_research(
            [Task {
                id: command.task_id,
                title: "持续处理签名消息、风险分类与人工接管".into(),
                status: TaskStatus::Running,
                capability: "webhook.ingest".into(),
            }],
            now,
        )?;
        self.store.create_mission_atomic(
            &mission,
            &[PendingEvent::new(
                "relationship.mission_started",
                serde_json::json!({
                    "missionId": mission.id,
                    "contractRevision": mission.revision,
                    "mode": mission.contract.mode,
                }),
                now,
            )],
        )?;
        Ok(mission)
    }

