    /// Returns the newest integrity-checked Runtime recovery attempt for one
    /// Mission. This is an internal coordination record, not a UI projection:
    /// it intentionally retains the exact revision and thread binding needed
    /// to resume safely after a Desktop restart.
    pub fn latest_runtime_recovery_for_mission(
        &self,
        project_id: &ProjectId,
        mission_id: &MissionId,
    ) -> Result<Option<RuntimeRecoveryAttempt>, ApplicationError> {
        Ok(self
            .store
            .list_runtime_recoveries(project_id)?
            .into_iter()
            .filter(|attempt| &attempt.mission_id == mission_id)
            .max_by(|left, right| {
                (left.updated_at, left.revision, left.id.as_str()).cmp(&(
                    right.updated_at,
                    right.revision,
                    right.id.as_str(),
                ))
            }))
    }

    /// Returns the newest integrity-checked Runtime turn attempt for one
    /// Mission so a coordinator can distinguish a safe retry from an active or
    /// uncertain turn that must never be duplicated.
    pub fn latest_runtime_turn_for_mission(
        &self,
        project_id: &ProjectId,
        mission_id: &MissionId,
    ) -> Result<Option<RuntimeTurnAttempt>, ApplicationError> {
        Ok(self
            .store
            .list_runtime_turn_attempts(project_id)?
            .into_iter()
            .filter(|attempt| &attempt.scope.mission_id == mission_id)
            .max_by(|left, right| {
                (left.updated_at, left.revision, left.id.as_str()).cmp(&(
                    right.updated_at,
                    right.revision,
                    right.id.as_str(),
                ))
            }))
    }

    fn failed_runtime_recovery_for_retirement(
        &self,
        command: &RetireFailedContextRuntimeGeneration,
    ) -> Result<RuntimeRecoveryAttempt, ApplicationError> {
        self.require_runtime_turn_startup_reconciliation()?;
        let recovery = self
            .store
            .load_runtime_recovery(&command.project_id, &command.recovery_id)?;
        if recovery.revision != command.expected_recovery_revision {
            return Err(ApplicationError::RuntimeRecoveryRevisionMismatch {
                expected: command.expected_recovery_revision,
                actual: recovery.revision,
            });
        }
        if recovery.status != RuntimeRecoveryStatus::Failed {
            return Err(ApplicationError::RuntimeRecoveryNotFailed);
        }
        if self
            .store
            .load_active_runtime_turn_for_worker(
                &recovery.project_id,
                &recovery.workspace_id,
                &recovery.worker_id,
            )?
            .is_some()
        {
            return Err(ApplicationError::RuntimeGenerationHasActiveTurn);
        }
        Ok(recovery)
    }

    fn runtime_generation_retired_event(
        recovery: &RuntimeRecoveryAttempt,
        branch: &ContextBranch,
        lease: &WorkerLease,
        capsule: &ContextCapsule,
        handle: &WorkerHandle,
        next_generation: u64,
        now: DateTime<Utc>,
    ) -> PendingEvent {
        PendingEvent::new(
            "context.runtime_generation_retired",
            serde_json::json!({
                "recoveryId": recovery.id,
                "missionId": recovery.mission_id,
                "workspaceId": recovery.workspace_id,
                "workerId": recovery.worker_id,
                "retiredGeneration": recovery.worker_generation,
                "nextGeneration": next_generation,
                "failureCount": recovery.failures.len(),
                "branchStatus": branch.status,
                "leaseStatus": lease.status,
                "capsuleStatus": capsule.status,
                "handleStatus": handle.status,
            }),
            now,
        )
    }

    /// Closes a definitively failed Runtime generation as an atomic authority
    /// revocation. It never reattaches the old Worker and never converts the
    /// failure into a successful capsule result.
    pub fn retire_failed_context_runtime_generation(
        &mut self,
        command: &RetireFailedContextRuntimeGeneration,
        now: DateTime<Utc>,
    ) -> Result<RetiredContextRuntimeGeneration, ApplicationError> {
        let recovery = self.failed_runtime_recovery_for_retirement(command)?;

        let mut handle = self.store.load_worker_handle(
            &recovery.project_id,
            &recovery.workspace_id,
            &recovery.worker_id,
        )?;
        let mut branch = self
            .store
            .load_context_branch(&recovery.project_id, &handle.branch_id)?;
        let mut lease = self
            .store
            .load_worker_lease(&recovery.project_id, &handle.lease_id)?;
        let mut capsule = self
            .store
            .load_context_capsule(&recovery.project_id, &handle.capsule_id)?;
        require_context_branch_revision(&branch, command.expected_branch_revision)?;
        require_worker_lease_revision(&lease, command.expected_lease_revision)?;
        if capsule.revision != command.expected_capsule_revision {
            return Err(ApplicationError::ContextCapsuleRevisionMismatch {
                expected: command.expected_capsule_revision,
                actual: capsule.revision,
            });
        }
        require_context_worker_handle_revision(&handle, command.expected_handle_revision)?;
        if handle.status != WorkerHandleStatus::Detached
            || !matches!(
                capsule.status,
                ContextCapsuleStatus::Issued | ContextCapsuleStatus::Claimed
            )
            || branch.status != ContextBranchStatus::Active
            || lease.status != WorkerLeaseStatus::Active
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }

        let conflict_digest = sha256(
            format!(
                "runtime-recovery-exhausted:{}:{}:{}",
                recovery.id, recovery.revision, recovery.worker_generation
            )
            .as_bytes(),
        );
        let expected_branch_revision = branch.revision;
        let expected_lease_revision = lease.revision;
        let expected_capsule_revision = capsule.revision;
        let expected_handle_revision = handle.revision;
        branch.abandon(&conflict_digest, now)?;
        let expired = now > capsule.expires_at;
        if now >= lease.expires_at {
            lease.expire(now)?;
        } else {
            let lease_token_digest = lease.lease_token_digest.clone();
            lease.revoke(lease.generation, &lease_token_digest, now)?;
        }
        if expired {
            capsule.expire(now)?;
            handle.fail(&capsule, now)?;
        } else {
            capsule.cancel(now)?;
            handle.cancel(&capsule, now)?;
        }
        let next_generation = recovery
            .worker_generation
            .checked_add(1)
            .ok_or(ContextError::RevisionOverflow)?;
        self.store.retire_failed_runtime_generation(
            &recovery,
            &branch,
            expected_branch_revision,
            &lease,
            expected_lease_revision,
            &capsule,
            expected_capsule_revision,
            &handle,
            expected_handle_revision,
            &[Self::runtime_generation_retired_event(
                &recovery,
                &branch,
                &lease,
                &capsule,
                &handle,
                next_generation,
                now,
            )],
            now,
        )?;
        Ok(RetiredContextRuntimeGeneration {
            mission_id: recovery.mission_id,
            workspace_id: recovery.workspace_id,
            worker_id: recovery.worker_id,
            retired_generation: recovery.worker_generation,
            next_generation,
            branch_status: branch.status,
            lease_status: lease.status,
            capsule_status: capsule.status,
            handle_status: handle.status,
        })
    }

    fn runtime_generation_authority(
        &self,
        recovery: &RuntimeRecoveryAttempt,
    ) -> Result<ContextRuntimeGenerationAuthority, ApplicationError> {
        let handle = self.store.load_worker_handle(
            &recovery.project_id,
            &recovery.workspace_id,
            &recovery.worker_id,
        )?;
        let branch = self
            .store
            .load_context_branch(&recovery.project_id, &handle.branch_id)?;
        let lease = self
            .store
            .load_worker_lease(&recovery.project_id, &handle.lease_id)?;
        let capsule = self
            .store
            .load_context_capsule(&recovery.project_id, &handle.capsule_id)?;
        if handle.project_id != recovery.project_id
            || handle.mission_id != recovery.mission_id
            || handle.workspace_id != recovery.workspace_id
            || handle.worker_id != recovery.worker_id
            || handle.generation != recovery.worker_generation
            || branch.project_id != recovery.project_id
            || branch.workspace_id != recovery.workspace_id
            || branch.generation != recovery.worker_generation
            || lease.project_id != recovery.project_id
            || lease.workspace_id != recovery.workspace_id
            || lease.worker_id != recovery.worker_id
            || lease.generation != recovery.worker_generation
            || capsule.project_id != recovery.project_id
            || capsule.workspace_id != recovery.workspace_id
            || capsule.worker_id != recovery.worker_id
            || capsule.worker_generation != recovery.worker_generation
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        Ok(ContextRuntimeGenerationAuthority {
            branch,
            lease,
            capsule,
            handle,
        })
    }

    /// Idempotently closes a definitively failed local Mission Runtime
    /// generation. The coordinator names only the failed recovery revision;
    /// this method resolves and fences every authority-bearing aggregate under
    /// one Application-layer transaction instead of exposing raw CAS revisions
    /// to the Desktop UI.
    pub fn ensure_failed_local_mission_runtime_generation_retired(
        &mut self,
        command: &EnsureFailedLocalMissionRuntimeGenerationRetired,
        now: DateTime<Utc>,
    ) -> Result<RetiredContextRuntimeGeneration, ApplicationError> {
        self.require_runtime_turn_startup_reconciliation()?;
        let recovery = self
            .store
            .load_runtime_recovery(&command.project_id, &command.recovery_id)?;
        if recovery.revision != command.expected_recovery_revision {
            return Err(ApplicationError::RuntimeRecoveryRevisionMismatch {
                expected: command.expected_recovery_revision,
                actual: recovery.revision,
            });
        }
        if recovery.mission_id != command.mission_id {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }
        if recovery.status != RuntimeRecoveryStatus::Failed {
            return Err(ApplicationError::RuntimeRecoveryNotFailed);
        }
        if self
            .store
            .load_active_runtime_turn_for_worker(
                &recovery.project_id,
                &recovery.workspace_id,
                &recovery.worker_id,
            )?
            .is_some()
        {
            return Err(ApplicationError::RuntimeGenerationHasActiveTurn);
        }

        let authority = self.runtime_generation_authority(&recovery)?;

        let next_generation = recovery
            .worker_generation
            .checked_add(1)
            .ok_or(ContextError::RevisionOverflow)?;
        let terminal_pair = matches!(
            (authority.capsule.status, authority.handle.status),
            (
                ContextCapsuleStatus::Cancelled,
                WorkerHandleStatus::Cancelled
            ) | (ContextCapsuleStatus::Expired, WorkerHandleStatus::Failed)
        );
        if authority.branch.status == ContextBranchStatus::Abandoned
            && matches!(
                authority.lease.status,
                WorkerLeaseStatus::Revoked | WorkerLeaseStatus::Expired
            )
            && terminal_pair
        {
            return Ok(RetiredContextRuntimeGeneration {
                mission_id: recovery.mission_id,
                workspace_id: recovery.workspace_id,
                worker_id: recovery.worker_id,
                retired_generation: recovery.worker_generation,
                next_generation,
                branch_status: authority.branch.status,
                lease_status: authority.lease.status,
                capsule_status: authority.capsule.status,
                handle_status: authority.handle.status,
            });
        }
        if authority.handle.status != WorkerHandleStatus::Detached
            || authority.branch.status != ContextBranchStatus::Active
            || authority.lease.status != WorkerLeaseStatus::Active
            || !matches!(
                authority.capsule.status,
                ContextCapsuleStatus::Issued | ContextCapsuleStatus::Claimed
            )
        {
            return Err(ApplicationError::RuntimeRecoveryScopeMismatch);
        }

        self.retire_failed_context_runtime_generation(
            &RetireFailedContextRuntimeGeneration {
                project_id: command.project_id.clone(),
                recovery_id: command.recovery_id.clone(),
                expected_recovery_revision: command.expected_recovery_revision,
                expected_branch_revision: authority.branch.revision,
                expected_lease_revision: authority.lease.revision,
                expected_capsule_revision: authority.capsule.revision,
                expected_handle_revision: authority.handle.revision,
            },
            now,
        )
    }

    #[allow(
        clippy::too_many_lines,
        reason = "dispatch validates and freezes one complete manifest, worker, recovery, process, thread, and durable-write authority closure"
    )]
    pub fn dispatch_context_runtime_turn(
        &mut self,
        managed: &mut ManagedContextRuntime,
        command: DispatchContextRuntimeTurn,
        envelope: &RuntimeContextEnvelope,
        now: DateTime<Utc>,
    ) -> Result<ContextRuntimeTurnDispatchOutcome, ApplicationError> {
        self.require_runtime_turn_startup_reconciliation()?;
        let manifest = self
            .store
            .load_context_assembly_manifest(&command.project_id, &command.assembly_id)?;
        if manifest.revision != command.expected_assembly_revision {
            return Err(ApplicationError::RuntimeTurnAssemblyRevisionMismatch {
                expected: command.expected_assembly_revision,
                actual: manifest.revision,
            });
        }
        if manifest.project_id != command.project_id
            || manifest.workspace_id != command.workspace_id
            || manifest.id != command.assembly_id
            || manifest.status != ContextAssemblyStatus::Ready
        {
            return Err(ApplicationError::RuntimeTurnScopeMismatch);
        }
        manifest.validate_dispatchable()?;
        envelope.validate_against(&manifest)?;
        if self
            .store
            .load_active_runtime_turn_for_worker(
                &manifest.project_id,
                &manifest.workspace_id,
                &manifest.worker_id,
            )?
            .is_some()
        {
            return Err(ApplicationError::RuntimeTurnAlreadyActive);
        }

        let handle = self.store.load_worker_handle(
            &manifest.project_id,
            &manifest.workspace_id,
            &manifest.worker_id,
        )?;
        if handle.revision != command.expected_handle_revision {
            return Err(ApplicationError::ContextWorkerHandleRevisionMismatch {
                expected: command.expected_handle_revision,
                actual: handle.revision,
            });
        }
        let recovery = self
            .store
            .load_runtime_recovery(&manifest.project_id, &managed.recovery.id)?;
        if recovery.revision != command.expected_recovery_revision {
            return Err(ApplicationError::RuntimeRecoveryRevisionMismatch {
                expected: command.expected_recovery_revision,
                actual: recovery.revision,
            });
        }
        let runtime_mapping_digest = runtime_mapping_base_digest(&managed.mapping)?;
        let tokenizer_profile = manifest
            .tokenizer_profile
            .as_ref()
            .ok_or(ApplicationError::RuntimeTurnTokenizerMismatch)?;
        if managed.mapping.runtime_model != tokenizer_profile.model
            || managed.mapping.runtime_model_provider != tokenizer_profile.provider
        {
            return Err(ApplicationError::RuntimeTurnTokenizerMismatch);
        }
        let runtime_instance_digest = recovery
            .runtime_instance_digest
            .clone()
            .ok_or(ApplicationError::RuntimeTurnScopeMismatch)?;
        let runtime_thread_id = recovery
            .runtime_thread_id
            .clone()
            .ok_or(ApplicationError::RuntimeTurnScopeMismatch)?;
        if managed.recovery != recovery
            || managed.handle != handle
            || handle.status != WorkerHandleStatus::Attached
            || handle.attachment_epoch != command.attachment_epoch
            || recovery.status != RuntimeRecoveryStatus::Attached
            || recovery.target_attachment_epoch != command.attachment_epoch
            || managed.mapping.project_id != manifest.project_id.as_str()
            || managed.mapping.mission_id != manifest.mission_id.as_str()
            || managed.mapping.runtime_generation != command.attachment_epoch
            || managed.mapping.runtime_instance_digest != runtime_instance_digest
            || managed.mapping.runtime_thread_id != runtime_thread_id
            || managed.mapping.runtime_turn_id.is_some()
            || managed.runtime.instance_digest() != runtime_instance_digest
            || handle.runtime_mapping_digest.as_deref() != Some(runtime_mapping_digest.as_str())
            || recovery.runtime_mapping_digest.as_deref() != Some(runtime_mapping_digest.as_str())
            || recovery.worker_generation != manifest.worker_generation
            || recovery.checkpoint_id != manifest.checkpoint_id
            || recovery.checkpoint_digest != manifest.checkpoint_digest
        {
            return Err(ApplicationError::RuntimeTurnScopeMismatch);
        }
        let prompt_digest = manifest
            .prompt_digest
            .clone()
            .ok_or(ApplicationError::RuntimeTurnScopeMismatch)?;
        let prompt = envelope.render_prompt()?;
        let scope = RuntimeTurnScope {
            tenant_id: manifest.tenant_id.clone(),
            project_id: manifest.project_id.clone(),
            mission_id: manifest.mission_id.clone(),
            workspace_id: manifest.workspace_id.clone(),
            capsule_id: manifest.capsule_id.clone(),
            capsule_revision: manifest.capsule_revision,
            capsule_authority_digest: manifest.capsule_authority_digest.clone(),
            branch_id: manifest.branch_id.clone(),
            branch_revision: manifest.branch_revision,
            worker_id: manifest.worker_id.clone(),
            worker_generation: manifest.worker_generation,
            worker_lease_id: manifest.worker_lease_id.clone(),
            worker_lease_revision: manifest.worker_lease_revision,
            attachment_epoch: command.attachment_epoch,
            assembly_id: manifest.id.clone(),
            assembly_revision: manifest.revision,
            assembly_manifest_digest: manifest.digest()?,
            assembly_input_digest: manifest.input_digest.clone(),
            prompt_digest,
            checkpoint_id: manifest.checkpoint_id.clone(),
            checkpoint_digest: manifest.checkpoint_digest.clone(),
            recovery_id: recovery.id.clone(),
            recovery_revision: recovery.revision,
            runtime_instance_digest,
            runtime_mapping_digest,
            runtime_thread_id: runtime_thread_id.clone(),
            runtime_thread_id_digest: sha256(runtime_thread_id.as_bytes()),
        };
        let mut attempt = RuntimeTurnAttempt::prepare(command.id, scope, now)?;
        self.store.insert_runtime_turn_attempt(&attempt)?;
        let expected_revision = attempt.revision;
        attempt.begin_dispatch(now)?;
        self.store
            .update_runtime_turn_attempt(&attempt, expected_revision)?;

        match managed.runtime.start_mapped_turn(
            &managed.mapping,
            attempt.id.as_str(),
            &prompt,
            command.response_timeout,
        ) {
            Ok(dispatch) => {
                let mapping_matches = dispatch.mapping.project_id
                    == attempt.scope.project_id.as_str()
                    && dispatch.mapping.mission_id == attempt.scope.mission_id.as_str()
                    && dispatch.mapping.runtime_generation == attempt.scope.attachment_epoch
                    && dispatch.mapping.runtime_instance_digest
                        == attempt.scope.runtime_instance_digest
                    && dispatch.mapping.runtime_thread_id == attempt.scope.runtime_thread_id
                    && runtime_mapping_base_digest(&dispatch.mapping)?
                        == attempt.scope.runtime_mapping_digest;
                let Some(runtime_turn_id) = dispatch.mapping.runtime_turn_id.clone() else {
                    let expected_revision = attempt.revision;
                    attempt.freeze_uncertain(
                        RuntimeTurnFailureClass::Protocol,
                        sha256(b"runtime-turn-dispatch-returned-no-turn-id"),
                        now,
                    )?;
                    self.store
                        .update_runtime_turn_attempt(&attempt, expected_revision)?;
                    return Ok(ContextRuntimeTurnDispatchOutcome {
                        attempt,
                        disposition: RuntimeTurnDispatchDisposition::Uncertain,
                    });
                };
                if !mapping_matches {
                    let expected_revision = attempt.revision;
                    attempt.freeze_uncertain(
                        RuntimeTurnFailureClass::Protocol,
                        sha256(b"runtime-turn-dispatch-mapping-mismatch"),
                        now,
                    )?;
                    self.store
                        .update_runtime_turn_attempt(&attempt, expected_revision)?;
                    return Ok(ContextRuntimeTurnDispatchOutcome {
                        attempt,
                        disposition: RuntimeTurnDispatchDisposition::Uncertain,
                    });
                }
                managed.mapping = dispatch.mapping;
                let expected_revision = attempt.revision;
                attempt.accept_dispatch(
                    runtime_turn_id,
                    dispatch.request_digest,
                    dispatch.response_digest,
                    now,
                )?;
                self.store
                    .update_runtime_turn_attempt(&attempt, expected_revision)?;
                Ok(ContextRuntimeTurnDispatchOutcome {
                    attempt,
                    disposition: RuntimeTurnDispatchDisposition::Running,
                })
            }
            Err(error) => {
                let (class, definitive) = classify_runtime_turn_dispatch_error(&error);
                let expected_revision = attempt.revision;
                attempt.fail_dispatch(
                    class,
                    sha256(format!("{error:?}").as_bytes()),
                    definitive,
                    now,
                )?;
                self.store
                    .update_runtime_turn_attempt(&attempt, expected_revision)?;
                Ok(ContextRuntimeTurnDispatchOutcome {
                    disposition: if definitive {
                        RuntimeTurnDispatchDisposition::Failed
                    } else {
                        RuntimeTurnDispatchDisposition::Uncertain
                    },
                    attempt,
                })
            }
        }
    }

    #[allow(
        clippy::too_many_lines,
        reason = "observation keeps one exact Runtime event, approval, terminal, uncertainty, and durable evidence boundary"
    )]
    pub fn observe_context_runtime_turn(
        &mut self,
        managed: &mut ManagedContextRuntime,
        command: &ObserveContextRuntimeTurn,
        now: DateTime<Utc>,
    ) -> Result<ContextRuntimeTurnObservation, ApplicationError> {
        self.require_runtime_turn_startup_reconciliation()?;
        let mut attempt = self.load_runtime_turn_at_revision(
            &command.project_id,
            &command.id,
            command.expected_revision,
        )?;
        self.validate_managed_runtime_turn(managed, &attempt, now, false)?;
        let event = match managed
            .runtime
            .next_mapped_turn_event(&managed.mapping, command.event_timeout)
        {
            Ok(event) => event,
            Err(AdapterError::NextEventTimedOut) => {
                return Ok(ContextRuntimeTurnObservation {
                    attempt,
                    kind: ContextRuntimeTurnObservationKind::NoEvent,
                    local_approval_request: None,
                    agent_message_delta: None,
                    agent_message: None,
                });
            }
            Err(error) => {
                if attempt.status != RuntimeTurnStatus::Uncertain {
                    let expected_revision = attempt.revision;
                    attempt.freeze_uncertain(
                        classify_runtime_turn_stream_error(&error),
                        sha256(format!("{error:?}").as_bytes()),
                        now,
                    )?;
                    self.store
                        .update_runtime_turn_attempt(&attempt, expected_revision)?;
                }
                return Ok(ContextRuntimeTurnObservation {
                    attempt,
                    kind: ContextRuntimeTurnObservationKind::Uncertain,
                    local_approval_request: None,
                    agent_message_delta: None,
                    agent_message: None,
                });
            }
        };
        let agent_message = event.agent_message;
        let agent_message_delta = event.agent_message_delta;
        let mut approval_request = event.approval_request;
        let observed_kind = event.kind.clone();
        let persisted_deltas = if agent_message.is_some() || agent_message_delta.is_some() {
            self.store
                .load_runtime_turn_private_text_deltas(&attempt.scope.project_id, &attempt.id)?
        } else {
            Vec::new()
        };
        if let Some(message) = agent_message.as_ref() {
            let streamed_body = Zeroizing::new(
                persisted_deltas
                    .iter()
                    .filter(|delta| delta.item_id_digest == message.item_id_digest)
                    .map(|delta| delta.delta.as_str())
                    .collect::<String>(),
            );
            if !streamed_body.is_empty() && streamed_body.as_str() != message.as_str() {
                attempt.freeze_uncertain(
                    RuntimeTurnFailureClass::Protocol,
                    event.event_digest,
                    now,
                )?;
                self.store
                    .update_runtime_turn_attempt(&attempt, command.expected_revision)?;
                managed.mapping.runtime_turn_id = None;
                return Ok(ContextRuntimeTurnObservation {
                    attempt,
                    kind: ContextRuntimeTurnObservationKind::Uncertain,
                    local_approval_request: None,
                    agent_message_delta: None,
                    agent_message: None,
                });
            }
        }
        match &event.kind {
            MappedTurnEventKind::TurnStarted => attempt.observe(
                RuntimeTurnObservedKind::TurnStarted,
                event.event_digest.clone(),
                now,
            )?,
            MappedTurnEventKind::ItemStarted => attempt.observe(
                RuntimeTurnObservedKind::ItemStarted,
                event.event_digest.clone(),
                now,
            )?,
            MappedTurnEventKind::AgentMessageDelta => attempt.observe(
                RuntimeTurnObservedKind::AgentMessageDelta,
                event.event_digest.clone(),
                now,
            )?,
            MappedTurnEventKind::ItemCompleted => attempt.observe(
                RuntimeTurnObservedKind::ItemCompleted,
                event.event_digest.clone(),
                now,
            )?,
            MappedTurnEventKind::TurnCompleted(status) => attempt.observe(
                match status {
                    RuntimeTurnCompletionStatus::Completed => RuntimeTurnObservedKind::Completed,
                    RuntimeTurnCompletionStatus::Interrupted => {
                        RuntimeTurnObservedKind::Interrupted
                    }
                    RuntimeTurnCompletionStatus::Failed => RuntimeTurnObservedKind::Failed,
                },
                event.event_digest.clone(),
                now,
            )?,
            MappedTurnEventKind::LocalApprovalRequested(_) => {
                if attempt.status == RuntimeTurnStatus::Running {
                    let request = approval_request
                        .as_ref()
                        .ok_or(ApplicationError::RuntimeTurnApprovalMismatch)?;
                    if request.request_digest != event.event_digest {
                        return Err(ApplicationError::RuntimeTurnApprovalMismatch);
                    }
                    attempt.request_local_approval(request.request_digest.clone(), now)?;
                } else {
                    approval_request = None;
                    attempt.observe(
                        RuntimeTurnObservedKind::Diagnostic,
                        event.event_digest.clone(),
                        now,
                    )?;
                }
            }
            MappedTurnEventKind::Diagnostic | MappedTurnEventKind::Other => attempt.observe(
                RuntimeTurnObservedKind::Diagnostic,
                event.event_digest.clone(),
                now,
            )?,
        }
        let private_text_delta = agent_message_delta
            .as_ref()
            .map(|delta| {
                let previous = persisted_deltas
                    .iter()
                    .rfind(|candidate| candidate.item_id_digest == delta.item_id_digest);
                RuntimeTurnPrivateTextDelta::capture(
                    &attempt,
                    delta.item_id_digest.clone(),
                    delta.as_str(),
                    previous,
                )
            })
            .transpose()?;
        let private_message = agent_message
            .as_ref()
            .map(|message| {
                RuntimeTurnPrivateMessage::capture_for_item(
                    &attempt,
                    message.item_id_digest.clone(),
                    message.as_str(),
                )
            })
            .transpose()?;
        let expected_revision = command.expected_revision;
        if let Some(delta) = &private_text_delta {
            self.store
                .update_runtime_turn_attempt_with_private_text_delta(
                    &attempt,
                    expected_revision,
                    delta,
                )?;
        } else if let Some(message) = &private_message {
            self.store
                .update_runtime_turn_attempt_with_private_message(
                    &attempt,
                    expected_revision,
                    message,
                )?;
        } else {
            self.store
                .update_runtime_turn_attempt(&attempt, expected_revision)?;
        }
        if attempt.status.is_terminal() {
            managed.mapping.runtime_turn_id = None;
        }
        Ok(ContextRuntimeTurnObservation {
            attempt,
            kind: ContextRuntimeTurnObservationKind::Event(observed_kind),
            local_approval_request: approval_request,
            agent_message_delta,
            agent_message,
        })
    }

    pub fn respond_context_runtime_local_approval(
        &mut self,
        managed: &mut ManagedContextRuntime,
        command: &RespondContextRuntimeLocalApproval,
        now: DateTime<Utc>,
    ) -> Result<RuntimeTurnAttempt, ApplicationError> {
        self.require_runtime_turn_startup_reconciliation()?;
        let mut attempt = self.load_runtime_turn_at_revision(
            &command.project_id,
            &command.id,
            command.expected_revision,
        )?;
        self.validate_managed_runtime_turn(managed, &attempt, now, command.approved)?;
        if attempt.pending_approval_request_digest.as_deref()
            != Some(command.request.request_digest.as_str())
        {
            return Err(ApplicationError::RuntimeTurnApprovalMismatch);
        }
        let decision_digest = sha256(
            serde_json::to_vec(&serde_json::json!({
                "attemptId": attempt.id,
                "attemptRevision": attempt.revision,
                "requestDigest": command.request.request_digest,
                "approved": command.approved,
            }))?
            .as_slice(),
        );
        let expected_revision = attempt.revision;
        attempt.begin_local_approval_response(
            &command.request.request_digest,
            decision_digest,
            now,
        )?;
        self.store
            .update_runtime_turn_attempt(&attempt, expected_revision)?;
        match managed.runtime.respond_to_mapped_turn_approval(
            &managed.mapping,
            &command.request,
            command.approved,
        ) {
            Ok(response_digest) => {
                let expected_revision = attempt.revision;
                attempt.finish_local_approval_response(response_digest, now)?;
                self.store
                    .update_runtime_turn_attempt(&attempt, expected_revision)?;
            }
            Err(error) => {
                let expected_revision = attempt.revision;
                attempt.freeze_uncertain(
                    RuntimeTurnFailureClass::ApprovalResponseUncertain,
                    sha256(format!("{error:?}").as_bytes()),
                    now,
                )?;
                self.store
                    .update_runtime_turn_attempt(&attempt, expected_revision)?;
            }
        }
        Ok(attempt)
    }

    pub fn interrupt_context_runtime_turn(
        &mut self,
        managed: &mut ManagedContextRuntime,
        command: &InterruptContextRuntimeTurn,
        now: DateTime<Utc>,
    ) -> Result<RuntimeTurnAttempt, ApplicationError> {
        self.require_runtime_turn_startup_reconciliation()?;
        let mut attempt = self.load_runtime_turn_at_revision(
            &command.project_id,
            &command.id,
            command.expected_revision,
        )?;
        self.validate_managed_runtime_turn(managed, &attempt, now, false)?;
        let expected_revision = attempt.revision;
        attempt.begin_interrupt(now)?;
        self.store
            .update_runtime_turn_attempt(&attempt, expected_revision)?;
        match managed
            .runtime
            .interrupt_mapped_turn(&managed.mapping, command.response_timeout)
        {
            Ok(receipt) => {
                let expected_revision = attempt.revision;
                attempt.confirm_interrupt(receipt.request_digest, receipt.response_digest, now)?;
                self.store
                    .update_runtime_turn_attempt(&attempt, expected_revision)?;
            }
            Err(error) => {
                let expected_revision = attempt.revision;
                attempt.freeze_uncertain(
                    RuntimeTurnFailureClass::InterruptUncertain,
                    sha256(format!("{error:?}").as_bytes()),
                    now,
                )?;
                self.store
                    .update_runtime_turn_attempt(&attempt, expected_revision)?;
            }
        }
        Ok(attempt)
    }

    pub fn fence_orphaned_context_runtime_turn(
        &mut self,
        command: &FenceOrphanedContextRuntimeTurn,
        now: DateTime<Utc>,
    ) -> Result<RuntimeTurnAttempt, ApplicationError> {
        let mut attempt = self.load_runtime_turn_at_revision(
            &command.project_id,
            &command.id,
            command.expected_revision,
        )?;
        let expected_revision = attempt.revision;
        if attempt.fence_after_coordinator_restart(now)?
            == RuntimeTurnRestartDisposition::AlreadySafe
        {
            return Ok(attempt);
        }
        self.store
            .update_runtime_turn_attempt(&attempt, expected_revision)?;
        Ok(attempt)
    }

    pub fn runtime_turn_attempt(
        &self,
        project_id: &ProjectId,
        id: &RuntimeTurnAttemptId,
    ) -> Result<RuntimeTurnAttempt, ApplicationError> {
        Ok(self.store.load_runtime_turn_attempt(project_id, id)?)
    }

    pub fn latest_runtime_turn_private_message(
        &self,
        project_id: &ProjectId,
        id: &RuntimeTurnAttemptId,
    ) -> Result<Option<RuntimeTurnPrivateMessage>, ApplicationError> {
        Ok(self
            .store
            .load_latest_runtime_turn_private_message(project_id, id)?)
    }

    pub fn runtime_turn_private_text_deltas(
        &self,
        project_id: &ProjectId,
        id: &RuntimeTurnAttemptId,
    ) -> Result<Vec<RuntimeTurnPrivateTextDelta>, ApplicationError> {
        Ok(self
            .store
            .load_runtime_turn_private_text_deltas(project_id, id)?)
    }

    fn load_runtime_turn_at_revision(
        &self,
        project_id: &ProjectId,
        id: &RuntimeTurnAttemptId,
        expected_revision: u64,
    ) -> Result<RuntimeTurnAttempt, ApplicationError> {
        let attempt = self.store.load_runtime_turn_attempt(project_id, id)?;
        if attempt.revision != expected_revision {
            return Err(ApplicationError::RuntimeTurnRevisionMismatch {
                expected: expected_revision,
                actual: attempt.revision,
            });
        }
        Ok(attempt)
    }

    fn validate_managed_runtime_turn(
        &self,
        managed: &ManagedContextRuntime,
        attempt: &RuntimeTurnAttempt,
        now: DateTime<Utc>,
        require_unexpired_authority: bool,
    ) -> Result<(), ApplicationError> {
        let scope = &attempt.scope;
        let handle = self.store.load_worker_handle(
            &scope.project_id,
            &scope.workspace_id,
            &scope.worker_id,
        )?;
        let recovery = self
            .store
            .load_runtime_recovery(&scope.project_id, &scope.recovery_id)?;
        let capsule = self
            .store
            .load_context_capsule(&scope.project_id, &scope.capsule_id)?;
        let lease = self
            .store
            .load_worker_lease(&scope.project_id, &scope.worker_lease_id)?;
        if managed.handle != handle
            || managed.recovery != recovery
            || handle.status != WorkerHandleStatus::Attached
            || handle.revision != managed.handle.revision
            || handle.attachment_epoch != scope.attachment_epoch
            || handle.runtime_mapping_digest.as_deref()
                != Some(scope.runtime_mapping_digest.as_str())
            || recovery.status != RuntimeRecoveryStatus::Attached
            || recovery.revision != scope.recovery_revision
            || recovery.runtime_instance_digest.as_deref()
                != Some(scope.runtime_instance_digest.as_str())
            || recovery.runtime_thread_id.as_deref() != Some(scope.runtime_thread_id.as_str())
            || recovery.runtime_mapping_digest.as_deref()
                != Some(scope.runtime_mapping_digest.as_str())
            || managed.mapping.project_id != scope.project_id.as_str()
            || managed.mapping.mission_id != scope.mission_id.as_str()
            || managed.mapping.runtime_generation != scope.attachment_epoch
            || managed.mapping.runtime_instance_digest != scope.runtime_instance_digest
            || managed.mapping.runtime_thread_id != scope.runtime_thread_id
            || managed.mapping.runtime_turn_id.as_deref() != attempt.runtime_turn_id.as_deref()
            || runtime_mapping_base_digest(&managed.mapping)? != scope.runtime_mapping_digest
            || managed.runtime.instance_digest() != scope.runtime_instance_digest
            || capsule.revision != scope.capsule_revision
            || capsule.authority_digest != scope.capsule_authority_digest
            || lease.revision != scope.worker_lease_revision
            || require_unexpired_authority
                && (now > capsule.expires_at
                    || now > lease.expires_at
                    || capsule.status != ContextCapsuleStatus::Claimed
                    || lease.status != hartevo_domain_kernel::WorkerLeaseStatus::Active)
        {
            return Err(
                if require_unexpired_authority
                    && (now > capsule.expires_at || now > lease.expires_at)
                {
                    ApplicationError::RuntimeTurnAuthorityExpired
                } else {
                    ApplicationError::RuntimeTurnScopeMismatch
                },
            );
        }
        Ok(())
    }

    #[allow(
        clippy::too_many_arguments,
        clippy::too_many_lines,
        reason = "the coordinator preserves every durable boundary around one spawned runtime generation"
    )]
    fn run_prepared_runtime_recovery(
        &mut self,
        mut attempt: RuntimeRecoveryAttempt,
        mut handle: WorkerHandle,
        mut mailbox: WorkerMailbox,
        runtime_command: &RuntimeCommand,
        workspace_root: &Path,
        model: Option<&str>,
        resume_thread_id: Option<&str>,
        health_timeout: StdDuration,
        thread_timeout: StdDuration,
        now: DateTime<Utc>,
    ) -> Result<ManagedContextRuntime, ApplicationError> {
        let launch_token = generate_runtime_launch_token(runtime_command)?;
        let runtime_launch = prepare_runtime_launch(runtime_command, &launch_token)?;
        let mut process_claim = RuntimeProcessClaim::prepare(
            &attempt,
            runtime_launch.program_sha256().to_owned(),
            launch_token,
            runtime_launch
                .executable_path()
                .to_string_lossy()
                .into_owned(),
            runtime_launch.executable_path_digest().to_owned(),
            now,
        )?;
        self.store.prepare_runtime_process_claim(
            &process_claim,
            &[PendingEvent::new(
                "context.runtime_process_launch_prepared",
                serde_json::json!({
                    "runtimeRecoveryId": attempt.id,
                    "missionId": attempt.mission_id,
                    "workspaceId": attempt.workspace_id,
                    "workerId": attempt.worker_id,
                    "workerGeneration": attempt.worker_generation,
                    "processAttempt": attempt.process_attempt,
                    "runtimeConfigDigest": attempt.runtime_config_digest,
                    "programSha256": process_claim.program_sha256,
                    "launchTokenDigest": process_claim.launch_token_digest,
                    "launchExecutablePathDigest": process_claim.launch_executable_path_digest,
                }),
                now,
            )],
            now,
        )?;
        let mut runtime = match StdioRuntime::spawn_prepared(runtime_command, &runtime_launch) {
            Ok(runtime) => runtime,
            Err(error) => {
                self.reconcile_runtime_process_claim(
                    &mut process_claim,
                    "context.runtime_process_spawn_reconciled",
                    now,
                )?;
                self.persist_runtime_process_failure(
                    &mut attempt,
                    RuntimeRecoveryFailureClass::Spawn,
                    &error,
                    now,
                )?;
                return Err(ApplicationError::Runtime(error));
            }
        };
        let expected_revision = attempt.revision;
        let expected_claim_revision = process_claim.revision;
        attempt.mark_spawned(runtime.instance_digest().to_owned(), now)?;
        process_claim.mark_spawned(
            RuntimeProcessIdentity {
                process_id: runtime.process_identity().process_id,
                started_at_epoch_seconds: runtime.process_identity().started_at_epoch_seconds,
                executable_path_digest: runtime.process_identity().executable_path_digest.clone(),
                runtime_instance_digest: runtime.process_identity().runtime_instance_digest.clone(),
            },
            now,
        )?;
        let process_identity_digest = process_claim
            .identity
            .as_ref()
            .map(runtime_process_identity_digest)
            .ok_or(ApplicationError::RuntimeRecoveryScopeMismatch)?;
        self.store.mark_runtime_process_spawned(
            &attempt,
            expected_revision,
            &process_claim,
            expected_claim_revision,
            &[PendingEvent::new(
                "context.runtime_recovery_spawned",
                serde_json::json!({
                    "runtimeRecoveryId": attempt.id,
                    "missionId": attempt.mission_id,
                    "workspaceId": attempt.workspace_id,
                    "workerId": attempt.worker_id,
                    "workerGeneration": attempt.worker_generation,
                    "processAttempt": attempt.process_attempt,
                    "runtimeInstanceDigest": attempt.runtime_instance_digest,
                    "launchTokenDigest": process_claim.launch_token_digest,
                    "launchExecutablePathDigest": process_claim.launch_executable_path_digest,
                    "processIdentityDigest": process_identity_digest,
                    "recoveryRevision": attempt.revision,
                    "processClaimRevision": process_claim.revision,
                }),
                now,
            )],
            now,
        )?;

        let health = match runtime.health_check(health_timeout) {
            Ok(health) => health,
            Err(error) => {
                self.shutdown_runtime_process_claim(
                    runtime,
                    &mut process_claim,
                    "context.runtime_process_health_failure_cleaned",
                    now,
                )?;
                self.persist_runtime_process_failure(
                    &mut attempt,
                    RuntimeRecoveryFailureClass::Health,
                    &error,
                    now,
                )?;
                return Err(ApplicationError::Runtime(error));
            }
        };
        let expected_revision = attempt.revision;
        attempt.confirm_health(health.evidence_digest(), now)?;
        self.persist_runtime_recovery_transition(
            &attempt,
            expected_revision,
            "context.runtime_recovery_healthy",
            now,
        )?;

        let mapping_result = if let Some(thread_id) = resume_thread_id {
            runtime.resume_mapped_thread(
                attempt.project_id.as_str(),
                attempt.mission_id.as_str(),
                attempt.target_attachment_epoch,
                thread_id,
                workspace_root,
                thread_timeout,
            )
        } else {
            runtime.start_mapped_thread(
                attempt.project_id.as_str(),
                attempt.mission_id.as_str(),
                attempt.target_attachment_epoch,
                workspace_root,
                model,
                thread_timeout,
            )
        };
        let mapping = match mapping_result {
            Ok(mapping) => mapping,
            Err(error) => {
                let failure_class = if resume_thread_id.is_some() {
                    RuntimeRecoveryFailureClass::ThreadResume
                } else {
                    RuntimeRecoveryFailureClass::ThreadStart
                };
                self.shutdown_runtime_process_claim(
                    runtime,
                    &mut process_claim,
                    "context.runtime_process_thread_failure_cleaned",
                    now,
                )?;
                self.persist_runtime_process_failure(&mut attempt, failure_class, &error, now)?;
                return Err(ApplicationError::Runtime(error));
            }
        };
        let mapping_digest = mapping.digest()?;
        let expected_revision = attempt.revision;
        attempt.bind_thread(
            runtime.instance_digest(),
            mapping.runtime_thread_id.clone(),
            mapping_digest.clone(),
            now,
        )?;
        self.persist_runtime_recovery_transition(
            &attempt,
            expected_revision,
            "context.runtime_recovery_thread_bound",
            now,
        )?;

        let expected_handle_revision = handle.revision;
        let expected_mailbox_revision = mailbox.revision;
        let expected_attempt_revision = attempt.revision;
        handle.reattach(attempt.source_attachment_epoch, mapping_digest.clone(), now)?;
        let requeued = mailbox.recover_after_reattach(&handle, now)?;
        attempt.mark_attached(&handle, now)?;
        self.store.attach_worker_and_finish_runtime_recovery(
            &handle,
            expected_handle_revision,
            &mailbox,
            expected_mailbox_revision,
            &attempt,
            expected_attempt_revision,
            &[PendingEvent::new(
                "context.runtime_recovery_attached",
                serde_json::json!({
                    "recoveryId": attempt.id,
                    "workspaceId": attempt.workspace_id,
                    "workerId": attempt.worker_id,
                    "workerGeneration": attempt.worker_generation,
                    "attachmentEpoch": handle.attachment_epoch,
                    "processAttempt": attempt.process_attempt,
                    "checkpointId": attempt.checkpoint_id,
                    "checkpointDigest": attempt.checkpoint_digest,
                    "healthDigest": attempt.health_digest,
                    "runtimeInstanceDigest": attempt.runtime_instance_digest,
                    "runtimeMappingDigest": mapping_digest,
                    "requeuedInFlight": requeued,
                    "handleRevision": handle.revision,
                    "mailboxRevision": mailbox.revision,
                    "recoveryRevision": attempt.revision,
                }),
                now,
            )],
            now,
        )?;
        Ok(ManagedContextRuntime {
            recovery: attempt,
            process_claim,
            mapping,
            handle,
            mailbox,
            runtime,
        })
    }

    fn shutdown_runtime_process_claim(
        &mut self,
        runtime: StdioRuntime,
        claim: &mut RuntimeProcessClaim,
        event_type: &str,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        match runtime.shutdown() {
            Ok(report) => {
                let evidence_digest = sha256(format!("{report:?}").as_bytes());
                self.record_runtime_process_cleanup(
                    claim,
                    RuntimeProcessCleanupDisposition::Terminated,
                    &evidence_digest,
                    event_type,
                    1,
                    1,
                    0,
                    now,
                )
            }
            Err(_) => self.reconcile_runtime_process_claim(claim, event_type, now),
        }
    }

    fn reconcile_runtime_process_claim(
        &mut self,
        claim: &mut RuntimeProcessClaim,
        event_type: &str,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        let report = cleanup_runtime_process(
            &runtime_process_cleanup_target(claim)?,
            StdDuration::from_millis(250),
        )?;
        let disposition = domain_process_cleanup_disposition(report.disposition);
        self.record_runtime_process_cleanup(
            claim,
            disposition,
            &report.evidence_digest,
            event_type,
            report.matched_process_count,
            report.signalled_process_count,
            report.remaining_process_count,
            now,
        )?;
        if matches!(
            disposition,
            RuntimeProcessCleanupDisposition::InspectionBlocked
                | RuntimeProcessCleanupDisposition::TerminationFailed
        ) {
            return Err(ApplicationError::RuntimeProcessCleanupBlocked { claim_count: 1 });
        }
        Ok(())
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "the persisted cleanup event carries the exact bounded process reconciliation counts"
    )]
    fn record_runtime_process_cleanup(
        &mut self,
        claim: &mut RuntimeProcessClaim,
        disposition: RuntimeProcessCleanupDisposition,
        evidence_digest: &str,
        event_type: &str,
        matched_process_count: usize,
        signalled_process_count: usize,
        remaining_process_count: usize,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        let expected_revision = claim.revision;
        claim.record_cleanup(disposition, evidence_digest.to_owned(), now)?;
        self.store.update_runtime_process_claim(
            claim,
            expected_revision,
            &[PendingEvent::new(
                event_type,
                serde_json::json!({
                    "runtimeRecoveryId": claim.recovery_id,
                    "missionId": claim.mission_id,
                    "workspaceId": claim.workspace_id,
                    "workerId": claim.worker_id,
                    "workerGeneration": claim.worker_generation,
                    "processAttempt": claim.process_attempt,
                    "launchTokenDigest": claim.launch_token_digest,
                    "launchExecutablePathDigest": claim.launch_executable_path_digest,
                    "cleanupDisposition": disposition,
                    "cleanupEvidenceDigest": evidence_digest,
                    "matchedProcessCount": matched_process_count,
                    "signalledProcessCount": signalled_process_count,
                    "remainingProcessCount": remaining_process_count,
                    "status": claim.status,
                    "externalEffectReplayed": false,
                }),
                now,
            )],
            now,
        )?;
        Ok(())
    }

    pub fn shutdown_managed_context_runtime(
        &mut self,
        managed: ManagedContextRuntime,
        now: DateTime<Utc>,
    ) -> Result<RuntimeProcessClaim, ApplicationError> {
        let ManagedContextRuntime {
            runtime,
            mut process_claim,
            ..
        } = managed;
        self.shutdown_runtime_process_claim(
            runtime,
            &mut process_claim,
            "context.runtime_process_shutdown_recorded",
            now,
        )?;
        Ok(process_claim)
    }

    fn persist_runtime_process_failure(
        &mut self,
        attempt: &mut RuntimeRecoveryAttempt,
        class: RuntimeRecoveryFailureClass,
        error: &AdapterError,
        now: DateTime<Utc>,
    ) -> Result<(), ApplicationError> {
        let expected_revision = attempt.revision;
        let evidence_digest = sha256(format!("{error:?}").as_bytes());
        attempt.record_process_failure(class, evidence_digest.clone(), now)?;
        self.store.update_runtime_recovery(
            attempt,
            expected_revision,
            &[PendingEvent::new(
                if attempt.status == RuntimeRecoveryStatus::Failed {
                    "context.runtime_recovery_failed"
                } else {
                    "context.runtime_recovery_retry_scheduled"
                },
                serde_json::json!({
                    "recoveryId": attempt.id,
                    "workspaceId": attempt.workspace_id,
                    "workerId": attempt.worker_id,
                    "failureClass": class,
                    "failureEvidenceDigest": evidence_digest,
                    "processAttempt": attempt.process_attempt,
                    "failureCount": attempt.failures.len(),
                    "status": attempt.status,
                    "revision": attempt.revision,
                }),
                now,
            )],
            now,
        )?;
        Ok(())
    }

