    pub fn merge_context_branch(
        &mut self,
        command: MergeContextBranch,
        now: DateTime<Utc>,
    ) -> Result<(ContextBranchMerge, ContextBranch, ContinuationLedger), ApplicationError> {
        let workspace = self
            .store
            .load_context_workspace(&command.project_id, &command.workspace_id)?;
        let mission = self
            .store
            .load_mission(&command.project_id, &workspace.mission_id)?;
        let mut source = self
            .store
            .load_context_branch(&command.project_id, &command.source_branch_id)?;
        require_context_branch_revision(&source, command.expected_source_revision)?;
        let target = self
            .store
            .load_context_branch(&command.project_id, &command.target_branch_id)?;
        let capsule = self
            .store
            .load_context_capsule(&command.project_id, &command.capsule_id)?;
        let mut continuation = self.store.load_context_continuation_ledger(
            &command.project_id,
            &command.continuation_ledger_id,
        )?;
        if continuation.revision != command.expected_continuation_revision {
            return Err(ApplicationError::ContextContinuationRevisionMismatch {
                expected: command.expected_continuation_revision,
                actual: continuation.revision,
            });
        }
        let merge = ContextBranchMerge::apply(
            command.id, &workspace, &mission, &source, &target, &capsule, now,
        )?;
        let entry = continuation.append(
            ContinuationEntryInput {
                kind: ContinuationEntryKind::CheckpointTransition,
                subject_id: source.id.to_string(),
                payload_ref: format!("mission://context-capsule/{}", capsule.id.as_str()),
                payload_digest: merge.result_digest.clone(),
                evidence_ids: merge.evidence_ids.clone(),
            },
            &workspace,
            &mission,
            now,
        )?;
        source.apply_merge(&merge, now)?;
        self.store.apply_context_branch_merge(
            &merge,
            &source,
            command.expected_source_revision,
            &continuation,
            command.expected_continuation_revision,
            &[PendingEvent::new(
                "context.branch_merged",
                serde_json::json!({
                    "mergeId": merge.id,
                    "workspaceId": merge.workspace_id,
                    "sourceBranchId": merge.source_branch_id,
                    "targetBranchId": merge.target_branch_id,
                    "capsuleId": merge.capsule_id,
                    "resultDigest": merge.result_digest,
                    "artifactCount": merge.artifact_digests.len(),
                    "evidenceCount": merge.evidence_ids.len(),
                    "continuationSequence": entry.sequence,
                    "sourceRevision": source.revision,
                }),
                now,
            )],
            now,
        )?;
        Ok((merge, source, continuation))
    }

