fn validate_sync_document(
    document: &SyncDocument,
    project: &Project,
    object_id: &str,
    object_kind: SyncObjectKind,
    _tombstone: bool,
) -> Result<(), ApplicationError> {
    if document.schema_version != 1
        || document.tenant_id != project.tenant_id
        || document.project_id != project.id
        || document.object_id != object_id
        || document.object_kind != object_kind
        || !document.body.is_object()
    {
        return Err(ApplicationError::InvalidSyncDocument);
    }
    Ok(())
}

#[derive(Clone, Copy)]
struct OutboundDocumentValidation<'a> {
    store: &'a ProjectStore,
    document: &'a SyncDocument,
    project: &'a Project,
    object_id: &'a str,
    object_kind: SyncObjectKind,
    tombstone: bool,
    target_revision: u64,
    now: DateTime<Utc>,
}

#[allow(
    clippy::too_many_lines,
    reason = "the exhaustive outbound dispatcher keeps every authenticated SyncObjectKind gate visible"
)]
fn validate_outbound_sync_document(
    validation: OutboundDocumentValidation<'_>,
) -> Result<(), ApplicationError> {
    if validation.tombstone {
        return Err(ApplicationError::SyncDeletionRequiresTypedCommand);
    }
    let OutboundDocumentValidation {
        store,
        document,
        project,
        object_id,
        object_kind: _,
        tombstone: _,
        target_revision,
        now,
    } = validation;
    match document.object_kind {
        SyncObjectKind::ProjectMetadata => {
            let metadata: ProjectMetadataSnapshot = serde_json::from_value(document.body.clone())?;
            metadata.validate_for(project, object_id)?;
            if metadata != ProjectMetadataSnapshot::from_project(project) {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        SyncObjectKind::Mission => {
            let mission: Mission = serde_json::from_value(document.body.clone())?;
            validate_synced_mission_snapshot(&mission, project, object_id)?;
            if store.load_mission(&project.id, &mission.id)? != mission {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        SyncObjectKind::ProjectTruth => {
            let fact: TruthFact = serde_json::from_value(document.body.clone())?;
            validate_synced_truth_fact(&fact, project, object_id, now)?;
            if fact.version != target_revision
                || store.load_truth_fact(&project.id, &fact.id)? != fact
            {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        SyncObjectKind::WorkProduct => {
            let snapshot: WorkProductSyncSnapshot = serde_json::from_value(document.body.clone())?;
            snapshot.validate_for(project, object_id)?;
            let mission = store.load_mission(&project.id, &snapshot.manifest.mission_id)?;
            let stored_product = mission
                .work_products
                .iter()
                .find(|product| product.id == snapshot.work_product.id);
            if snapshot.manifest.version != target_revision
                || stored_product != Some(&snapshot.work_product)
                || store
                    .load_work_product_manifest(&project.id, &snapshot.manifest.work_product_id)?
                    != snapshot.manifest
            {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        SyncObjectKind::Conversation => {
            let snapshot: ConversationSyncSnapshot = serde_json::from_value(document.body.clone())?;
            validate_outbound_conversation_snapshot(
                store,
                project,
                object_id,
                target_revision,
                now,
                &snapshot,
            )?;
        }
        SyncObjectKind::ConnectionMetadata => {
            let snapshot: ConnectionMetadataSyncSnapshot =
                serde_json::from_value(document.body.clone())?;
            snapshot.validate_for(project, object_id)?;
            if snapshot.sync_version != target_revision
                || store
                    .load_connection(&project.id, &snapshot.connection.id)?
                    .snapshot()
                    != snapshot.connection
            {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
        SyncObjectKind::CreatorWork => {
            let snapshot: CreatorWorkSyncSnapshot = serde_json::from_value(document.body.clone())?;
            validate_outbound_creator_work_snapshot(
                store,
                project,
                object_id,
                target_revision,
                now,
                &snapshot,
            )?;
        }
        SyncObjectKind::OutcomeLedger => {
            let snapshot: OutcomeLedgerSyncSnapshot =
                serde_json::from_value(document.body.clone())?;
            validate_outbound_outcome_ledger_snapshot(
                store,
                project,
                object_id,
                target_revision,
                &snapshot,
            )?;
        }
        SyncObjectKind::ContextCapsule => {
            let snapshot: ContextCapsuleSyncSnapshot =
                serde_json::from_value(document.body.clone())?;
            let mission = store.load_mission(&project.id, &snapshot.capsule.mission_id)?;
            snapshot.validate_for(project, &mission, object_id, now)?;
            let expected = build_context_capsule_sync_snapshot(
                store,
                &project.id,
                &snapshot.capsule.id,
                target_revision,
                now,
            )?;
            if snapshot.sync_version != target_revision || snapshot != expected {
                return Err(ApplicationError::InvalidSyncDocument);
            }
        }
    }
    Ok(())
}

fn validate_outbound_deletion_document(
    validation: OutboundDocumentValidation<'_>,
) -> Result<DeletionTombstone, ApplicationError> {
    if !validation.tombstone || validation.object_kind != SyncObjectKind::ContextCapsule {
        return Err(ApplicationError::SyncDeletionUnsupported(
            validation.object_kind,
        ));
    }
    let tombstone: DeletionTombstone = serde_json::from_value(validation.document.body.clone())?;
    tombstone.validate(validation.now)?;
    if tombstone.tenant_id != validation.project.tenant_id
        || tombstone.project_id != validation.project.id
        || tombstone.object_id != validation.object_id
        || tombstone.object_kind != validation.object_kind.as_str()
        || tombstone
            .prior_object_revision
            .checked_add(1)
            .ok_or(ApplicationError::InvalidSyncDeletion)?
            != validation.target_revision
    {
        return Err(ApplicationError::InvalidSyncDeletion);
    }
    validation.store.ensure_sync_object_not_deleted(
        &validation.project.id,
        validation.object_kind.as_str(),
        validation.object_id,
    )?;
    let capsule = validation.store.load_context_capsule(
        &validation.project.id,
        &ContextCapsuleId::from_stable(validation.object_id.to_owned()),
    )?;
    if capsule.tenant_id != tombstone.tenant_id
        || capsule.project_id != tombstone.project_id
        || capsule.revision != tombstone.prior_object_revision
        || !matches!(
            capsule.status,
            ContextCapsuleStatus::Accepted
                | ContextCapsuleStatus::Cancelled
                | ContextCapsuleStatus::Expired
        )
    {
        return Err(ApplicationError::InvalidSyncDeletion);
    }
    Ok(tombstone)
}

fn validate_outbound_conversation_snapshot(
    store: &ProjectStore,
    project: &Project,
    object_id: &str,
    target_revision: u64,
    now: DateTime<Utc>,
    snapshot: &ConversationSyncSnapshot,
) -> Result<(), ApplicationError> {
    let mission_id = snapshot
        .conversation
        .mission_id
        .as_ref()
        .ok_or(ApplicationError::InvalidSyncDocument)?;
    let mission = store.load_mission(&project.id, mission_id)?;
    snapshot.validate_for(project, &mission, object_id, now)?;
    let identity_matches = store.load_person(&project.id, &snapshot.identity.person.id)?
        == snapshot.identity.person
        && match &snapshot.identity.company {
            Some(company) => store.load_company(&project.id, &company.id)? == *company,
            None => true,
        };
    let connection_matches = store
        .load_connection(&project.id, &snapshot.connection.id)?
        .snapshot()
        == snapshot.connection;
    let consents_match = snapshot.consents.iter().all(|consent| {
        matches!(
            store.load_consent_record(&project.id, &consent.id),
            Ok(stored) if stored == *consent
        )
    });
    if snapshot.sync_version != target_revision
        || store.load_conversation(&project.id, &snapshot.conversation.id)? != snapshot.conversation
        || !identity_matches
        || !connection_matches
        || !consents_match
    {
        return Err(ApplicationError::InvalidSyncDocument);
    }
    Ok(())
}

fn validate_outbound_creator_work_snapshot(
    store: &ProjectStore,
    project: &Project,
    object_id: &str,
    target_revision: u64,
    now: DateTime<Utc>,
    snapshot: &CreatorWorkSyncSnapshot,
) -> Result<(), ApplicationError> {
    let mission = store.load_mission(&project.id, &snapshot.task.mission_id)?;
    snapshot.validate_for(project, &mission, object_id, now)?;
    let identity_mismatch = snapshot.identities.iter().any(|identity| {
        !matches!(
            store.load_partner(&project.id, &identity.partner.id),
            Ok(stored) if stored == identity.partner
        ) || identity.person.as_ref().is_some_and(|person| {
            !matches!(
                store.load_person(&project.id, &person.id),
                Ok(stored) if stored == *person
            )
        }) || identity.company.as_ref().is_some_and(|company| {
            !matches!(
                store.load_company(&project.id, &company.id),
                Ok(stored) if stored == *company
            )
        })
    });
    if snapshot.sync_version != target_revision
        || store.load_creator_hiring(&project.id, &snapshot.hiring.id)? != snapshot.hiring
        || store.load_creator_task(&project.id, &snapshot.task.id)? != snapshot.task
        || identity_mismatch
    {
        return Err(ApplicationError::InvalidSyncDocument);
    }
    Ok(())
}

fn validate_outbound_outcome_ledger_snapshot(
    store: &ProjectStore,
    project: &Project,
    object_id: &str,
    target_revision: u64,
    snapshot: &OutcomeLedgerSyncSnapshot,
) -> Result<(), ApplicationError> {
    snapshot.validate_for(project, object_id)?;
    if snapshot.sync_version != target_revision
        || store.load_outcome_ledger(&project.id)? != snapshot.ledger
        || snapshot.missions.iter().any(|mission| {
            !matches!(
                store.load_mission(&project.id, &mission.id),
                Ok(stored) if stored == *mission
            )
        })
        || snapshot.connections.iter().any(|connection| {
            !matches!(
                store.load_connection(&project.id, &connection.id),
                Ok(stored) if stored.snapshot() == *connection
            )
        })
        || snapshot.companies.iter().any(|company| {
            !matches!(
                store.load_company(&project.id, &company.id),
                Ok(stored) if stored == *company
            )
        })
        || snapshot.people.iter().any(|person| {
            !matches!(
                store.load_person(&project.id, &person.id),
                Ok(stored) if stored == *person
            )
        })
        || snapshot.partners.iter().any(|partner| {
            !matches!(
                store.load_partner(&project.id, &partner.id),
                Ok(stored) if stored == *partner
            )
        })
        || snapshot.identity_links.iter().any(|link| {
            !matches!(
                store.load_identity_link(&project.id, &link.id),
                Ok(stored) if stored == *link
            )
        })
        || snapshot.consents.iter().any(|consent| {
            !matches!(
                store.load_consent_record(&project.id, &consent.id),
                Ok(stored) if stored == *consent
            )
        })
        || snapshot.campaigns.iter().any(|campaign| {
            !matches!(
                store.load_campaign(&project.id, &campaign.id),
                Ok(stored) if stored == *campaign
            )
        })
        || snapshot.opportunities.iter().any(|opportunity| {
            !matches!(
                store.load_opportunity(&project.id, &opportunity.id),
                Ok(stored) if stored == *opportunity
            )
        })
    {
        return Err(ApplicationError::InvalidSyncDocument);
    }
    Ok(())
}

fn validate_synced_truth_fact(
    fact: &TruthFact,
    project: &Project,
    object_id: &str,
    now: DateTime<Utc>,
) -> Result<(), ApplicationError> {
    fact.validate(now)?;
    if fact.tenant_id != project.tenant_id
        || fact.project_id != project.id
        || fact.id.as_str() != object_id
    {
        return Err(ApplicationError::InvalidSyncDocument);
    }
    Ok(())
}

#[allow(
    clippy::too_many_lines,
    reason = "the sync validator exhaustively enforces every nested Mission aggregate invariant"
)]
fn validate_synced_mission_snapshot(
    mission: &Mission,
    project: &Project,
    object_id: &str,
) -> Result<(), ApplicationError> {
    let task_ids = mission
        .tasks
        .iter()
        .map(|task| task.id.clone())
        .collect::<BTreeSet<_>>();
    let evidence_ids = mission
        .evidence
        .iter()
        .map(|evidence| evidence.id.clone())
        .collect::<BTreeSet<_>>();
    let work_product_ids = mission
        .work_products
        .iter()
        .map(|work_product| work_product.id.clone())
        .collect::<BTreeSet<_>>();
    let effect_ids = mission
        .effects
        .iter()
        .map(|effect| effect.id.clone())
        .collect::<BTreeSet<_>>();
    let effect_idempotency = mission
        .effects
        .iter()
        .map(|effect| effect.idempotency_key.as_str())
        .collect::<BTreeSet<_>>();
    let outcome_projection_matches = match (mission.outcome_history.last(), &mission.outcome) {
        (None, None) => true,
        (Some(history), Some(projection)) => history == projection,
        _ => false,
    };
    if mission.tenant_id != project.tenant_id
        || mission.project_id != project.id
        || mission.id.as_str() != object_id
        || mission.title.trim().is_empty()
        || mission.revision == 0
        || mission.created_at > mission.updated_at
        || mission
            .contract
            .validate(mission.contract.valid_from)
            .is_err()
        || mission.definition.as_ref().is_some_and(|definition| {
            definition.validate().is_err()
                || mission.validate_checkpoint_evidence_scope().is_err()
                || definition.operating_mode != mission.contract.mode
                || definition.capability_ids != mission.contract.enabled_capabilities
                || !definition
                    .capability_ids
                    .is_disjoint(&mission.contract.forbidden_capabilities)
        })
        || task_ids.len() != mission.tasks.len()
        || evidence_ids.len() != mission.evidence.len()
        || work_product_ids.len() != mission.work_products.len()
        || effect_ids.len() != mission.effects.len()
        || effect_idempotency.len() != mission.effects.len()
        || mission.tasks.iter().any(|task| {
            task.id.as_str().trim().is_empty()
                || task.title.trim().is_empty()
                || task.capability.trim().is_empty()
        })
        || mission.evidence.iter().any(|evidence| {
            evidence.id.as_str().trim().is_empty()
                || evidence.title.trim().is_empty()
                || evidence.source_uri.trim().is_empty()
                || !evidence.confidence.is_finite()
                || !(0.0..=1.0).contains(&evidence.confidence)
                || !is_sha256_text(&evidence.content_digest)
        })
        || mission.work_products.iter().any(|work_product| {
            work_product.id.as_str().trim().is_empty()
                || work_product.title.trim().is_empty()
                || work_product.revision == 0
                || !work_product
                    .evidence_ids
                    .iter()
                    .all(|evidence_id| evidence_ids.contains(evidence_id))
        })
        || mission.effects.iter().any(|effect| {
            effect.tenant_id != project.tenant_id
                || effect.project_id != project.id
                || effect.mission_id != mission.id
                || effect.id.as_str().trim().is_empty()
                || effect.idempotency_key.trim().is_empty()
                || !is_sha256_text(&effect.payload_digest)
                || effect.amount.amount_minor < 0
                || effect.approval.as_ref().is_some_and(|approval| {
                    approval.scope_digest != effect.approval_digest()
                        || !is_sha256_text(&approval.permission_digest)
                })
                || effect.verification.as_ref().is_some_and(|verification| {
                    effect
                        .receipt
                        .as_ref()
                        .is_none_or(|receipt| receipt.id != verification.receipt_id)
                        || !verification.independent
                        || !is_sha256_text(&verification.evidence_digest)
                })
        })
        || !outcome_projection_matches
        || mission.block.as_ref().is_some_and(|block| {
            !matches!(
                mission.stage,
                MissionStage::Blocked | MissionStage::WaitingUser | MissionStage::WaitingApproval
            ) || block.code.trim().is_empty()
                || block.detail.trim().is_empty()
        })
    {
        return Err(ApplicationError::InvalidSyncDocument);
    }
    Ok(())
}

fn validate_remote_sync_scope(
    project: &Project,
    object: &EncryptedSyncObject,
) -> Result<(), ApplicationError> {
    if object.scope.tenant_id != project.tenant_id
        || object.project_id != project.id
        || object.scope.cell.as_str().is_empty()
        || object.object_id.trim().is_empty()
        || object.revision == 0
    {
        return Err(ApplicationError::SyncResultMismatch);
    }
    Ok(())
}

fn validate_local_inbound_matches_remote(
    local: &LocalInboundSyncObject,
    remote: &EncryptedSyncObject,
) -> Result<(), ApplicationError> {
    if local.envelope.tenant_id != remote.scope.tenant_id
        || local.envelope.project_id != remote.project_id
        || local.envelope.cell != remote.scope.cell.as_str()
        || local.envelope.object_id != remote.object_id
        || local.envelope.object_kind != remote.object_kind.as_str()
        || local.envelope.remote_revision != remote.revision
        || local.envelope.key_version != remote.payload.key_version
        || local.envelope.content_digest != remote.payload.content_digest
        || local.envelope.tombstone != remote.tombstone
        || local.envelope.request_digest != canonical_sha256(&local.envelope.request)?
    {
        return Err(ApplicationError::SyncResultMismatch);
    }
    Ok(())
}

fn sync_content_context(
    cell: DataCell,
    project: &Project,
    object_id: &str,
    object_kind: SyncObjectKind,
    object_revision: u64,
    key_version: u64,
    tombstone: bool,
) -> ContentEncryptionContext {
    ContentEncryptionContext {
        cell: cell.as_str().into(),
        tenant_id: project.tenant_id.clone(),
        project_id: project.id.clone(),
        object_id: object_id.to_owned(),
        object_kind: object_kind.as_str().into(),
        object_revision,
        key_version,
        tombstone,
    }
}

fn sync_idempotency_digest(
    project: &Project,
    cell: DataCell,
    idempotency_key: &str,
) -> Result<String, ApplicationError> {
    canonical_sha256(&serde_json::json!({
        "cell": cell,
        "tenantId": project.tenant_id,
        "projectId": project.id,
        "idempotencyKey": idempotency_key,
    }))
}

fn canonical_sha256(value: &serde_json::Value) -> Result<String, ApplicationError> {
    Ok(format!("{:x}", Sha256::digest(serde_json::to_vec(value)?)))
}

fn prepared_sync_from_outcome(
    outcome: LocalSyncPrepareOutcome,
) -> Result<PreparedEncryptedSyncOperation, ApplicationError> {
    prepared_sync_from_local(outcome.operation, outcome.duplicate)
}

fn prepared_sync_from_local(
    local: LocalSyncOperation,
    duplicate: bool,
) -> Result<PreparedEncryptedSyncOperation, ApplicationError> {
    if local.request_digest != canonical_sha256(&local.request)? {
        return Err(ApplicationError::SyncResultMismatch);
    }
    let mutation: EncryptedSyncMutation = serde_json::from_value(local.request.clone())?;
    if mutation.scope.cell.as_str() != local.cell
        || mutation.scope.tenant_id != local.tenant_id
        || mutation.project_id != local.project_id
        || mutation.object_id != local.object_id
        || mutation.object_kind.as_str() != local.object_kind
        || mutation.payload.key_version != local.key_version
        || mutation.payload.content_digest != local.content_digest
        || mutation.tombstone != local.tombstone
        || mutation.idempotency_key_digest != local.idempotency_key_digest
        || sync_target_revision(mutation.precondition, mutation.tombstone)? != local.target_revision
    {
        return Err(ApplicationError::SyncResultMismatch);
    }
    Ok(PreparedEncryptedSyncOperation {
        local,
        mutation,
        duplicate,
    })
}

fn mission_stage_event(stage: &MissionStage) -> &'static str {
    match stage {
        MissionStage::Scheduled => "mission.scheduled",
        MissionStage::CycleReviewed => "mission.cycle_reviewed",
        MissionStage::Completed => "mission.completed",
        MissionStage::Partial => "mission.partial",
        MissionStage::ExpectedRefusal => "mission.expected_refusal",
        MissionStage::Failed => "mission.failed",
        MissionStage::Cancelled => "mission.cancelled",
        _ => "mission.state_changed",
    }
}

fn effect_execution_events(
    effect_id: &EffectId,
    result: &BrokerResult,
    now: DateTime<Utc>,
) -> [PendingEvent; 2] {
    [
        PendingEvent::new(
            "effect.executed",
            serde_json::json!({
                "effectId": effect_id,
                "receiptId": result.receipt.id,
                "disposition": format!("{:?}", result.disposition),
            }),
            now,
        ),
        PendingEvent::new(
            "effect.verified",
            serde_json::json!({
                "effectId": effect_id,
                "verificationId": result.verification.id,
                "status": result.verification.status,
            }),
            now,
        ),
    ]
}

fn effect_reconciliation_events(
    effect_id: &EffectId,
    result: &BrokerResult,
    now: DateTime<Utc>,
) -> [PendingEvent; 2] {
    [
        PendingEvent::new(
            "effect.reconciliation_receipt_found",
            serde_json::json!({
                "effectId": effect_id,
                "receiptId": result.receipt.id,
                "disposition": format!("{:?}", result.disposition),
                "readOnlyReconciliation": true,
                "providerExecutionReplayed": false,
            }),
            now,
        ),
        PendingEvent::new(
            "effect.reconciliation_verified",
            serde_json::json!({
                "effectId": effect_id,
                "verificationId": result.verification.id,
                "status": result.verification.status,
                "independent": result.verification.independent,
            }),
            now,
        ),
    ]
}

fn effect_reconciliation_error_event(
    effect_id: &EffectId,
    error: &BrokerError,
    now: DateTime<Utc>,
) -> PendingEvent {
    let (event_type, evidence_digest, retry_at, attempts) = match error {
        BrokerError::ProviderNotExecuted { evidence_digest } => (
            "effect.reconciled_not_executed",
            Some(evidence_digest.as_str()),
            None,
            None,
        ),
        BrokerError::ReconciliationStillUncertain {
            evidence_digest,
            retry_at,
            ..
        } => (
            "effect.reconciliation_retry_scheduled",
            Some(evidence_digest.as_str()),
            Some(*retry_at),
            None,
        ),
        BrokerError::ReconciliationDeadLetter {
            evidence_digest,
            attempts,
            ..
        } => (
            "effect.reconciliation_dead_lettered",
            Some(evidence_digest.as_str()),
            None,
            Some(*attempts),
        ),
        BrokerError::ProviderRejected(_) => {
            ("effect.reconciliation_provider_rejected", None, None, None)
        }
        BrokerError::VerificationRejected => (
            "effect.reconciliation_verification_rejected",
            None,
            None,
            None,
        ),
        BrokerError::VerificationInconclusive => (
            "effect.reconciliation_verification_inconclusive",
            None,
            None,
            None,
        ),
        _ => ("effect.reconciliation_failed", None, None, None),
    };
    PendingEvent::new(
        event_type,
        serde_json::json!({
            "effectId": effect_id,
            "evidenceDigest": evidence_digest,
            "retryAt": retry_at,
            "attempts": attempts,
            "readOnlyReconciliation": true,
            "providerExecutionReplayed": false,
        }),
        now,
    )
}

fn project_conversation_reconciliation_error(
    conversation: &mut Conversation,
    mission: &Mission,
    effect_id: &EffectId,
    original_generation: u64,
    now: DateTime<Utc>,
) -> Result<&'static str, ApplicationError> {
    let effect = mission.effect(effect_id)?;
    match effect.status {
        EffectStatus::Reconciled => {
            conversation.mark_agent_reply_reconciled_not_sent(
                effect_id,
                original_generation,
                now,
            )?;
            Ok("conversation.reply_reconciled_not_sent")
        }
        EffectStatus::DeadLetter => {
            conversation.mark_agent_reply_reconciliation_dead_letter(
                effect_id,
                original_generation,
                now,
            )?;
            Ok("conversation.reply_reconciliation_dead_lettered")
        }
        EffectStatus::Failed if effect.receipt.is_none() => {
            conversation.mark_agent_reply_reconciled_failed(effect_id, original_generation, now)?;
            Ok("conversation.reply_reconciled_failed")
        }
        EffectStatus::Failed | EffectStatus::VerificationRequired => {
            let receipt = effect
                .receipt
                .as_ref()
                .ok_or(ApplicationError::InvalidEffectReconciliationProjection)?;
            conversation.record_reconciled_agent_reply_uncertain_receipt(
                effect_id,
                receipt.id.clone(),
                provider_receipt_event_digest(receipt),
                original_generation,
                receipt.accepted_at,
                now,
            )?;
            Ok("conversation.reply_reconciliation_unverified")
        }
        _ => Err(ApplicationError::InvalidEffectReconciliationProjection),
    }
}

fn provider_receipt_event_digest(receipt: &hartevo_domain_kernel::Receipt) -> String {
    sha256(
        format!(
            "{}:{}:{}",
            receipt.provider, receipt.external_id, receipt.response_digest
        )
        .as_bytes(),
    )
}

fn order_mission(
    ledger: &OutcomeLedger,
    order_id: &OrderId,
) -> Result<MissionId, ApplicationError> {
    let source_event_id = ledger
        .orders
        .iter()
        .find(|order| &order.id == order_id)
        .map(|order| &order.source_event_id)
        .ok_or(OutcomeLedgerError::UnknownOrder)?;
    ledger
        .events
        .iter()
        .find(|event| &event.id == source_event_id)
        .map(|event| event.mission_id.clone())
        .ok_or_else(|| OutcomeLedgerError::EventProjectionMismatch.into())
}

#[allow(clippy::too_many_arguments)]
fn creator_recruitment_effect_spec(
    hiring: &CreatorHiring,
    candidate: Option<&CreatorCandidate>,
    effect_id: EffectId,
    actor_id: ActorId,
    provider: String,
    connection_id: ConnectionId,
    account_id: AccountId,
    required_scopes: BTreeSet<String>,
    policy_version: String,
    timezone: String,
    idempotency_key: String,
    expires_in: Duration,
    scope_digest: String,
    creator_contact_guard: Option<CreatorContactEffectGuard>,
    now: DateTime<Utc>,
) -> Result<EffectSpec, ApplicationError> {
    if hiring.status != hartevo_domain_kernel::CreatorHiringStatus::Recruiting
        || provider.trim().is_empty()
        || policy_version.trim().is_empty()
        || timezone.trim().is_empty()
        || idempotency_key.trim().is_empty()
    {
        return Err(ApplicationError::CreatorHiringEffectMismatch);
    }
    let expires_at = std::cmp::min(
        hiring.application_deadline,
        now.checked_add_signed(expires_in)
            .ok_or(ApplicationError::CreatorHiringEffectMismatch)?,
    );
    if expires_at <= now {
        return Err(ApplicationError::CreatorHiringEffectMismatch);
    }
    let (capability, effect_class, description, target_resource, audience_digest) = match candidate
    {
        Some(candidate) => (
            "partner.engage".to_owned(),
            EffectClass::Outreach,
            format!(
                "Invite selected creator {} to the frozen bounty",
                candidate.creator_id
            ),
            format!(
                "creator-hiring://{}/candidate/{}",
                hiring.id, candidate.creator_id
            ),
            Some(candidate.identity_evidence_digest.clone()),
        ),
        None => (
            "creator.task.publish".to_owned(),
            EffectClass::ExternalWrite,
            format!("Publish frozen creator bounty {}", hiring.id),
            format!("creator-hiring://{}/listing", hiring.id),
            None,
        ),
    };
    Ok(EffectSpec {
        id: effect_id,
        actor_id,
        capability,
        provider,
        connection_id: Some(connection_id),
        account_id: Some(account_id),
        required_scopes,
        effect_class,
        description,
        target_resource,
        audience_digest,
        payload_digest: scope_digest,
        asset_digests: BTreeSet::from([hiring.brief_digest.clone()]),
        scheduled_for: None,
        timezone,
        consent: ConsentState::NotRequired,
        consent_record_id: None,
        consent_requirement: None,
        conversation_guard: None,
        creator_contact_guard,
        policy_version,
        risk: EffectRisk::High,
        idempotency_key,
        amount: Money::zero(hiring.bounty.currency.clone()),
        expires_at,
    })
}

fn verified_creator_external_proof(
    mission: &Mission,
    effect_id: &EffectId,
    expected_capability: &str,
    expected_class: &EffectClass,
    expected_scope_digest: &str,
) -> Result<CreatorExternalProof, ApplicationError> {
    let effect = mission.effect(effect_id)?;
    let receipt = effect
        .receipt
        .as_ref()
        .ok_or(ApplicationError::CreatorHiringEffectMismatch)?;
    let verification = effect
        .verification
        .as_ref()
        .filter(|verification| {
            verification.status == VerificationStatus::Confirmed && verification.independent
        })
        .ok_or(ApplicationError::CreatorHiringEffectMismatch)?;
    let connection_id = effect
        .connection_id
        .clone()
        .ok_or(ApplicationError::CreatorHiringEffectMismatch)?;
    let account_id = effect
        .account_id
        .clone()
        .ok_or(ApplicationError::CreatorHiringEffectMismatch)?;
    if effect.status != EffectStatus::Verified
        || effect.capability != expected_capability
        || &effect.effect_class != expected_class
        || effect.payload_digest != expected_scope_digest
        || receipt.provider != effect.provider
        || receipt.request_digest != effect.approval_digest()
        || verification.receipt_id != receipt.id
        || verification.observed_at < receipt.accepted_at
    {
        return Err(ApplicationError::CreatorHiringEffectMismatch);
    }
    Ok(CreatorExternalProof {
        effect_id: effect.id.clone(),
        receipt_id: receipt.id.clone(),
        verification_id: verification.id.clone(),
        provider: receipt.provider.clone(),
        connection_id,
        account_id,
        scope_digest: effect.payload_digest.clone(),
        provider_receipt_digest: provider_receipt_event_digest(receipt),
        verification_evidence_digest: verification.evidence_digest.clone(),
        occurred_at: receipt.accepted_at,
        verified_at: verification.observed_at,
    })
}

fn creator_payout_effect_spec(
    command: &PrepareCreatorPayout,
    authorization: &PayoutAuthorization,
    now: DateTime<Utc>,
) -> Result<EffectSpec, ApplicationError> {
    let expires_at = std::cmp::min(
        authorization.expires_at,
        now.checked_add_signed(command.expires_in)
            .ok_or(ApplicationError::CreatorPayoutEffectMismatch)?,
    );
    Ok(EffectSpec {
        id: command.effect_id.clone(),
        actor_id: command.actor_id.clone(),
        capability: "settlement.payout".into(),
        provider: authorization.funding_provider.clone(),
        connection_id: Some(authorization.connection_id.clone()),
        account_id: Some(authorization.connected_account_id.clone()),
        required_scopes: BTreeSet::from(["payout.write".into()]),
        effect_class: EffectClass::Payment,
        description: format!(
            "Pay accepted creator milestone {}",
            authorization.milestone_id
        ),
        target_resource: format!(
            "creator-payout://{}/{}",
            authorization.task_id, authorization.payout_id
        ),
        audience_digest: None,
        payload_digest: authorization.scope_digest.clone(),
        asset_digests: BTreeSet::from([authorization.deliverable_digest.clone()]),
        scheduled_for: None,
        timezone: command.timezone.clone(),
        consent: ConsentState::NotRequired,
        consent_record_id: None,
        consent_requirement: None,
        conversation_guard: None,
        creator_contact_guard: None,
        policy_version: command.policy_version.clone(),
        risk: EffectRisk::Critical,
        idempotency_key: authorization.idempotency_key.clone(),
        amount: authorization.amount.clone(),
        expires_at,
    })
}

fn validate_creator_payout_effect_binding(
    task: &CreatorTask,
    effect: &Effect,
) -> Result<PayoutAuthorization, ApplicationError> {
    let authorization = task
        .payout_authorizations
        .iter()
        .find(|authorization| {
            authorization.scope_digest == effect.payload_digest
                && authorization.idempotency_key == effect.idempotency_key
        })
        .cloned()
        .ok_or(ApplicationError::CreatorPayoutEffectMismatch)?;
    let expected_target = format!(
        "creator-payout://{}/{}",
        authorization.task_id, authorization.payout_id
    );
    if effect.tenant_id != task.tenant_id
        || effect.project_id != task.project_id
        || effect.mission_id != task.mission_id
        || effect.effect_class != EffectClass::Payment
        || effect.capability != "settlement.payout"
        || effect.provider != authorization.funding_provider
        || effect.connection_id.as_ref() != Some(&authorization.connection_id)
        || effect.account_id.as_ref() != Some(&authorization.connected_account_id)
        || effect.required_scopes != BTreeSet::from(["payout.write".into()])
        || effect.target_resource != expected_target
        || effect.audience_digest.is_some()
        || effect.payload_digest != authorization.scope_digest
        || effect.asset_digests != BTreeSet::from([authorization.deliverable_digest.clone()])
        || effect.scheduled_for.is_some()
        || effect.timezone.trim().is_empty()
        || effect.consent != ConsentState::NotRequired
        || effect.consent_record_id.is_some()
        || effect.consent_requirement.is_some()
        || effect.conversation_guard.is_some()
        || effect.creator_contact_guard.is_some()
        || effect.risk != EffectRisk::Critical
        || effect.idempotency_key != authorization.idempotency_key
        || effect.amount != authorization.amount
        || effect.expires_at > authorization.expires_at
    {
        return Err(ApplicationError::CreatorPayoutEffectMismatch);
    }
    Ok(authorization)
}

fn project_verified_creator_payout(
    task: &mut CreatorTask,
    effect: &Effect,
    now: DateTime<Utc>,
) -> Result<bool, ApplicationError> {
    let authorization = validate_creator_payout_effect_binding(task, effect)?;
    let receipt = effect
        .receipt
        .as_ref()
        .ok_or(ApplicationError::CreatorPayoutEffectMismatch)?;
    let verification = effect
        .verification
        .as_ref()
        .filter(|verification| {
            verification.status == VerificationStatus::Confirmed && verification.independent
        })
        .ok_or(ApplicationError::CreatorPayoutEffectMismatch)?;
    if effect.status != EffectStatus::Verified
        || receipt.provider != effect.provider
        || receipt.request_digest != effect.approval_digest()
        || verification.receipt_id != receipt.id
        || verification.observed_at < receipt.accepted_at
    {
        return Err(ApplicationError::CreatorPayoutEffectMismatch);
    }
    let confirmation = CreatorPayoutConfirmation {
        effect_id: effect.id.clone(),
        effect_approval_digest: effect.approval_digest(),
        approved_payload_digest: effect.payload_digest.clone(),
        provider: receipt.provider.clone(),
        external_id: receipt.external_id.clone(),
        request_digest: receipt.request_digest.clone(),
        response_digest: receipt.response_digest.clone(),
        verification_evidence_digest: verification.evidence_digest.clone(),
        executed_at: receipt.accepted_at,
        verified_at: verification.observed_at,
    };
    if let Some(existing) = task
        .payouts
        .iter()
        .find(|payout| payout.authorization.payout_id == authorization.payout_id)
    {
        if existing.authorization == authorization && existing.confirmation == confirmation {
            return Ok(false);
        }
        return Err(ApplicationError::CreatorPayoutEffectMismatch);
    }
    task.record_verified_payout(authorization, confirmation, now)?;
    Ok(true)
}

fn conversation_reply_effect_spec(
    conversation: &Conversation,
    command: &PrepareConversationReplyEffect,
    prepared_reply: &PreparedAutomaticReply,
    consent: ConsentState,
    consent_record_id: Option<ConsentRecordId>,
    consent_requirement: Option<ConsentRequirement>,
    expires_at: DateTime<Utc>,
) -> EffectSpec {
    EffectSpec {
        id: command.effect_id.clone(),
        actor_id: command.actor_id.clone(),
        capability: "conversation.reply".into(),
        provider: command.provider.clone(),
        connection_id: command.connection_id.clone(),
        account_id: command.account_id.clone(),
        required_scopes: command.required_scopes.clone(),
        effect_class: EffectClass::Outreach,
        description: format!("Send reviewed conversation reply {}", command.message_id),
        target_resource: format!("conversation://{}", conversation.id),
        audience_digest: Some(sha256(conversation.person_id.as_str().as_bytes())),
        payload_digest: command.content_digest.clone(),
        asset_digests: BTreeSet::new(),
        scheduled_for: command.scheduled_for,
        timezone: command.timezone.clone(),
        consent,
        consent_record_id,
        consent_requirement,
        conversation_guard: Some(ConversationEffectGuard {
            conversation_id: conversation.id.clone(),
            control_generation: prepared_reply.control_generation,
            scope_digest: prepared_reply.scope_digest.clone(),
        }),
        creator_contact_guard: None,
        policy_version: command.policy_version.clone(),
        risk: EffectRisk::High,
        idempotency_key: command.idempotency_key.clone(),
        amount: Money::zero(command.currency.clone()),
        expires_at,
    }
}

pub fn compile_contract(prompt: &str, now: DateTime<Utc>) -> MissionContract {
    let mut constraints = Vec::new();
    let lower = prompt.to_lowercase();
    if prompt.contains("未经")
        || prompt.contains("必须确认")
        || prompt.contains("不要发布")
        || lower.contains("approval")
    {
        constraints.push(Constraint::RequireApproval {
            effect_classes: vec![
                EffectClass::ExternalWrite,
                EffectClass::Outreach,
                EffectClass::Spend,
                EffectClass::Payment,
            ],
        });
    }
    let budget_minor = extract_budget_minor(prompt);
    if let Some(amount_minor) = budget_minor {
        constraints.push(Constraint::Budget {
            amount_minor,
            currency: "CNY".into(),
        });
    }
    constraints.push(Constraint::UserInstruction {
        description: prompt.trim().to_owned(),
    });

    let mut contract = MissionContract::bootstrap(
        prompt.trim(),
        [
            "research.discover".into(),
            "evidence.verify".into(),
            "work_product.compose".into(),
            "channel.preview".into(),
            "channel.preview_publish".into(),
        ],
        now,
    );
    contract.constraints = constraints;
    contract.forbidden_capabilities = BTreeSet::from([
        "payment.execute".into(),
        "budget.expand".into(),
        "outreach.bulk_send".into(),
    ]);
    if let Some(amount_minor) = budget_minor {
        contract.budget = Money::new(
            amount_minor,
            CurrencyCode::parse("CNY").expect("static ISO currency is valid"),
        );
    }
    contract
}

#[allow(
    clippy::too_many_lines,
    reason = "the compiler materializes every Operating Contract authority, consent, approval, cadence, budget, market, and completion dimension"
)]
fn compile_catalog_contract(
    catalog: &Catalog,
    manifest: &MissionManifest,
    command: &StartCatalogMission,
    now: DateTime<Utc>,
) -> Result<MissionContract, ApplicationError> {
    let goal = command.goal.trim();
    let market = command.market.trim();
    let language = command.language.trim();
    let audience = command.audience.trim();
    let timezone = command.timezone.trim();
    if goal.is_empty()
        || market.is_empty()
        || language.is_empty()
        || audience.is_empty()
        || timezone.is_empty()
        || command.budget.amount_minor < 0
        || command.manifest_id.trim() != manifest.id
    {
        return Err(ApplicationError::InvalidCatalogMissionInput);
    }
    let mode_name = operating_mode_catalog_name(&command.mode);
    if !manifest.modes.iter().any(|mode| mode == mode_name) {
        return Err(ApplicationError::CatalogMissionModeNotAllowed);
    }

    let enabled_capabilities = manifest
        .capability_ids
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let mut autonomy_by_capability = BTreeMap::new();
    let mut required_effect_classes = BTreeSet::new();
    for capability_id in &manifest.capability_ids {
        let capability = catalog
            .capabilities
            .capabilities
            .iter()
            .find(|capability| &capability.id == capability_id)
            .ok_or(ApplicationError::InvalidCatalogMissionInput)?;
        let (effect_class, autonomy) = catalog_capability_authority(capability)?;
        if matches!(
            effect_class,
            EffectClass::ExternalWrite
                | EffectClass::Outreach
                | EffectClass::Spend
                | EffectClass::Payment
        ) {
            required_effect_classes.insert(effect_class);
        }
        autonomy_by_capability.insert(capability_id.clone(), autonomy);
    }
    let forbidden_capabilities = catalog
        .capabilities
        .capabilities
        .iter()
        .filter(|capability| !enabled_capabilities.contains(&capability.id))
        .map(|capability| capability.id.clone())
        .collect::<BTreeSet<_>>();
    for capability in &forbidden_capabilities {
        autonomy_by_capability.insert(capability.clone(), AutonomyLevel::Disabled);
    }

    let event_topics = match manifest.id.as_str() {
        "VM-06" => BTreeSet::from(["creator_work.event".to_owned()]),
        _ => BTreeSet::from(["conversation.inbound".to_owned()]),
    };
    let has_event_trigger = manifest.default_cadence.contains("event_driven");
    let has_interval_trigger =
        manifest.default_cadence.contains("weekly") || manifest.default_cadence.contains("monthly");
    let cadence = match command.mode {
        OperatingMode::ContinuousRelationship if has_event_trigger && !has_interval_trigger => {
            Some(Cadence {
                interval_seconds: 0,
                anchor_at: now,
                trigger: CadenceTriggerKind::EventDriven,
                event_topics,
            })
        }
        OperatingMode::ContinuousRelationship if has_event_trigger => Some(Cadence {
            interval_seconds: 7 * 24 * 60 * 60,
            anchor_at: now,
            trigger: CadenceTriggerKind::IntervalOrEvent,
            event_topics,
        }),
        OperatingMode::ContinuousOperator | OperatingMode::ContinuousRelationship => {
            Some(Cadence {
                interval_seconds: 7 * 24 * 60 * 60,
                anchor_at: now,
                trigger: CadenceTriggerKind::Interval,
                event_topics: BTreeSet::new(),
            })
        }
        OperatingMode::Campaign if has_event_trigger && has_interval_trigger => Some(Cadence {
            interval_seconds: 7 * 24 * 60 * 60,
            anchor_at: now,
            trigger: CadenceTriggerKind::IntervalOrEvent,
            event_topics,
        }),
        OperatingMode::Campaign if has_event_trigger => Some(Cadence {
            interval_seconds: 0,
            anchor_at: now,
            trigger: CadenceTriggerKind::EventDriven,
            event_topics,
        }),
        OperatingMode::Campaign if has_interval_trigger => Some(Cadence {
            interval_seconds: 7 * 24 * 60 * 60,
            anchor_at: now,
            trigger: CadenceTriggerKind::Interval,
            event_topics: BTreeSet::new(),
        }),
        OperatingMode::BuildOnce | OperatingMode::Campaign | OperatingMode::OneOffDecision => None,
    };
    let valid_until = now
        + match command.mode {
            OperatingMode::ContinuousOperator | OperatingMode::ContinuousRelationship => {
                Duration::days(180)
            }
            OperatingMode::Campaign => Duration::days(90),
            OperatingMode::BuildOnce | OperatingMode::OneOffDecision => Duration::days(30),
        };
    let mut constraints = vec![
        Constraint::Market {
            value: market.to_owned(),
        },
        Constraint::Budget {
            amount_minor: command.budget.amount_minor,
            currency: command.budget.currency.as_str().to_owned(),
        },
        Constraint::UserInstruction {
            description: goal.to_owned(),
        },
    ];
    if !required_effect_classes.is_empty() {
        constraints.push(Constraint::RequireApproval {
            effect_classes: required_effect_classes.iter().cloned().collect(),
        });
    }
    let consent_requirements = if enabled_capabilities.contains("consent.evaluate") {
        BTreeSet::from([
            "applicable_consent_or_documented_legal_basis".to_owned(),
            "suppression_and_withdrawal_checked_at_dispatch".to_owned(),
        ])
    } else {
        BTreeSet::new()
    };
    let contract = MissionContract {
        version: 1,
        mode: command.mode.clone(),
        goal: goal.to_owned(),
        non_goals: vec![
            "treat provider acceptance as business verification".into(),
            "automatically replay an uncertain external effect".into(),
            "expand beyond the Mission Manifest capability set".into(),
        ],
        market: market.to_owned(),
        language: language.to_owned(),
        audience: audience.to_owned(),
        kpis: BTreeMap::new(),
        budget: command.budget.clone(),
        timezone: timezone.to_owned(),
        cadence,
        autonomy_by_capability,
        consent_requirements,
        approval_policy: ApprovalPolicy {
            required_effect_classes,
            validity_seconds: 3_600,
            exact_scope_required: true,
        },
        stop_conditions: vec![
            "user_cancelled".into(),
            "budget_exhausted".into(),
            "contract_expired".into(),
            "required_connection_revoked".into(),
        ],
        completion_conditions: vec![
            "checkpoint_dag_completed".into(),
            "deterministic_oracles_satisfied".into(),
            "outcome_reviewed_or_valid_terminal_recorded".into(),
        ],
        valid_from: now,
        valid_until,
        constraints,
        enabled_capabilities,
        forbidden_capabilities,
    };
    contract.validate(now).map_err(MissionError::from)?;
    Ok(contract)
}

fn operating_mode_catalog_name(mode: &OperatingMode) -> &'static str {
    match mode {
        OperatingMode::BuildOnce => "build_once",
        OperatingMode::ContinuousOperator => "continuous_operator",
        OperatingMode::Campaign => "campaign",
        OperatingMode::ContinuousRelationship => "continuous_relationship",
        OperatingMode::OneOffDecision => "one_off_decision",
    }
}

fn catalog_capability_authority(
    capability: &CapabilityManifest,
) -> Result<(EffectClass, AutonomyLevel), ApplicationError> {
    match capability.effect_class.as_str() {
        "read" => Ok((EffectClass::Read, AutonomyLevel::AutonomousLowRisk)),
        "local_write" => Ok((EffectClass::LocalWrite, AutonomyLevel::DraftOnly)),
        "external_write" => Ok((EffectClass::ExternalWrite, AutonomyLevel::ApprovalRequired)),
        "outreach" => Ok((EffectClass::Outreach, AutonomyLevel::ApprovalRequired)),
        "spend" => Ok((EffectClass::Spend, AutonomyLevel::ApprovalRequired)),
        "payment" => Ok((EffectClass::Payment, AutonomyLevel::ApprovalRequired)),
        _ => Err(ApplicationError::InvalidCatalogMissionInput),
    }
}

fn extract_budget_minor(prompt: &str) -> Option<i64> {
    let budget_index = prompt
        .find("预算")
        .or_else(|| prompt.to_lowercase().find("budget"))?;
    let trailing = &prompt[budget_index..];
    let digits: String = trailing
        .chars()
        .skip_while(|character| !character.is_ascii_digit())
        .take_while(|character| character.is_ascii_digit() || *character == ',')
        .filter(char::is_ascii_digit)
        .collect();
    if digits.is_empty() {
        return None;
    }
    digits.parse::<i64>().ok()?.checked_mul(100)
}

fn concise_title(prompt: &str) -> String {
    let mut characters = prompt.trim().chars();
    let title: String = characters.by_ref().take(24).collect();
    if characters.next().is_some() {
        format!("{title}…")
    } else {
        title
    }
}

fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn fresh_local_runtime_secret_digest() -> Result<String, ApplicationError> {
    let material = KeyMaterial::generate()?;
    let secret = material.to_secret();
    Ok(sha256(secret.as_slice()))
}

fn runtime_mapping_base_digest(mapping: &RuntimeMapping) -> Result<String, AdapterError> {
    let mut base = mapping.clone();
    base.runtime_turn_id = None;
    base.digest()
}

fn classify_runtime_turn_dispatch_error(error: &AdapterError) -> (RuntimeTurnFailureClass, bool) {
    match error {
        AdapterError::TurnRequestRejected { .. } => {
            (RuntimeTurnFailureClass::DispatchRejected, true)
        }
        AdapterError::InvalidRuntimeMapping
        | AdapterError::InvalidTurnRequest
        | AdapterError::OutboundMessageTooLarge { .. }
        | AdapterError::UnsupportedClientMethod(_)
        | AdapterError::DuplicateRequestId(_)
        | AdapterError::InvalidJsonRpcEnvelope
        | AdapterError::RequestIdExhausted
        | AdapterError::RuntimePoisoned
        | AdapterError::RuntimeAlreadyShutdown
        | AdapterError::TimeoutOutOfRange => (RuntimeTurnFailureClass::DispatchNotSent, true),
        AdapterError::RuntimeExited { .. } | AdapterError::RuntimeStreamsClosed => {
            (RuntimeTurnFailureClass::RuntimeExited, false)
        }
        AdapterError::ProtocolViolation { .. }
        | AdapterError::InvalidTurnResponse { .. }
        | AdapterError::InvalidTurnNotification { .. }
        | AdapterError::ThreadIdentityMismatch { .. } => (RuntimeTurnFailureClass::Protocol, false),
        _ => (RuntimeTurnFailureClass::DispatchUncertain, false),
    }
}

fn classify_runtime_turn_stream_error(error: &AdapterError) -> RuntimeTurnFailureClass {
    match error {
        AdapterError::RuntimeExited { .. }
        | AdapterError::RuntimeStreamsClosed
        | AdapterError::RuntimeAlreadyShutdown => RuntimeTurnFailureClass::RuntimeExited,
        AdapterError::ProtocolViolation { .. }
        | AdapterError::InvalidTurnResponse { .. }
        | AdapterError::InvalidTurnNotification { .. }
        | AdapterError::InvalidRuntimeMapping
        | AdapterError::RuntimePoisoned => RuntimeTurnFailureClass::Protocol,
        _ => RuntimeTurnFailureClass::EventStream,
    }
}

#[derive(Debug, Error)]
pub enum ApplicationError {
    #[error(transparent)]
    Catalog(#[from] CatalogError),
    #[error(transparent)]
    Project(#[from] ProjectError),
    #[error(transparent)]
    Mission(#[from] MissionError),
    #[error(transparent)]
    MissionSchedule(#[from] MissionScheduleError),
    #[error(transparent)]
    MissionConversation(#[from] MissionConversationError),
    #[error(transparent)]
    Storage(#[from] StorageError),
    #[error(transparent)]
    Broker(#[from] BrokerError),
    #[error(transparent)]
    CreatorWork(#[from] CreatorWorkError),
    #[error(transparent)]
    CreatorHiring(#[from] CreatorHiringError),
    #[error(transparent)]
    Connection(#[from] ConnectionError),
    #[error(transparent)]
    Identity(#[from] IdentityError),
    #[error(transparent)]
    Relationship(#[from] RelationshipError),
    #[error(transparent)]
    Truth(#[from] TruthError),
    #[error(transparent)]
    WorkProductManifest(#[from] WorkProductManifestError),
    #[error(transparent)]
    Outcome(#[from] OutcomeLedgerError),
    #[error(transparent)]
    Context(#[from] ContextError),
    #[error(transparent)]
    ContextAssembly(#[from] ContextAssemblyError),
    #[error(transparent)]
    ContextMaterialStore(#[from] ContextMaterialStoreError),
    #[error(transparent)]
    Deletion(#[from] DeletionError),
    #[error(transparent)]
    KeyManagement(#[from] KeyManagementError),
    #[error(transparent)]
    SecretStore(#[from] SecretStoreError),
    #[error(transparent)]
    Json(#[from] serde_json::Error),
    #[error(transparent)]
    CloudStorage(#[from] CloudStorageError),
    #[error(transparent)]
    Runtime(#[from] AdapterError),
    #[error(transparent)]
    RuntimeTurn(#[from] RuntimeTurnError),
    #[error(transparent)]
    Browser(#[from] BrowserError),
    #[error(
        "browser workspace {workspace_id} is hard-stopped in the Host but persistence failed; reconciliation is required"
    )]
    BrowserPersistenceReconciliationRequired {
        workspace_id: BrowserWorkspaceId,
        #[source]
        source: StorageError,
    },
    #[error(
        "browser workspace {workspace_id} has a durable agent lease but the Host remains more restrictive; reconciliation is required"
    )]
    BrowserHostReconciliationRequired {
        workspace_id: BrowserWorkspaceId,
        #[source]
        source: BrowserError,
    },
    #[error(
        "browser file grant {grant_id} could not be persisted ({persistence}) and its staged file also requires cleanup reconciliation"
    )]
    BrowserFilePreparationReconciliationRequired {
        grant_id: BrowserFileGrantId,
        persistence: Box<StorageError>,
        #[source]
        cleanup: BrowserError,
    },
    #[error(
        "browser file grant {grant_id} is durable but its staged-file broker requires reconciliation"
    )]
    BrowserFileBrokerReconciliationRequired {
        grant_id: BrowserFileGrantId,
        #[source]
        source: BrowserError,
    },
    #[error("project encryption mode, primary recipient, or recovery contract is invalid")]
    InvalidEncryptionProvisioning,
    #[error("project keyring persistence failed and the OS wrapping key could not be removed")]
    EncryptionCompensationFailed,
    #[error("project keyring revision changed: expected {expected}, actual {actual}")]
    KeyringRevisionMismatch { expected: u64, actual: u64 },
    #[error("project revision changed: expected {expected}, actual {actual}")]
    ProjectRevisionMismatch { expected: u64, actual: u64 },
    #[error("mission revision changed: expected {expected}, actual {actual}")]
    MissionRevisionMismatch { expected: u64, actual: u64 },
    #[error("Mission Conversation revision changed: expected {expected}, actual {actual}")]
    MissionConversationRevisionMismatch { expected: u64, actual: u64 },
    #[error("work product manifest version changed: expected {expected}, actual {actual}")]
    WorkProductManifestVersionMismatch { expected: u64, actual: u64 },
    #[error("context capsule revision changed: expected {expected}, actual {actual}")]
    ContextCapsuleRevisionMismatch { expected: u64, actual: u64 },
    #[error("context working-set revision changed: expected {expected}, actual {actual}")]
    ContextWorkingSetRevisionMismatch { expected: u64, actual: u64 },
    #[error("context continuation-ledger revision changed: expected {expected}, actual {actual}")]
    ContextContinuationRevisionMismatch { expected: u64, actual: u64 },
    #[error("context branch revision changed: expected {expected}, actual {actual}")]
    ContextBranchRevisionMismatch { expected: u64, actual: u64 },
    #[error("context assembly does not match the requested project, workspace, or capsule")]
    ContextAssemblyScopeMismatch,
    #[error("context assembly expected checkpoint is no longer the current checkpoint")]
    ContextAssemblyCheckpointMismatch,
    #[error("context assembly idempotency key was reused for a different authority or projection")]
    ContextAssemblyIdempotencyConflict,
    #[error("context worker handle revision changed: expected {expected}, actual {actual}")]
    ContextWorkerHandleRevisionMismatch { expected: u64, actual: u64 },
    #[error("context worker mailbox revision changed: expected {expected}, actual {actual}")]
    ContextWorkerMailboxRevisionMismatch { expected: u64, actual: u64 },
    #[error("context worker has an active runtime recovery and cannot be reattached directly")]
    RuntimeRecoveryRequired,
    #[error("runtime recovery requires a durable context checkpoint")]
    RuntimeRecoveryCheckpointRequired,
    #[error("runtime recovery does not match the project, worker, epoch, or runtime configuration")]
    RuntimeRecoveryScopeMismatch,
    #[error("context worker already has an active runtime recovery")]
    RuntimeRecoveryAlreadyActive,
    #[error("runtime recovery revision changed: expected {expected}, actual {actual}")]
    RuntimeRecoveryRevisionMismatch { expected: u64, actual: u64 },
    #[error("runtime recovery is terminal, exhausted, or not in a retryable state")]
    RuntimeRecoveryNotRetryable,
    #[error("runtime generation retirement requires an exhausted failed recovery")]
    RuntimeRecoveryNotFailed,
    #[error("runtime generation has an active or uncertain turn and cannot be retired")]
    RuntimeGenerationHasActiveTurn,
    #[error("runtime working directory resolves outside every project workspace root")]
    RuntimeWorkspaceOutOfScope,
    #[error("runtime resume thread does not match the recovery strategy or durable thread binding")]
    RuntimeRecoveryResumeThreadMismatch,
    #[error("runtime turn assembly revision changed: expected {expected}, actual {actual}")]
    RuntimeTurnAssemblyRevisionMismatch { expected: u64, actual: u64 },
    #[error("runtime turn revision changed: expected {expected}, actual {actual}")]
    RuntimeTurnRevisionMismatch { expected: u64, actual: u64 },
    #[error("runtime turn does not match its assembly, worker, recovery, process, or thread scope")]
    RuntimeTurnScopeMismatch,
    #[error("runtime model/provider does not match the digest-pinned context tokenizer profile")]
    RuntimeTurnTokenizerMismatch,
    #[error("context worker already has an active or unreconciled runtime turn")]
    RuntimeTurnAlreadyActive,
    #[error(
        "runtime turn startup reconciliation must finish before any Runtime process or turn can run"
    )]
    RuntimeTurnStartupReconciliationRequired,
    #[error("{claim_count} Runtime process claim(s) could not be inspected or terminated safely")]
    RuntimeProcessCleanupBlocked { claim_count: usize },
    #[error("runtime local approval request does not match the exact pending request digest")]
    RuntimeTurnApprovalMismatch,
    #[error("runtime turn authority has expired and cannot approve a local action")]
    RuntimeTurnAuthorityExpired,
    #[error("Runtime draft turn does not match the requested project or Mission")]
    RuntimeDraftScopeMismatch,
    #[error("Runtime draft adoption requires a definitively completed turn")]
    RuntimeDraftTurnNotCompleted,
    #[error("completed Runtime turn has no durable SQLCipher-private assistant message")]
    RuntimeDraftMessageMissing,
    #[error("Mission Conversation advanced beyond the Runtime generation awaiting adoption")]
    RuntimeDraftConversationAdvanced,
    #[error("persisted Runtime draft replay does not match its turn-bound content")]
    RuntimeDraftReplayMismatch,
    #[error("local Runtime Context session does not match the exact project scope")]
    LocalRuntimeContextScopeMismatch,
    #[error("local Runtime Context graph conflicts with an existing durable generation")]
    LocalRuntimeContextConflict,
    #[error("Mission is not in a valid state for its bounded local Runtime task")]
    LocalRuntimeMissionNotSchedulable,
    #[error("current Mission Checkpoint executor is {executor:?}, not Runtime")]
    LocalRuntimeCheckpointExecutorMismatch { executor: MissionCheckpointExecutor },
    #[error("Mission has no durable next-cycle schedule")]
    MissionScheduleUnavailable,
    #[error("Mission schedule event identifier is invalid")]
    MissionScheduleSignalInvalid,
    #[error("Mission schedule lease owner or token is invalid")]
    MissionScheduleLeaseInvalid,
    #[error("Mission schedule Task does not match the exact Checkpoint Capability route")]
    MissionScheduleTaskInvalid,
    #[error(
        "Mission schedule {schedule_id} no longer matches Scheduled Mission {mission_id}; reconciliation stopped fail-closed"
    )]
    MissionScheduleStateConflict {
        schedule_id: MissionScheduleId,
        mission_id: MissionId,
    },
    #[error("Catalog Mission has no dispatchable current Checkpoint route")]
    MissionCheckpointDispatchUnavailable,
    #[error("Application Checkpoint completion requires its registered deterministic handler")]
    ApplicationCheckpointExecutionRequired,
    #[error("current Mission Checkpoint executor is {executor:?}, not Application")]
    ApplicationCheckpointExecutorMismatch { executor: MissionCheckpointExecutor },
    #[error(
        "Application Checkpoint command no longer matches the exact Mission/Checkpoint revision"
    )]
    ApplicationCheckpointCommandMismatch,
    #[error("Application Checkpoint replay does not match its persisted handler evidence")]
    ApplicationCheckpointReplayMismatch,
    #[error("Application handler registry and compiled implementation disagree for {handler_id}")]
    ApplicationCheckpointHandlerRegistryMismatch { handler_id: String },
    #[error("Application Checkpoint Mission is bound to a stale Catalog digest")]
    ApplicationCheckpointCatalogRevisionMismatch,
    #[error("Human Checkpoint completion requires the atomic confirmation command")]
    HumanCheckpointConfirmationRequired,
    #[error("the current Catalog Checkpoint is not an active Human confirmation route")]
    HumanCheckpointConfirmationUnavailable,
    #[error(
        "Mission Checkpoint {checkpoint_id} revision changed: expected {expected}, actual {actual}"
    )]
    MissionCheckpointRevisionMismatch {
        checkpoint_id: String,
        expected: u64,
        actual: u64,
    },
    #[error("Human Checkpoint confirmation replay does not match persisted evidence")]
    HumanCheckpointConfirmationReplayMismatch,
    #[error("Human Checkpoint confirmation does not bind the exact required WorkProducts")]
    HumanCheckpointWorkProductMismatch,
    #[error(
        "Catalog Mission route, mode, market, language, audience, timezone, or budget is invalid"
    )]
    InvalidCatalogMissionInput,
    #[error("the selected operating mode is not allowed by the Mission Manifest")]
    CatalogMissionModeNotAllowed,
    #[error("worker lease revision changed: expected {expected}, actual {actual}")]
    WorkerLeaseRevisionMismatch { expected: u64, actual: u64 },
    #[error("project key reference does not match the tenant, project, recipient, or key version")]
    KeyReferenceScopeMismatch,
    #[error("the project has no local workspace root for its encrypted Context CAS")]
    ContextMaterialProjectRootUnavailable,
    #[error(
        "the active project content key version {key_version} has no durable local SecretReference"
    )]
    ContextMaterialKeyReferenceUnavailable { key_version: u64 },
    #[error("project key administration lacks a scoped user/device authorization record")]
    InvalidKeyAdministrationAuthorization,
    #[error("device attachment method, scope, recovery kit, revision, or idempotency is invalid")]
    InvalidDeviceAttachment,
    #[error("the device attachment idempotency key was reused for a different intent")]
    DeviceAttachmentIdempotencyConflict,
    #[error("the prepared device attachment conflicts with the current keyring revision")]
    DeviceAttachmentConflict,
    #[error("device attachment preparation failed and the new OS key could not be removed")]
    DeviceAttachmentCompensationFailed,
    #[error("device bootstrap preparation failed and the X25519 private key could not be removed")]
    DeviceBootstrapCompensationFailed,
    #[error("device handoff scope, target key, claim, expiry, or bootstrap revision is invalid")]
    InvalidDeviceHandoff,
    #[error(
        "the durable key bootstrap operation is applied, conflicted, or assigned to another Cell"
    )]
    KeyBootstrapOperationNotDispatchable,
    #[error("device handoff decryption is forbidden until the remote Claim is durably applied")]
    DeviceHandoffClaimRequired,
    #[error("the local keyring diverged from the exact manifest bound into the handoff Grant")]
    DeviceHandoffBootstrapConflict,
    #[error("encrypted synchronization requires a local encrypted-sync project")]
    SyncRequiresEncryptedProject,
    #[error(
        "encrypted synchronization object, revision, tombstone, or idempotency input is invalid"
    )]
    InvalidSyncOperation,
    #[error(
        "encrypted synchronization document schema, tenant, project, object, kind, or tombstone body is invalid"
    )]
    InvalidSyncDocument,
    #[error("synchronized deletion must use a typed deletion command")]
    SyncDeletionRequiresTypedCommand,
    #[error("synchronized deletion is retention-blocked or unsupported for {0:?}")]
    SyncDeletionUnsupported(SyncObjectKind),
    #[error(
        "synchronized deletion scope, authorization, generation, or causal revision is invalid"
    )]
    InvalidSyncDeletion,
    #[error(
        "project cloud registration requires a scoped Cell, key, authorization, and idempotency key"
    )]
    InvalidProjectCloudRegistration,
    #[error("the project cloud registration idempotency key was reused for another intent")]
    ProjectRegistrationIdempotencyConflict,
    #[error("the local project cloud registration does not match its encrypted request or result")]
    ProjectRegistrationResultMismatch,
    #[error("the project cloud registration is applied, conflicted, or assigned to another Cell")]
    ProjectRegistrationNotDispatchable,
    #[error("encrypted synchronization Cell does not match the project's immutable Cell selection")]
    ProjectDataCellMismatch,
    #[error(
        "encrypted synchronization cannot dispatch before project cloud registration is applied"
    )]
    ProjectCloudRegistrationRequired,
    #[error(
        "the encrypted synchronization idempotency key was reused for another plaintext intent"
    )]
    SyncIdempotencyConflict,
    #[error(
        "the local encrypted synchronization ledger does not match the prepared or remote result"
    )]
    SyncResultMismatch,
    #[error(
        "the encrypted synchronization operation is applied, conflicted, dead-lettered, or assigned to another Cell"
    )]
    SyncOperationNotDispatchable,
    #[error("creator task persistence violated an aggregate invariant")]
    CreatorStateInvariant,
    #[error("verified payment effect does not match the authorized creator payout")]
    CreatorPayoutEffectMismatch,
    #[error("creator recruitment effect, permission guard, receipt or verification is mis-scoped")]
    CreatorHiringEffectMismatch,
    #[error("creator task award does not match the persisted user selection")]
    CreatorHiringAwardMismatch,
    #[error("creator work supports only campaign or continuous_relationship operating mode")]
    InvalidCreatorWorkOperatingMode,
    #[error("a conversation reply effect requires a persisted mission binding")]
    ConversationMissionRequired,
    #[error("the conversation reply effect expiry or exact scope is invalid")]
    InvalidConversationReplyEffect,
    #[error("the durable effect reconciliation cannot be projected into the bound conversation")]
    InvalidEffectReconciliationProjection,
}

