    #[test]
    fn every_machine_registered_application_handler_exists_in_this_binary() {
        let catalog = Catalog::load().expect("valid catalog");
        assert!(!catalog.application_handlers.handlers.is_empty());
        assert!(catalog.application_handlers.handlers.iter().all(|handler| {
            compiled_application_checkpoint_handler(&handler.handler_id).is_some()
        }));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the contract test covers all twelve Catalog routes and their exact authority, checkpoint, Conversation, privacy, and event projections"
    )]
    fn all_twelve_catalog_missions_compile_exact_authority_and_content_free_events() {
        let workspace = tempfile::tempdir().expect("project workspace");
        let project_id = ProjectId::from("catalog-routing-project");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("catalog-routing-tenant"),
                    id: project_id.clone(),
                    name: "Catalog routing".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("project");
        let catalog = Catalog::load().expect("catalog");
        let snapshot = catalog.snapshot().expect("snapshot");

        for manifest in &catalog.missions.missions {
            let mode = match manifest.modes.first().map(String::as_str) {
                Some("build_once") => OperatingMode::BuildOnce,
                Some("continuous_operator") => OperatingMode::ContinuousOperator,
                Some("campaign") => OperatingMode::Campaign,
                Some("continuous_relationship") => OperatingMode::ContinuousRelationship,
                Some("one_off_decision") => OperatingMode::OneOffDecision,
                _ => panic!("validated operating mode"),
            };
            let private_goal = format!(
                "PRIVATE-CATALOG-GOAL::{}::operate only inside the confirmed contract",
                manifest.id
            );
            let mission_id = MissionId::from_stable(format!("catalog-mission-{}", manifest.id));
            let mission = service
                .start_catalog_mission(
                    StartCatalogMission {
                        id: mission_id.clone(),
                        first_task_id: TaskId::from_stable(format!("catalog-task-{}", manifest.id)),
                        project_id: project_id.clone(),
                        manifest_id: manifest.id.clone(),
                        mode: mode.clone(),
                        title: None,
                        goal: private_goal.clone(),
                        market: "DE".into(),
                        language: "de".into(),
                        audience: "confirmed buyers".into(),
                        timezone: "Europe/Berlin".into(),
                        budget: Money::zero(CurrencyCode::parse("EUR").expect("EUR")),
                    },
                    now(),
                )
                .expect("Catalog Mission");
            let definition = mission.definition.as_ref().expect("definition");
            assert_eq!(
                (
                    definition.manifest_id.as_str(),
                    definition.manifest_version,
                    definition.catalog_digest.as_str(),
                    &definition.operating_mode,
                ),
                (
                    manifest.id.as_str(),
                    manifest.version,
                    snapshot.digest.as_str(),
                    &mode,
                )
            );
            assert_eq!(
                definition.capability_ids,
                manifest.capability_ids.iter().cloned().collect()
            );
            assert_eq!(
                definition.required_artifact_types,
                manifest.required_artifacts.iter().cloned().collect()
            );
            assert_eq!(
                definition.oracle_ids,
                manifest.oracle_ids.iter().cloned().collect()
            );
            assert_eq!(definition.checkpoints.len(), manifest.checkpoint_ids.len());
            assert_eq!(
                definition
                    .checkpoints
                    .iter()
                    .map(|checkpoint| {
                        let route = checkpoint.route.as_ref().expect("Checkpoint route");
                        (
                            checkpoint.id.as_str(),
                            route.capability_id.as_str(),
                            route.executor,
                        )
                    })
                    .collect::<Vec<_>>(),
                manifest
                    .checkpoint_routes
                    .iter()
                    .map(|route| (
                        route.checkpoint_id.as_str(),
                        route.capability_id.as_str(),
                        MissionCheckpointExecutor::try_from(route.executor.as_str())
                            .expect("validated executor"),
                    ))
                    .collect::<Vec<_>>()
            );
            assert_eq!(
                definition
                    .current_checkpoint()
                    .map(|checkpoint| (checkpoint.id.as_str(), checkpoint.status)),
                manifest
                    .checkpoint_ids
                    .first()
                    .map(|checkpoint| (checkpoint.as_str(), MissionCheckpointStatus::Running))
            );
            assert_eq!(
                mission.contract.enabled_capabilities,
                definition.capability_ids
            );
            assert!(
                mission
                    .contract
                    .enabled_capabilities
                    .is_disjoint(&mission.contract.forbidden_capabilities)
            );
            assert_eq!(mission.stage, MissionStage::Running);
            assert_eq!(
                mission.tasks.first().map(|task| task.capability.as_str()),
                manifest
                    .checkpoint_routes
                    .first()
                    .map(|route| route.capability_id.as_str())
            );
            if manifest.id == "VM-10" {
                assert_eq!(
                    mission.tasks.first().map(|task| task.capability.as_str()),
                    Some("webhook.ingest")
                );
                assert_ne!(
                    mission.tasks.first().map(|task| task.capability.as_str()),
                    definition.capability_ids.iter().next().map(String::as_str)
                );
            }
            let conversation = service
                .mission_conversation(&project_id, &mission_id)
                .expect("Catalog Mission Conversation");
            assert_eq!(conversation.revision, 1);
            assert_eq!(conversation.messages.len(), 1);
            assert_eq!(conversation.messages[0].body, private_goal);
            let event_json = serde_json::to_string(
                &service
                    .mission_events(&project_id, &mission_id)
                    .expect("events"),
            )
            .expect("event JSON");
            assert!(!event_json.contains(&private_goal));
            assert!(event_json.contains("mission.catalog_bound"));
            assert!(event_json.contains("mission.checkpoint_started"));
        }

        let projections = service
            .desktop_inventory()
            .expect("inventory")
            .projects
            .into_iter()
            .find(|project| project.project_id == project_id)
            .expect("project")
            .missions;
        assert_eq!(projections.len(), 12);
        assert!(projections.iter().all(|projection| {
            projection.manifest_id.is_some()
                && projection.manifest_version.is_some()
                && projection.catalog_digest.as_deref() == Some(snapshot.digest.as_str())
                && projection.current_checkpoint_id.is_some()
                && projection.current_checkpoint_status == Some(MissionCheckpointStatus::Running)
                && projection.current_checkpoint_capability_id.is_some()
                && projection.current_checkpoint_executor.is_some()
                && projection.completed_checkpoint_count == 0
                && projection.checkpoint_count > 0
                && projection.conversation_revision == Some(1)
                && projection.conversation_messages.len() == 1
                && projection.conversation_messages[0].body.is_empty()
                && projection.title.is_empty()
                && projection.goal.is_empty()
                && projection.outcome_summary.is_none()
        }));
    }

