        let ApplicationMissionCheckpointExecution::Completed {
            completion_evidence_digest,
            outcome_ledger_revision,
            replayed,
            next_dispatch,
            ..
        } = completed
        else {
            panic!("event_ingest must complete from the verified ledger")
        };
        assert_eq!((outcome_ledger_revision, replayed), (2, false));
        let next_dispatch = next_dispatch.expect("next Application route");
