    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the replay keeps first-route proof, verified transition, next-route atomic start, and idempotent dispatch fencing in one ordered Journey"
    )]
    fn checkpoint_dispatch_advances_ready_dag_once_and_never_crosses_executor() {
        let workspace = tempfile::tempdir().expect("project workspace");
        let project_id = ProjectId::from("checkpoint-dispatch-project");
        let mission_id = MissionId::from("checkpoint-dispatch-mission");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("checkpoint-dispatch-tenant"),
                    id: project_id.clone(),
                    name: "Checkpoint dispatch".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("project");
        service
            .start_catalog_mission(
                StartCatalogMission {
                    id: mission_id.clone(),
                    first_task_id: TaskId::from("checkpoint-dispatch-task-1"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-04".into(),
                    mode: OperatingMode::Campaign,
                    title: Some("Social matrix".into()),
                    goal: "Route every Checkpoint to only its frozen executor".into(),
                    market: "US".into(),
                    language: "en-US".into(),
                    audience: "owner".into(),
                    timezone: "America/New_York".into(),
                    budget: Money::zero(CurrencyCode::parse("USD").expect("USD")),
                },
                now(),
            )
            .expect("VM-04 Mission");

        let runtime = service
            .dispatch_current_mission_checkpoint(
                &project_id,
                &mission_id,
                now() + Duration::milliseconds(1),
            )
            .expect("exact first dispatch");
        assert_eq!(runtime.checkpoint_id, "audience_channel_fit");
        assert_eq!(runtime.capability_id, "social.plan");
        assert_eq!(runtime.executor, MissionCheckpointExecutor::Runtime);
        assert_eq!(runtime.state, MissionCheckpointDispatchState::Ready);

        let completion = prepare_catalog_checkpoint_oracle_evidence(
            &mut service,
            &project_id,
            &mission_id,
            &runtime.checkpoint_id,
            0,
            now() + Duration::milliseconds(2),
        );
        service
            .complete_mission_checkpoint(
                &project_id,
                &mission_id,
                &runtime.checkpoint_id,
                completion,
            )
            .expect("first Checkpoint completion");
        let ready_revision = service
            .load_mission(&project_id, &mission_id)
            .expect("Mission with next Ready Checkpoint")
            .revision;

        let application = service
            .dispatch_current_mission_checkpoint(
                &project_id,
                &mission_id,
                now() + Duration::milliseconds(4),
            )
            .expect("start exact next Checkpoint");
        assert_eq!(application.checkpoint_id, "account_scope_probe");
        assert_eq!(application.capability_id, "connection.probe");
        assert_eq!(application.executor, MissionCheckpointExecutor::Application);
        assert_eq!(application.state, MissionCheckpointDispatchState::Ready);
        assert!(application.mission_revision > ready_revision);
        let before_unsupported_completion = service
            .load_mission(&project_id, &mission_id)
            .expect("Application route before generic completion rejection");
        assert!(matches!(
            service.complete_mission_checkpoint(
                &project_id,
                &mission_id,
                &application.checkpoint_id,
                MissionCheckpointCompletion {
                    oracle_ids: application.oracle_ids.clone(),
                    work_product_ids: BTreeSet::new(),
                    effect_ids: BTreeSet::new(),
                    application_evidence: None,
                    evidence_digest: "a".repeat(64),
                    verified_at: now() + Duration::milliseconds(5),
                },
            ),
            Err(ApplicationError::ApplicationCheckpointExecutionRequired)
        ));
        assert_eq!(
            service
                .load_mission(&project_id, &mission_id)
                .expect("unchanged Application route"),
            before_unsupported_completion
        );
        let event_count = service
            .mission_events(&project_id, &mission_id)
            .expect("events")
            .len();

        let replay = service
            .dispatch_current_mission_checkpoint(
                &project_id,
                &mission_id,
                now() + Duration::milliseconds(5),
            )
            .expect("idempotent dispatch read");
        assert_eq!(replay, application);
        assert_eq!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("unchanged events")
                .len(),
            event_count
        );
        let mission = service
            .load_mission(&project_id, &mission_id)
            .expect("dispatched Mission");
        assert_eq!(
            mission
                .tasks
                .iter()
                .filter(|task| task.status == TaskStatus::Running)
                .map(|task| task.capability.as_str())
                .collect::<Vec<_>>(),
            vec!["connection.probe"]
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the test proves bypass rejection, dual revision fencing, atomic completion and next-route start, content-free evidence, replay, and payload-swap rejection in one Human Journey"
    )]
    fn human_checkpoint_confirmation_is_atomic_replayable_and_starts_the_exact_next_route() {
        let workspace = tempfile::tempdir().expect("project workspace");
        let project_id = ProjectId::from("human-checkpoint-project");
        let mission_id = MissionId::from("human-checkpoint-mission");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("human-checkpoint-tenant"),
                    id: project_id.clone(),
                    name: "Human checkpoint".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("project");
        service
            .start_catalog_mission(
                StartCatalogMission {
                    id: mission_id.clone(),
                    first_task_id: TaskId::from("human-checkpoint-task-1"),
                    project_id: project_id.clone(),
                    manifest_id: "VM-07".into(),
                    mode: OperatingMode::OneOffDecision,
                    title: Some("Germany market decision".into()),
                    goal: "Decide whether Germany fits a fixed budget".into(),
                    market: "DE".into(),
                    language: "de-DE".into(),
                    audience: "owner".into(),
                    timezone: "Europe/Berlin".into(),
                    budget: Money::zero(CurrencyCode::parse("EUR").expect("EUR")),
                },
                now(),
            )
            .expect("VM-07 Mission");
        let before = service
            .load_mission(&project_id, &mission_id)
            .expect("Mission before confirmation");
        let checkpoint = before
            .definition
            .as_ref()
            .and_then(MissionDefinition::current_checkpoint)
            .cloned()
            .expect("Human Checkpoint");
        assert_eq!(checkpoint.id, "product_market_budget_constraints");
        assert_eq!(
            checkpoint.route.as_ref().map(|route| route.executor),
            Some(MissionCheckpointExecutor::Human)
        );
        assert!(matches!(
            service.begin_mission_checkpoint_verification(
                &project_id,
                &mission_id,
                &checkpoint.id,
                now() + Duration::milliseconds(1),
            ),
            Err(ApplicationError::HumanCheckpointConfirmationRequired)
        ));
        assert_eq!(
            service
                .load_mission(&project_id, &mission_id)
                .expect("bypass leaves Mission unchanged"),
            before
        );

        let conversation_before = service
            .mission_conversation(&project_id, &mission_id)
            .expect("Conversation before confirmation");
        let command = ConfirmHumanMissionCheckpoint {
            project_id: project_id.clone(),
            mission_id: mission_id.clone(),
            checkpoint_id: checkpoint.id.clone(),
            message_id: MissionConversationMessageId::from("human-checkpoint-confirmation-1"),
            body: "Budget, market, product and non-goals are correct; proceed.".into(),
            idempotency_key: "human-checkpoint-confirmation:1".into(),
            work_product_ids: BTreeSet::new(),
            expected_mission_revision: before.revision,
            expected_checkpoint_revision: checkpoint.revision,
            expected_conversation_revision: conversation_before.revision,
        };
        let events_before = service
            .mission_events(&project_id, &mission_id)
            .expect("events before confirmation")
            .len();
        let confirmed = service
            .confirm_human_mission_checkpoint(command.clone(), now() + Duration::milliseconds(2))
            .expect("atomic Human confirmation");
        assert_eq!(confirmed.conversation.revision, 2);
        assert_eq!(confirmed.message.sequence, 2);
        assert_eq!(
            confirmed.message.kind,
            MissionConversationMessageKind::CheckpointConfirmation
        );
        assert_eq!(
            confirmed.message.mission_revision,
            command.expected_mission_revision
        );
        let completed = confirmed
            .mission
            .definition
            .as_ref()
            .and_then(|definition| {
                definition
                    .checkpoints
                    .iter()
                    .find(|candidate| candidate.id == command.checkpoint_id)
            })
            .expect("completed Human Checkpoint");
        assert_eq!(completed.status, MissionCheckpointStatus::Completed);
        assert_eq!(
            completed
                .completion
                .as_ref()
                .map(|completion| &completion.evidence_digest),
            Some(&confirmed.completion_evidence_digest)
        );
        let next = confirmed
            .next_dispatch
            .as_ref()
            .expect("next route started");
        assert_eq!(next.checkpoint_id, "evidence_plan");
        assert_eq!(next.capability_id, "research.discover");
        assert_eq!(next.executor, MissionCheckpointExecutor::Runtime);
        assert_eq!(next.state, MissionCheckpointDispatchState::Ready);
        assert!(confirmed.mission.tasks.iter().any(|task| {
            task.status == TaskStatus::Running && task.capability == "research.discover"
        }));
        let event_json = serde_json::to_string(
            &service
                .mission_events(&project_id, &mission_id)
                .expect("confirmation events"),
        )
        .expect("event JSON");
        assert!(!event_json.contains(&command.body));
        assert!(event_json.contains("mission.human_checkpoint_confirmed"));
        assert!(event_json.contains("mission.checkpoint_completed"));
        assert!(event_json.contains("mission.checkpoint_started"));

        let replay = service
            .confirm_human_mission_checkpoint(command.clone(), now() + Duration::milliseconds(3))
            .expect("exact confirmation replay");
        assert_eq!(replay, confirmed);
        assert_eq!(
            service
                .mission_events(&project_id, &mission_id)
                .expect("replay events")
                .len(),
            events_before + 3
        );
        let mut swapped = command;
        swapped.body = "Change the budget after approval.".into();
        assert!(matches!(
            service.confirm_human_mission_checkpoint(swapped, now() + Duration::milliseconds(4)),
            Err(ApplicationError::HumanCheckpointConfirmationReplayMismatch)
        ));
        assert_eq!(
            service
                .load_mission(&project_id, &mission_id)
                .expect("payload swap leaves Mission unchanged"),
            confirmed.mission
        );
    }

