    #[test]
    fn scheduler_startup_reconciliation_closes_contract_expiry_exactly_once() {
        let workspace = tempfile::tempdir().expect("project workspace");
        let project_id = ProjectId::from("scheduler-expiry-project");
        let mission_id = MissionId::from("scheduler-expiry-mission");
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("scheduler-expiry-tenant"),
                    id: project_id.clone(),
                    name: "Scheduler expiry".into(),
                    description: String::new(),
                    workspace_root: workspace.path().to_path_buf(),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("project");
        service
            .start_relationship_mission(
                StartRelationshipMission {
                    id: mission_id.clone(),
                    project_id: project_id.clone(),
                    task_id: TaskId::from("scheduler-expiry-cycle-1"),
                    title: "Bounded inbox operator".into(),
                    goal: "Stop honestly at the Operating Contract boundary".into(),
                },
                now(),
            )
            .expect("mission");
        let contract_valid_until = service
            .load_mission(&project_id, &mission_id)
            .expect("mission")
            .contract
            .valid_until;
        service
            .record_outcome(
                &project_id,
                &mission_id,
                "Initial relationship cycle reviewed",
                OutcomeDecision::Continue,
                BTreeMap::new(),
                now() + Duration::seconds(1),
            )
            .expect("schedule cycle two");
        assert_eq!(
            service
                .reconcile_mission_schedules_on_startup(
                    contract_valid_until - Duration::seconds(1),
                )
                .expect("before boundary"),
            MissionScheduleStartupReconciliation::default()
        );
        let report = service
            .reconcile_mission_schedules_on_startup(contract_valid_until)
            .expect("contract expiry");
        assert_eq!(report.scanned_schedules, 1);
        assert_eq!(report.expired_schedules, 1);
        assert_eq!(report.completed_missions, 1);
        assert_eq!(report.event_sequences.len(), 2);
        assert_eq!(report.outbox_sequences.len(), 2);
        let projection = service
            .projection(&project_id, &mission_id, WorkSurface::Orchestrator)
            .expect("projection");
        assert_eq!(projection.stage, MissionStage::Completed);
        assert_eq!(
            projection.schedule.as_ref().map(|schedule| schedule.status),
            Some(MissionScheduleStatus::Expired)
        );
        assert_eq!(
            service
                .reconcile_mission_schedules_on_startup(
                    contract_valid_until + Duration::seconds(1),
                )
                .expect("idempotent replay"),
            MissionScheduleStartupReconciliation::default()
        );
        let event_json = serde_json::to_string(
            &service
                .mission_events(&project_id, &mission_id)
                .expect("events"),
        )
        .expect("event json");
        assert!(event_json.contains("mission.schedule_expired"));
        assert!(event_json.contains("operating_contract_expired"));
        assert!(event_json.contains("\"externalEffectReplayed\":false"));
    }

