    #[cfg(unix)]
    #[test]
    fn startup_scan_freezes_every_ambiguous_turn_before_any_new_dispatch() {
        let turn_id = RuntimeTurnAttemptId::from("turn-attempt-startup-orphan");
        let runtime_turn_id = "private-runtime-turn-startup-orphan";
        let mut fixture = ready_runtime_turn_fixture(|workspace| {
            turn_dispatch_fault_runtime_command(
                workspace,
                "private-runtime-thread-startup-orphan",
                Some(serde_json::json!({
                    "jsonrpc": "2.0",
                    "id": 3,
                    "result": {"turn": {"id": runtime_turn_id, "status": "inProgress"}}
                })),
            )
        });
        let initial_command =
            dispatch_command(&fixture, turn_id.as_str(), StdDuration::from_secs(1));
        let dispatch = fixture
            .fixture
            .service
            .dispatch_context_runtime_turn(
                &mut fixture.managed,
                initial_command,
                &fixture.envelope,
                now() + Duration::seconds(6),
            )
            .expect("running turn before coordinator crash");
        assert_eq!(dispatch.attempt.status, RuntimeTurnStatus::Running);
        let project_id = fixture.fixture.project_id.clone();
        let ReadyRuntimeTurnFixture {
            fixture: mut runtime_fixture,
            managed,
            ..
        } = fixture;
        let process_claim = runtime_fixture
            .service
            .shutdown_managed_context_runtime(managed, now() + Duration::seconds(7))
            .expect("process cleanup commits before simulated coordinator crash");
        assert_eq!(process_claim.status, RuntimeProcessClaimStatus::Terminated);
        let store = runtime_fixture.service.store;
        let mut restarted = ApplicationService::new(store);
        let report = restarted
            .reconcile_runtime_turns_on_startup(now() + Duration::seconds(8))
            .expect("atomic startup scan");
        assert_eq!(report.scanned_attempts, 1);
        assert_eq!(report.failed_before_dispatch, 0);
        assert_eq!(report.frozen_uncertain, 1);
        assert_eq!(report.already_safe, 0);
        assert_eq!(report.event_sequences.len(), 1);
        assert!(!format!("{report:?}").contains(runtime_turn_id));
        let orphan = restarted
            .runtime_turn_attempt(&project_id, &turn_id)
            .expect("frozen orphan");
        assert_eq!(orphan.status, RuntimeTurnStatus::Uncertain);
        assert_eq!(
            orphan.failures.last().expect("restart failure").class,
            RuntimeTurnFailureClass::CoordinatorRestart
        );
        let replay = restarted
            .reconcile_runtime_turns_on_startup(now() + Duration::seconds(10))
            .expect("idempotent startup scan");
        assert_eq!(replay.scanned_attempts, 1);
        assert_eq!(replay.already_safe, 1);
        assert!(replay.event_sequences.is_empty());
    }

