    #[cfg(unix)]
    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the replay materializes a durable ThreadBound crash boundary, proves forged resume input cannot consume retry budget, then resumes only the bound thread"
    )]
    fn coordinator_restart_resumes_only_the_durably_bound_thread() {
        let mut fixture = runtime_recovery_fixture();
        let runtime_thread_id = "private-orphan-bound-thread";
        let runtime_command =
            delayed_fake_runtime_command(fixture.workspace.path(), runtime_thread_id, "0.20");
        let recovery_id = RuntimeRecoveryAttemptId::from("recovery-coordinator-restart");
        assert!(matches!(
            fixture.service.recover_context_worker_runtime(
                RecoverContextWorkerRuntime {
                    id: recovery_id.clone(),
                    project_id: fixture.project_id.clone(),
                    workspace_id: fixture.workspace_id.clone(),
                    worker_id: fixture.worker_id.clone(),
                    expected_handle_revision: 1,
                    expected_mailbox_revision: 1,
                    attachment_epoch: 1,
                    strategy: RuntimeResumeStrategy::StartNew,
                    resume_thread_id: None,
                    model: Some("fixture-model".into()),
                    max_process_attempts: 3,
                    health_timeout: StdDuration::from_millis(20),
                    thread_timeout: StdDuration::from_secs(1),
                },
                &runtime_command,
                now() + Duration::seconds(3),
            ),
            Err(ApplicationError::Runtime(
                AdapterError::HealthCheckTimedOut { .. }
            ))
        ));
        let mut attempt = fixture
            .service
            .runtime_recovery_attempt(&fixture.project_id, &recovery_id)
            .expect("retryable recovery");
        let expected_revision = attempt.revision;
        attempt
            .mark_spawned("d".repeat(64), now() + Duration::seconds(4))
            .expect("durable orphan spawn projection");
        fixture
            .service
            .store
            .update_runtime_recovery(
                &attempt,
                expected_revision,
                &[PendingEvent::new(
                    "context.runtime_recovery_spawned",
                    serde_json::json!({"recoveryId": attempt.id}),
                    now() + Duration::seconds(4),
                )],
                now() + Duration::seconds(4),
            )
            .expect("persist orphan spawn");
        let expected_revision = attempt.revision;
        attempt
            .confirm_health("e".repeat(64), now() + Duration::seconds(5))
            .expect("durable orphan health projection");
        fixture
            .service
            .store
            .update_runtime_recovery(
                &attempt,
                expected_revision,
                &[PendingEvent::new(
                    "context.runtime_recovery_healthy",
                    serde_json::json!({"recoveryId": attempt.id}),
                    now() + Duration::seconds(5),
                )],
                now() + Duration::seconds(5),
            )
            .expect("persist orphan health");
        let expected_revision = attempt.revision;
        attempt
            .bind_thread(
                &"d".repeat(64),
                runtime_thread_id.into(),
                "f".repeat(64),
                now() + Duration::seconds(6),
            )
            .expect("durable orphan thread binding");
        fixture
            .service
            .store
            .update_runtime_recovery(
                &attempt,
                expected_revision,
                &[PendingEvent::new(
                    "context.runtime_recovery_thread_bound",
                    serde_json::json!({"recoveryId": attempt.id}),
                    now() + Duration::seconds(6),
                )],
                now() + Duration::seconds(6),
            )
            .expect("persist orphan binding");

        let before_forged_retry = attempt.clone();
        assert!(matches!(
            fixture.service.retry_context_worker_runtime(
                RetryContextWorkerRuntime {
                    project_id: fixture.project_id.clone(),
                    recovery_id: recovery_id.clone(),
                    expected_attempt_revision: attempt.revision,
                    expected_handle_revision: 2,
                    expected_mailbox_revision: 1,
                    resume_thread_id: Some("forged-orphan-thread".into()),
                    model: Some("fixture-model".into()),
                    health_timeout: StdDuration::from_secs(2),
                    thread_timeout: StdDuration::from_secs(2),
                },
                &runtime_command,
                now() + Duration::seconds(7),
            ),
            Err(ApplicationError::RuntimeRecoveryResumeThreadMismatch)
        ));
        assert_eq!(
            fixture
                .service
                .runtime_recovery_attempt(&fixture.project_id, &recovery_id)
                .expect("forged orphan retry is side-effect free"),
            before_forged_retry
        );

        let managed = fixture
            .service
            .retry_context_worker_runtime(
                RetryContextWorkerRuntime {
                    project_id: fixture.project_id.clone(),
                    recovery_id: recovery_id.clone(),
                    expected_attempt_revision: attempt.revision,
                    expected_handle_revision: 2,
                    expected_mailbox_revision: 1,
                    resume_thread_id: None,
                    model: Some("fixture-model".into()),
                    health_timeout: StdDuration::from_secs(2),
                    thread_timeout: StdDuration::from_secs(2),
                },
                &runtime_command,
                now() + Duration::seconds(8),
            )
            .expect("resume exact orphan binding");
        assert_eq!(managed.recovery.status, RuntimeRecoveryStatus::Attached);
        assert_eq!(managed.recovery.process_attempt, 3);
        assert_eq!(managed.recovery.failures.len(), 2);
        assert_eq!(
            managed.recovery.failures[1].class,
            RuntimeRecoveryFailureClass::CoordinatorRestart
        );
        assert_eq!(managed.mapping.runtime_thread_id, runtime_thread_id);
        let events = serde_json::to_string(
            &fixture
                .service
                .mission_events(&fixture.project_id, &fixture.mission_id)
                .expect("events"),
        )
        .expect("events serialize");
        assert!(!events.contains(runtime_thread_id));
        assert!(events.contains("context.runtime_recovery_orphan_fenced"));
        assert!(managed.runtime.shutdown().expect("shutdown").forced);
    }

    #[test]
    fn compiler_preserves_approval_and_budget_constraints() {
        let contract = compile_contract("准备新品测试，预算 10,000 元；未经我批准不要发布", now());
        assert!(
            contract
                .constraints
                .iter()
                .any(|constraint| matches!(constraint, Constraint::RequireApproval { .. }))
        );
        assert!(contract.constraints.iter().any(|constraint| matches!(
            constraint,
            Constraint::Budget {
                amount_minor: 1_000_000,
                currency
            } if currency == "CNY"
        )));
        assert!(contract.forbidden_capabilities.contains("payment.execute"));
    }

    #[test]
    fn identity_conflict_review_is_persisted_as_one_decision_per_revision() {
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        let tenant_id = TenantId::from("tenant-identity-review");
        let project_id = ProjectId::from("project-identity-review");
        service
            .create_project(
                CreateProject {
                    tenant_id: tenant_id.clone(),
                    id: project_id.clone(),
                    name: "Identity review".into(),
                    description: String::new(),
                    workspace_root: PathBuf::from("/tmp/hartevo-identity-review"),
                    storage_mode: StorageMode::LocalExisting,
                },
                now(),
            )
            .expect("project");
        let company = service
            .create_company(
                Company::create(
                    hartevo_domain_kernel::CompanyId::from("company-identity-review"),
                    tenant_id.clone(),
                    project_id.clone(),
                    "Reviewed customer",
                    "DE",
                )
                .expect("company"),
                now(),
            )
            .expect("company persisted");
        let link_id = IdentityLinkId::from("identity-review-link");
        service
            .create_identity_link(
                IdentityLink::propose(
                    link_id.clone(),
                    tenant_id,
                    project_id.clone(),
                    IdentitySubject::Company(company.id),
                    [ExternalIdentity {
                        provider: "commerce-fixture".into(),
                        account_id: AccountId::from("identity-review-account"),
                        external_subject_digest: "1".repeat(64),
                        encrypted_subject_ref: "ciphertext://identity-review/customer".into(),
                        evidence_digest: "2".repeat(64),
                    }],
                    Decimal::ONE,
                )
                .expect("proposal"),
                now(),
            )
            .expect("proposal persisted");
        let confirmed = service
            .confirm_identity_link(
                &project_id,
                &link_id,
                ActorId::from("reviewer-1"),
                "2".repeat(64),
                now(),
            )
            .expect("confirmed");
        assert_eq!(confirmed.revision, 2);
        let conflicted = service
            .mark_identity_link_conflicted(
                &project_id,
                &link_id,
                ActorId::from("reviewer-2"),
                "3".repeat(64),
                now() + chrono::Duration::minutes(1),
            )
            .expect("conflicted");
        assert_eq!(conflicted.revision, 3);
        assert!(!conflicted.confirms_external_identity(
            "commerce-fixture",
            &AccountId::from("identity-review-account")
        ));
        let rejected = service
            .reject_identity_link(
                &project_id,
                &link_id,
                ActorId::from("reviewer-3"),
                "4".repeat(64),
                now() + chrono::Duration::minutes(2),
            )
            .expect("rejected");
        assert_eq!(rejected.status, IdentityLinkStatus::Rejected);
        assert_eq!(rejected.decisions.len(), 3);
        assert!(matches!(
            service.confirm_identity_link(
                &project_id,
                &link_id,
                ActorId::from("reviewer-4"),
                "5".repeat(64),
                now() + chrono::Duration::minutes(3),
            ),
            Err(ApplicationError::Identity(
                IdentityError::InvalidIdentityLinkTransition
            ))
        ));
    }

    #[test]
    fn two_work_surfaces_share_the_same_mission_revision() {
        let store = ProjectStore::in_memory().expect("store");
        let mut service = ApplicationService::new(store);
        let project_id = ProjectId::from("project-1");
        let mission_id = MissionId::from("mission-1");
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("tenant-1"),
                    id: project_id.clone(),
                    name: "North America launch".into(),
                    description: String::new(),
                    workspace_root: PathBuf::from("/tmp/hartevo-project-1"),
                    storage_mode: StorageMode::LocalExisting,
                },
                now(),
            )
            .expect("project");
        service
            .start_mission(
                StartMission {
                    id: mission_id.clone(),
                    research_task_id: TaskId::from("task-1"),
                    project_id: project_id.clone(),
                    title: None,
                    prompt: "研究新品机会，未经我批准不要发布".into(),
                },
                now(),
            )
            .expect("mission");

        let orchestrator = service
            .projection(&project_id, &mission_id, WorkSurface::Orchestrator)
            .expect("orchestrator");
        let channels = service
            .projection(&project_id, &mission_id, WorkSurface::ChannelOperations)
            .expect("channels");

        assert_eq!(orchestrator.mission_id, channels.mission_id);
        assert_eq!(orchestrator.revision, channels.revision);
        assert_eq!(orchestrator.stage, channels.stage);
        assert_ne!(orchestrator.surface, channels.surface);
    }

