    fn relationship_reply_command(
        project_id: &ProjectId,
        conversation_id: &ConversationId,
        connection_id: &ConnectionId,
        consent_id: &ConsentRecordId,
        effect_id: &EffectId,
        message_id: &str,
    ) -> PrepareConversationReplyEffect {
        PrepareConversationReplyEffect {
            project_id: project_id.clone(),
            conversation_id: conversation_id.clone(),
            message_id: MessageId::from_stable(message_id),
            content_digest: "7".repeat(64),
            effect_id: effect_id.clone(),
            actor_id: ActorId::from("agent-1"),
            provider: "gmail".into(),
            connection_id: Some(connection_id.clone()),
            account_id: Some(AccountId::from("gmail-account-1")),
            required_scopes: BTreeSet::from(["messages.send".into()]),
            authorization: ReplyAuthorization::Consent(consent_id.clone()),
            policy_version: "relationship-policy-v1".into(),
            idempotency_key: format!("{effect_id}:v1"),
            currency: CurrencyCode::parse("EUR").expect("EUR"),
            scheduled_for: None,
            timezone: "Europe/Berlin".into(),
            expires_in: Duration::hours(1),
        }
    }

    fn relationship_policy_broker() -> EffectBroker {
        EffectBroker::new(
            EffectPolicy {
                version: "relationship-policy-v1".into(),
                allowed_capabilities: BTreeSet::from(["conversation.reply".into()]),
                allowed_classes: BTreeSet::from([EffectClass::Outreach]),
                max_amounts_minor: [(CurrencyCode::parse("EUR").expect("EUR"), 0)]
                    .into_iter()
                    .collect(),
                rate_limits: vec![EffectRateLimit {
                    rule_id: "gmail-conversation-reply-per-minute".into(),
                    provider: "gmail".into(),
                    capability: "conversation.reply".into(),
                    max_executions: 60,
                    window_seconds: 60,
                }],
            },
            "relationship-application-worker",
        )
    }

    #[test]
    fn personal_project_key_is_wrapped_for_device_and_user_held_recovery() {
        let store = ProjectStore::in_memory().expect("store");
        let mut service = ApplicationService::new(store);
        let secrets = hartevo_storage::MemorySecretStore::default();
        let tenant_id = TenantId::from("tenant-encrypted");
        let project_id = ProjectId::from("project-encrypted");
        let recipient = KeyRecipient::Device(DeviceId::from("device-1"));
        service
            .create_project(
                CreateProject {
                    tenant_id: tenant_id.clone(),
                    id: project_id.clone(),
                    name: "Encrypted sync".into(),
                    description: String::new(),
                    workspace_root: PathBuf::from("/tmp/hartevo-encrypted-sync"),
                    storage_mode: StorageMode::LocalEncryptedSync,
                },
                now(),
            )
            .expect("project");
        let provisioned = service
            .provision_project_encryption(
                &secrets,
                ProvisionProjectEncryption {
                    project_id: project_id.clone(),
                    mode: ProjectEncryptionMode::PersonalE2ee,
                    primary_recipient: recipient.clone(),
                    recovery_recipient_id: Some("recovery-kit-1".into()),
                },
                now(),
            )
            .expect("provision encryption");
        assert_eq!(provisioned.keyring.envelopes.len(), 2);
        let recovery_secret = provisioned.recovery_secret.expect("recovery secret");
        assert!(format!("{recovery_secret:?}").contains("[REDACTED]"));

        let primary_envelope = provisioned
            .keyring
            .active_envelope_for(&recipient, now())
            .expect("primary envelope");
        let primary_reference = SecretReference {
            tenant_id: tenant_id.clone(),
            project_id: project_id.clone(),
            provider: "os-native".into(),
            account_scope: recipient.stable_scope(),
            purpose: format!("project_wrapping_key:{}", primary_envelope.id),
            version: 1,
        };
        let primary_wrapping = KeyMaterial::from_secret(
            &secrets
                .get(&primary_reference)
                .expect("device wrapping key"),
        )
        .expect("device key material");
        let primary_context = EnvelopeContext {
            tenant_id: tenant_id.clone(),
            project_id: project_id.clone(),
            key_version: 1,
            recipient: recipient.clone(),
            purpose: "project_content_key".into(),
            expires_at: None,
        };
        let opened_primary = EnvelopeCrypto::open_key(
            &primary_envelope.sealed_key,
            &primary_wrapping,
            &primary_context,
        )
        .expect("device unwrap");
        let recovery_recipient = KeyRecipient::Recovery("recovery-kit-1".into());
        let recovery_envelope = provisioned
            .keyring
            .active_envelope_for(&recovery_recipient, now())
            .expect("recovery envelope");
        let recovery_context = EnvelopeContext {
            tenant_id,
            project_id: project_id.clone(),
            key_version: 1,
            recipient: recovery_recipient,
            purpose: "project_content_key".into(),
            expires_at: None,
        };
        let opened_recovery = EnvelopeCrypto::open_key(
            &recovery_envelope.sealed_key,
            &KeyMaterial::from_secret(&recovery_secret).expect("recovery key material"),
            &recovery_context,
        )
        .expect("recovery unwrap");
        assert_eq!(
            opened_primary.to_secret().as_slice(),
            opened_recovery.to_secret().as_slice()
        );
        assert_eq!(
            service
                .load_project_keyring(&project_id)
                .expect("persisted keyring"),
            provisioned.keyring
        );
        assert_eq!(secrets.entry_count().expect("secret count"), 1);
    }

    #[test]
    fn user_confirmed_recovery_secret_is_never_escrowed_by_hartevo() {
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        let secrets = MemorySecretStore::default();
        let project_id = ProjectId::from("project-user-recovery");
        let recovery_recipient = KeyRecipient::Recovery("recovery-user-owned".into());
        service
            .create_project(
                CreateProject {
                    tenant_id: TenantId::from("tenant-user-recovery"),
                    id: project_id.clone(),
                    name: "User-owned recovery".into(),
                    description: String::new(),
                    workspace_root: PathBuf::from("/tmp/hartevo-user-recovery"),
                    storage_mode: StorageMode::LocalNew,
                },
                now(),
            )
            .expect("project");
        let user_recovery = SecretBytes::new(vec![91; 32]).expect("user recovery key");
        let provisioned = service
            .provision_project_encryption_with_user_recovery(
                &secrets,
                ProvisionProjectEncryption {
                    project_id: project_id.clone(),
                    mode: ProjectEncryptionMode::PersonalE2ee,
                    primary_recipient: KeyRecipient::Device(DeviceId::from("desktop-device")),
                    recovery_recipient_id: Some("recovery-user-owned".into()),
                },
                &user_recovery,
                now(),
            )
            .expect("provision with exported key");

        assert!(provisioned.recovery_secret.is_none());
        assert_eq!(secrets.entry_count().expect("only device wrapping key"), 1);
        assert!(
            open_project_key_with_recovery_secret(
                &provisioned.keyring,
                &recovery_recipient,
                &user_recovery,
                now(),
            )
            .is_ok()
        );
        assert_eq!(
            service
                .load_project_keyring(&project_id)
                .expect("persisted keyring"),
            provisioned.keyring
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the restart journey proves durable reference recovery, old-version CAS reads, degraded missing-history reporting, wrong-device refusal, and revocation fencing together"
    )]
    fn desktop_context_session_recovers_rotated_keys_without_exposing_key_material() {
        let directory = tempfile::tempdir().expect("database directory");
        let workspace = tempfile::tempdir().expect("project workspace");
        let workspace_root = workspace
            .path()
            .canonicalize()
            .expect("canonical workspace");
        let database_path = directory.path().join("desktop-context-session.sqlite3");
        let database_key = DatabaseKey::new([41; 32]).expect("database key");
        let secrets = hartevo_storage::MemorySecretStore::default();
        let tenant = TenantId::from("tenant-context-session");
        let project = ProjectId::from("project-context-session");
        let owner_device = DeviceId::from("device-context-owner");
        let owner = KeyRecipient::Device(owner_device.clone());
        let member = KeyRecipient::Member(MemberId::from("member-context-revoked"));
        let v1_descriptor;
        let v2_descriptor;
        let owner_v1_reference;
        let owner_v2_reference = SecretReference {
            tenant_id: tenant.clone(),
            project_id: project.clone(),
            provider: "os-native".into(),
            account_scope: owner.stable_scope(),
            purpose: "project_context_owner_wrapping_v2".into(),
            version: 2,
        };
        {
            let store = ProjectStore::open(&database_path, &database_key).expect("encrypted store");
            let mut service = ApplicationService::new(store);
            service
                .create_project(
                    CreateProject {
                        tenant_id: tenant.clone(),
                        id: project.clone(),
                        name: "Restart-safe Context CAS".into(),
                        description: String::new(),
                        workspace_root: workspace_root.clone(),
                        storage_mode: StorageMode::LocalEncryptedSync,
                    },
                    now(),
                )
                .expect("project");
            let provisioned = service
                .provision_project_encryption(
                    &secrets,
                    ProvisionProjectEncryption {
                        project_id: project.clone(),
                        mode: ProjectEncryptionMode::TeamEnvelope,
                        primary_recipient: owner.clone(),
                        recovery_recipient_id: None,
                    },
                    now(),
                )
                .expect("project encryption");
            let owner_v1_envelope = provisioned
                .keyring
                .active_envelope_for(&owner, now())
                .expect("owner v1 envelope");
            owner_v1_reference = SecretReference {
                tenant_id: tenant.clone(),
                project_id: project.clone(),
                provider: "os-native".into(),
                account_scope: owner.stable_scope(),
                purpose: format!("project_wrapping_key:{}", owner_v1_envelope.id),
                version: 1,
            };
            let session = service
                .open_project_context_material_session(&secrets, &project, &owner_device, now())
                .expect("v1 context session");
            assert_eq!(session.readable_key_versions(), &BTreeSet::from([1]));
            v1_descriptor = session
                .put_text("PRIVATE-CONTEXT-V1::durable before rotation")
                .expect("v1 encrypted material");
            assert!(!format!("{session:?}").contains("PRIVATE-CONTEXT-V1"));
            drop(session);

            let member_reference = SecretReference {
                tenant_id: tenant.clone(),
                project_id: project.clone(),
                provider: "os-native".into(),
                account_scope: member.stable_scope(),
                purpose: "project_context_member_wrapping_v1".into(),
                version: 1,
            };
            secrets
                .put(
                    &member_reference,
                    &KeyMaterial::from_bytes([42; 32])
                        .expect("member wrapping key")
                        .to_secret(),
                )
                .expect("store member key");
            service
                .grant_project_key_recipient(
                    &secrets,
                    GrantProjectKeyRecipient {
                        project_id: project.clone(),
                        expected_keyring_revision: 1,
                        authorizing_key: RecipientKeyReference {
                            recipient: owner.clone(),
                            reference: owner_v1_reference.clone(),
                        },
                        recipient_key: RecipientKeyReference {
                            recipient: member.clone(),
                            reference: member_reference,
                        },
                        authorization: key_admin_authorization(),
                    },
                    now() + Duration::minutes(1),
                )
                .expect("grant member");
            secrets
                .put(
                    &owner_v2_reference,
                    &KeyMaterial::from_bytes([43; 32])
                        .expect("owner v2 wrapping key")
                        .to_secret(),
                )
                .expect("store owner v2 key");
            service
                .revoke_and_rotate_project_key(
                    &secrets,
                    RevokeAndRotateProjectKey {
                        project_id: project.clone(),
                        expected_keyring_revision: 2,
                        authorizing_key: RecipientKeyReference {
                            recipient: owner.clone(),
                            reference: owner_v1_reference.clone(),
                        },
                        revoked_recipient: member,
                        retained_recipient_keys: vec![RecipientKeyReference {
                            recipient: owner.clone(),
                            reference: owner_v2_reference.clone(),
                        }],
                        authorization: key_admin_authorization(),
                    },
                    now() + Duration::minutes(2),
                )
                .expect("rotate content key");
            let rotated = service
                .open_project_context_material_session(
                    &secrets,
                    &project,
                    &owner_device,
                    now() + Duration::minutes(2),
                )
                .expect("rotated session");
            assert_eq!(rotated.active_key_version(), 2);
            assert_eq!(rotated.readable_key_versions(), &BTreeSet::from([1, 2]));
            assert_eq!(
                rotated
                    .load_text(&v1_descriptor.storage_ref)
                    .expect("load v1")
                    .expect("v1 material")
                    .as_str(),
                "PRIVATE-CONTEXT-V1::durable before rotation"
            );
            v2_descriptor = rotated
                .put_text("PRIVATE-CONTEXT-V2::durable after rotation")
                .expect("v2 encrypted material");
        }

        let reopened = ProjectStore::open(&database_path, &database_key).expect("reopen SQLCipher");
        let mut service = ApplicationService::new(reopened);
        let session = service
            .open_project_context_material_session(
                &secrets,
                &project,
                &owner_device,
                now() + Duration::minutes(3),
            )
            .expect("restart-safe context session");
        assert_eq!(
            (session.keyring_revision(), session.active_key_version()),
            (3, 2)
        );
        assert_eq!(session.readable_key_versions(), &BTreeSet::from([1, 2]));
        assert!(session.unavailable_historical_key_versions().is_empty());
        assert_eq!(
            session
                .load_text(&v1_descriptor.storage_ref)
                .expect("load v1 after restart")
                .expect("v1 after restart")
                .as_str(),
            "PRIVATE-CONTEXT-V1::durable before rotation"
        );
        assert_eq!(
            session
                .load_text(&v2_descriptor.storage_ref)
                .expect("load v2 after restart")
                .expect("v2 after restart")
                .as_str(),
            "PRIVATE-CONTEXT-V2::durable after rotation"
        );
        assert!(matches!(
            service.open_project_context_material_session(
                &secrets,
                &project,
                &DeviceId::from("wrong-device"),
                now() + Duration::minutes(3),
            ),
            Err(ApplicationError::KeyManagement(
                KeyManagementError::RecipientNotFound
            ))
        ));
        drop(session);
        secrets
            .delete(&owner_v1_reference)
            .expect("simulate unavailable historical device key");
        let degraded = service
            .open_project_context_material_session(
                &secrets,
                &project,
                &owner_device,
                now() + Duration::minutes(3),
            )
            .expect("active key remains usable");
        assert_eq!(degraded.readable_key_versions(), &BTreeSet::from([2]));
        assert_eq!(
            degraded.unavailable_historical_key_versions(),
            &BTreeSet::from([1])
        );
        assert!(matches!(
            degraded.load_text(&v1_descriptor.storage_ref),
            Err(ContextMaterialStoreError::MissingKeyVersion)
        ));
        assert!(degraded.load_text(&v2_descriptor.storage_ref).is_ok());
        drop(degraded);

        let successor_device = DeviceId::from("device-context-successor");
        let successor = KeyRecipient::Device(successor_device.clone());
        let successor_v2_reference = SecretReference {
            tenant_id: tenant.clone(),
            project_id: project.clone(),
            provider: "os-native".into(),
            account_scope: successor.stable_scope(),
            purpose: "project_context_successor_wrapping_v2".into(),
            version: 2,
        };
        secrets
            .put(
                &successor_v2_reference,
                &KeyMaterial::from_bytes([44; 32])
                    .expect("successor v2 wrapping key")
                    .to_secret(),
            )
            .expect("store successor v2 key");
        service
            .grant_project_key_recipient(
                &secrets,
                GrantProjectKeyRecipient {
                    project_id: project.clone(),
                    expected_keyring_revision: 3,
                    authorizing_key: RecipientKeyReference {
                        recipient: owner.clone(),
                        reference: owner_v2_reference.clone(),
                    },
                    recipient_key: RecipientKeyReference {
                        recipient: successor.clone(),
                        reference: successor_v2_reference,
                    },
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(4),
            )
            .expect("attach successor at v2");
        let successor_v3_reference = SecretReference {
            tenant_id: tenant,
            project_id: project.clone(),
            provider: "os-native".into(),
            account_scope: successor.stable_scope(),
            purpose: "project_context_successor_wrapping_v3".into(),
            version: 3,
        };
        secrets
            .put(
                &successor_v3_reference,
                &KeyMaterial::from_bytes([45; 32])
                    .expect("successor v3 wrapping key")
                    .to_secret(),
            )
            .expect("store successor v3 key");
        service
            .revoke_and_rotate_project_key(
                &secrets,
                RevokeAndRotateProjectKey {
                    project_id: project.clone(),
                    expected_keyring_revision: 4,
                    authorizing_key: RecipientKeyReference {
                        recipient: owner,
                        reference: owner_v2_reference,
                    },
                    revoked_recipient: KeyRecipient::Device(owner_device.clone()),
                    retained_recipient_keys: vec![RecipientKeyReference {
                        recipient: successor,
                        reference: successor_v3_reference.clone(),
                    }],
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(5),
            )
            .expect("revoke old device and rotate");
        assert!(matches!(
            service.open_project_context_material_session(
                &secrets,
                &project,
                &owner_device,
                now() + Duration::minutes(5),
            ),
            Err(ApplicationError::KeyManagement(
                KeyManagementError::RecipientNotFound
            ))
        ));
        let successor_session = service
            .open_project_context_material_session(
                &secrets,
                &project,
                &successor_device,
                now() + Duration::minutes(5),
            )
            .expect("successor session");
        assert_eq!(successor_session.active_key_version(), 3);
        assert_eq!(
            successor_session.readable_key_versions(),
            &BTreeSet::from([2, 3])
        );
        assert!(
            successor_session
                .load_text(&v2_descriptor.storage_ref)
                .is_ok()
        );
        assert!(matches!(
            successor_session.load_text(&v1_descriptor.storage_ref),
            Err(ContextMaterialStoreError::MissingKeyVersion)
        ));
        drop(successor_session);
        secrets
            .delete(&successor_v3_reference)
            .expect("simulate lost active device key");
        assert!(matches!(
            service.open_project_context_material_session(
                &secrets,
                &project,
                &successor_device,
                now() + Duration::minutes(5),
            ),
            Err(ApplicationError::SecretStore(
                SecretStoreError::SecretNotFound
            ))
        ));
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the recovery replay proves wrong-secret rollback, a distinct new-device secret store, exact envelope decryption, durable attachment, and idempotency fencing"
    )]
    fn personal_recovery_attaches_a_new_device_without_generic_recovery_admin() {
        let mut service = ApplicationService::new(ProjectStore::in_memory().expect("store"));
        let original_device_store = hartevo_storage::MemorySecretStore::default();
        let new_device_store = hartevo_storage::MemorySecretStore::default();
        let tenant = TenantId::from("tenant-personal-recovery");
        let project = ProjectId::from("project-personal-recovery");
        let original_device = KeyRecipient::Device(DeviceId::from("device-original"));
        service
            .create_project(
                CreateProject {
                    tenant_id: tenant.clone(),
                    id: project.clone(),
                    name: "Personal recovery attach".into(),
                    description: String::new(),
                    workspace_root: PathBuf::from("/tmp/hartevo-personal-recovery"),
                    storage_mode: StorageMode::LocalEncryptedSync,
                },
                now(),
            )
            .expect("project");
        let provisioned = service
            .provision_project_encryption(
                &original_device_store,
                ProvisionProjectEncryption {
                    project_id: project.clone(),
                    mode: ProjectEncryptionMode::PersonalE2ee,
                    primary_recipient: original_device,
                    recovery_recipient_id: Some("recovery-kit-device-attach".into()),
                },
                now(),
            )
            .expect("personal keyring");
        let recovery_recipient = KeyRecipient::Recovery("recovery-kit-device-attach".into());
        let recovery_secret = provisioned
            .recovery_secret
            .expect("user-held recovery secret");
        let expected_project_key = open_project_key_with_recovery_secret(
            &provisioned.keyring,
            &recovery_recipient,
            &recovery_secret,
            now(),
        )
        .expect("recovery secret opens the project key");
        let authorization = KeyAdministrationAuthorization {
            actor_id: ActorId::from("personal-owner"),
            evidence_digest: "7".repeat(64),
        };

        assert!(matches!(
            service.recover_personal_project_device(
                &new_device_store,
                RecoverPersonalProjectDevice {
                    project_id: project.clone(),
                    expected_keyring_revision: 1,
                    recovery_recipient_id: "recovery-kit-device-attach".into(),
                    recovery_secret: SecretBytes::new(vec![4; 32]).expect("wrong recovery key"),
                    device_id: DeviceId::from("device-new"),
                    authorization: authorization.clone(),
                    idempotency_key: "personal-recovery-wrong-secret".into(),
                },
                now() + Duration::minutes(1),
            ),
            Err(ApplicationError::SecretStore(
                SecretStoreError::AuthenticationFailed
            ))
        ));
        assert_eq!(new_device_store.entry_count().expect("no orphan key"), 0);
        assert_eq!(
            service
                .load_project_keyring(&project)
                .expect("unchanged keyring")
                .revision,
            1
        );

        let attached = service
            .recover_personal_project_device(
                &new_device_store,
                RecoverPersonalProjectDevice {
                    project_id: project.clone(),
                    expected_keyring_revision: 1,
                    recovery_recipient_id: "recovery-kit-device-attach".into(),
                    recovery_secret,
                    device_id: DeviceId::from("device-new"),
                    authorization: authorization.clone(),
                    idempotency_key: "personal-recovery-device-new".into(),
                },
                now() + Duration::minutes(2),
            )
            .expect("attach recovered device");
        assert!(!attached.duplicate);
        assert_eq!(
            (
                attached.attachment.status,
                attached.attachment.revision,
                attached.keyring.revision,
            ),
            (DeviceAttachmentStatus::Applied, 2, 2)
        );
        assert_eq!(new_device_store.entry_count().expect("one device key"), 1);
        let opened_on_new_device = open_active_project_key(
            &new_device_store,
            &attached.keyring,
            &RecipientKeyReference {
                recipient: KeyRecipient::Device(DeviceId::from("device-new")),
                reference: attached.device_key_reference.clone(),
            },
            now() + Duration::minutes(2),
        )
        .expect("new device opens project key");
        assert_eq!(
            opened_on_new_device.to_secret().as_slice(),
            expected_project_key.to_secret().as_slice()
        );

        let replay = service
            .recover_personal_project_device(
                &new_device_store,
                RecoverPersonalProjectDevice {
                    project_id: project.clone(),
                    expected_keyring_revision: 1,
                    recovery_recipient_id: "recovery-kit-device-attach".into(),
                    recovery_secret: SecretBytes::new(vec![5; 32])
                        .expect("unused on exact applied replay"),
                    device_id: DeviceId::from("device-new"),
                    authorization: authorization.clone(),
                    idempotency_key: "personal-recovery-device-new".into(),
                },
                now() + Duration::minutes(3),
            )
            .expect("idempotent applied recovery replay");
        assert!(replay.duplicate);
        assert_eq!(replay.attachment, attached.attachment);
        assert_eq!(
            new_device_store
                .entry_count()
                .expect("still one device key"),
            1
        );

        assert!(matches!(
            service.recover_personal_project_device(
                &new_device_store,
                RecoverPersonalProjectDevice {
                    project_id: project,
                    expected_keyring_revision: 1,
                    recovery_recipient_id: "recovery-kit-device-attach".into(),
                    recovery_secret: SecretBytes::new(vec![6; 32]).expect("unused conflicting key"),
                    device_id: DeviceId::from("device-other"),
                    authorization,
                    idempotency_key: "personal-recovery-device-new".into(),
                },
                now() + Duration::minutes(4),
            ),
            Err(ApplicationError::DeviceAttachmentIdempotencyConflict)
        ));
    }

    #[test]
    fn failed_duplicate_keyring_provisioning_preserves_the_active_os_secret() {
        let store = ProjectStore::in_memory().expect("store");
        let mut service = ApplicationService::new(store);
        let secrets = hartevo_storage::MemorySecretStore::default();
        let tenant_id = TenantId::from("tenant-encryption-compensation");
        let project_id = ProjectId::from("project-encryption-compensation");
        let recipient = KeyRecipient::Device(DeviceId::from("device-1"));
        service
            .create_project(
                CreateProject {
                    tenant_id: tenant_id.clone(),
                    id: project_id.clone(),
                    name: "Encrypted compensation".into(),
                    description: String::new(),
                    workspace_root: PathBuf::from("/tmp/hartevo-encryption-compensation"),
                    storage_mode: StorageMode::LocalEncryptedSync,
                },
                now(),
            )
            .expect("project");
        let first = service
            .provision_project_encryption(
                &secrets,
                ProvisionProjectEncryption {
                    project_id: project_id.clone(),
                    mode: ProjectEncryptionMode::PersonalE2ee,
                    primary_recipient: recipient.clone(),
                    recovery_recipient_id: Some("recovery-kit-1".into()),
                },
                now(),
            )
            .expect("first provisioning");
        let primary_envelope = first
            .keyring
            .active_envelope_for(&recipient, now())
            .expect("primary envelope");
        let primary_reference = SecretReference {
            tenant_id,
            project_id: project_id.clone(),
            provider: "os-native".into(),
            account_scope: recipient.stable_scope(),
            purpose: format!("project_wrapping_key:{}", primary_envelope.id),
            version: 1,
        };
        let duplicate = service.provision_project_encryption(
            &secrets,
            ProvisionProjectEncryption {
                project_id,
                mode: ProjectEncryptionMode::PersonalE2ee,
                primary_recipient: recipient,
                recovery_recipient_id: Some("replacement-recovery-kit".into()),
            },
            now() + Duration::minutes(1),
        );
        assert!(matches!(duplicate, Err(ApplicationError::Storage(_))));
        assert_eq!(secrets.entry_count().expect("compensated secret count"), 1);
        assert!(secrets.get(&primary_reference).is_ok());
    }

