    fn install_recipient_key(
        secrets: &hartevo_storage::MemorySecretStore,
        tenant: &TenantId,
        project: &ProjectId,
        recipient: KeyRecipient,
        version: u64,
        fill: u8,
    ) -> RecipientKeyReference {
        let reference = SecretReference {
            tenant_id: tenant.clone(),
            project_id: project.clone(),
            provider: "test-recipient-vault".into(),
            account_scope: recipient.stable_scope(),
            purpose: "project_recipient_wrapping_key".into(),
            version,
        };
        secrets
            .put(
                &reference,
                &KeyMaterial::from_bytes([fill; 32])
                    .expect("wrapping key")
                    .to_secret(),
            )
            .expect("install recipient key");
        RecipientKeyReference {
            recipient,
            reference,
        }
    }

    fn key_admin_authorization() -> KeyAdministrationAuthorization {
        KeyAdministrationAuthorization {
            actor_id: ActorId::from("team-key-admin"),
            evidence_digest: "a".repeat(64),
        }
    }

    fn grant_team_member(
        fixture: &mut TeamKeyFixture,
        member: &KeyRecipient,
    ) -> RecipientKeyReference {
        let member_key = install_recipient_key(
            &fixture.secrets,
            &fixture.tenant,
            &fixture.project,
            member.clone(),
            1,
            2,
        );
        let granted = fixture
            .service
            .grant_project_key_recipient(
                &fixture.secrets,
                GrantProjectKeyRecipient {
                    project_id: fixture.project.clone(),
                    expected_keyring_revision: 1,
                    authorizing_key: fixture.primary_key.clone(),
                    recipient_key: member_key.clone(),
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(1),
            )
            .expect("grant member");
        assert_eq!(granted.revision, 2);
        let available_at = now() + Duration::minutes(1);
        let owner_project_key = open_active_project_key(
            &fixture.secrets,
            &granted,
            &fixture.primary_key,
            available_at,
        )
        .expect("owner opens project key");
        let member_project_key =
            open_active_project_key(&fixture.secrets, &granted, &member_key, available_at)
                .expect("member opens project key");
        assert_eq!(
            owner_project_key.to_secret().as_slice(),
            member_project_key.to_secret().as_slice()
        );
        member_key
    }

    fn opt_in_and_issue_worker(fixture: &mut TeamKeyFixture) -> RecipientKeyReference {
        let opted_in = fixture
            .service
            .set_project_remote_execution(
                &fixture.secrets,
                &SetProjectRemoteExecution {
                    project_id: fixture.project.clone(),
                    expected_keyring_revision: 2,
                    authorizing_key: fixture.primary_key.clone(),
                    enabled: true,
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(2),
            )
            .expect("remote execution opt in");
        assert!(opted_in.remote_execution_opt_in);
        let worker_id = WorkerId::from("worker-lease-1");
        let worker_key = install_recipient_key(
            &fixture.secrets,
            &fixture.tenant,
            &fixture.project,
            KeyRecipient::Worker(worker_id.clone()),
            1,
            3,
        );
        let with_worker = fixture
            .service
            .issue_worker_key_envelope(
                &fixture.secrets,
                IssueWorkerKeyEnvelope {
                    project_id: fixture.project.clone(),
                    expected_keyring_revision: 3,
                    authorizing_key: fixture.primary_key.clone(),
                    worker_id,
                    worker_key_reference: worker_key.reference.clone(),
                    expires_at: now() + Duration::minutes(12),
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(3),
            )
            .expect("short-lived worker envelope");
        assert_eq!(with_worker.revision, 4);
        worker_key
    }

    #[test]
    fn authorized_team_recipient_attaches_device_with_exact_cas_and_replay() {
        let mut fixture = setup_team_key_fixture();
        let owner_keyring = fixture
            .service
            .load_project_keyring(&fixture.project)
            .expect("owner keyring");
        let expected_project_key = open_active_project_key(
            &fixture.secrets,
            &owner_keyring,
            &fixture.primary_key,
            now(),
        )
        .expect("owner opens project key");
        let command = AttachProjectDevice {
            project_id: fixture.project.clone(),
            expected_keyring_revision: 1,
            authorizing_key: fixture.primary_key.clone(),
            device_id: DeviceId::from("device-team-second"),
            authorization: key_admin_authorization(),
            idempotency_key: "team-device-second-v1".into(),
        };
        let attached = fixture
            .service
            .attach_project_device(
                &fixture.secrets,
                command.clone(),
                now() + Duration::minutes(1),
            )
            .expect("authorized device attach");
        assert_eq!(attached.keyring.revision, 2);
        assert_eq!(attached.attachment.status, DeviceAttachmentStatus::Applied);
        let new_device_key = RecipientKeyReference {
            recipient: KeyRecipient::Device(DeviceId::from("device-team-second")),
            reference: attached.device_key_reference.clone(),
        };
        let opened = open_active_project_key(
            &fixture.secrets,
            &attached.keyring,
            &new_device_key,
            now() + Duration::minutes(1),
        )
        .expect("new team device opens project key");
        assert_eq!(
            opened.to_secret().as_slice(),
            expected_project_key.to_secret().as_slice()
        );

        let replay = fixture
            .service
            .attach_project_device(&fixture.secrets, command, now() + Duration::minutes(2))
            .expect("exact attach replay");
        assert!(replay.duplicate);
        assert_eq!(replay.attachment, attached.attachment);

        let recovery_reference = RecipientKeyReference {
            recipient: KeyRecipient::Recovery("not-an-admin".into()),
            reference: SecretReference {
                tenant_id: fixture.tenant,
                project_id: fixture.project.clone(),
                provider: "user-recovery".into(),
                account_scope: "recovery:not-an-admin".into(),
                purpose: "project_recovery_key:missing".into(),
                version: 1,
            },
        };
        assert!(matches!(
            fixture.service.attach_project_device(
                &fixture.secrets,
                AttachProjectDevice {
                    project_id: fixture.project,
                    expected_keyring_revision: 2,
                    authorizing_key: recovery_reference,
                    device_id: DeviceId::from("device-forbidden"),
                    authorization: key_admin_authorization(),
                    idempotency_key: "recovery-cannot-generic-attach".into(),
                },
                now() + Duration::minutes(3),
            ),
            Err(ApplicationError::InvalidKeyAdministrationAuthorization)
        ));
    }

    #[test]
    fn team_member_worker_opt_in_and_atomic_rotation_form_one_key_lifecycle() {
        let mut fixture = setup_team_key_fixture();
        let member = KeyRecipient::Member(MemberId::from("member-operator"));
        let member_v1 = grant_team_member(&mut fixture, &member);
        let worker_key = opt_in_and_issue_worker(&mut fixture);
        assert!(matches!(
            fixture.service.grant_project_key_recipient(
                &fixture.secrets,
                GrantProjectKeyRecipient {
                    project_id: fixture.project.clone(),
                    expected_keyring_revision: 4,
                    authorizing_key: worker_key.clone(),
                    recipient_key: member_v1,
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(3),
            ),
            Err(ApplicationError::InvalidKeyAdministrationAuthorization)
        ));
        assert!(matches!(
            fixture.service.set_project_remote_execution(
                &fixture.secrets,
                &SetProjectRemoteExecution {
                    project_id: fixture.project.clone(),
                    expected_keyring_revision: 4,
                    authorizing_key: worker_key,
                    enabled: false,
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(3),
            ),
            Err(ApplicationError::InvalidKeyAdministrationAuthorization)
        ));

        let member_v2 = install_recipient_key(
            &fixture.secrets,
            &fixture.tenant,
            &fixture.project,
            member,
            2,
            4,
        );
        let rotated = fixture
            .service
            .revoke_and_rotate_project_key(
                &fixture.secrets,
                RevokeAndRotateProjectKey {
                    project_id: fixture.project.clone(),
                    expected_keyring_revision: 4,
                    authorizing_key: fixture.primary_key.clone(),
                    revoked_recipient: KeyRecipient::Device(DeviceId::from("device-owner")),
                    retained_recipient_keys: vec![member_v2.clone()],
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(4),
            )
            .expect("atomic revoke and rotate");
        assert_eq!((rotated.active_key_version, rotated.revision), (2, 5));
        assert!(
            open_active_project_key(
                &fixture.secrets,
                &rotated,
                &member_v2,
                now() + Duration::minutes(4),
            )
            .is_ok()
        );
        assert!(rotated.envelopes.iter().any(|envelope| {
            matches!(envelope.recipient, KeyRecipient::Worker(_))
                && envelope.revoked_at == Some(now() + Duration::minutes(4))
        }));
        assert!(matches!(
            fixture.service.set_project_remote_execution(
                &fixture.secrets,
                &SetProjectRemoteExecution {
                    project_id: fixture.project,
                    expected_keyring_revision: 4,
                    authorizing_key: member_v2,
                    enabled: false,
                    authorization: key_admin_authorization(),
                },
                now() + Duration::minutes(5),
            ),
            Err(ApplicationError::KeyringRevisionMismatch {
                expected: 4,
                actual: 5
            })
        ));
    }

