    fn remote_sync_object(prepared: &PreparedEncryptedSyncOperation) -> EncryptedSyncObject {
        remote_sync_object_at(prepared, 1)
    }

    fn remote_sync_object_at(
        prepared: &PreparedEncryptedSyncOperation,
        revision: u64,
    ) -> EncryptedSyncObject {
        EncryptedSyncObject {
            scope: prepared.mutation.scope.clone(),
            project_id: prepared.mutation.project_id.clone(),
            object_id: prepared.mutation.object_id.clone(),
            object_kind: prepared.mutation.object_kind,
            revision,
            payload: prepared.mutation.payload.clone(),
            tombstone: prepared.mutation.tombstone,
            recorded_at: prepared.mutation.recorded_at,
        }
    }

