    #[test]
    fn creator_contact_withdrawal_after_approval_blocks_provider_execution() {
        let CreatorWithdrawalFixture {
            mut service,
            ids,
            effect_id,
            currency,
        } = prepare_creator_withdrawal_fixture();
        let mut broker = EffectBroker::new(
            EffectPolicy {
                version: "creator-contact-v1".into(),
                allowed_capabilities: BTreeSet::from(["partner.engage".into()]),
                allowed_classes: BTreeSet::from([EffectClass::Outreach]),
                max_amounts_minor: BTreeMap::from([(currency, 0)]),
                rate_limits: vec![EffectRateLimit {
                    rule_id: "creator-invitation-per-minute".into(),
                    provider: "hartevo-opt-in".into(),
                    capability: "partner.engage".into(),
                    max_executions: 30,
                    window_seconds: 60,
                }],
            },
            "creator-withdrawal-worker",
        );
        service
            .approve_effect(
                &broker,
                &ids.project,
                &ids.mission,
                &effect_id,
                ActorId::from("user-1"),
                now() + Duration::minutes(2),
            )
            .expect("approval");
        service
            .withdraw_partner_contact_permission(
                &ids.project,
                &ids.partner,
                "6".repeat(64),
                now() + Duration::minutes(3),
            )
            .expect("withdraw contact permission");
        let mut executor = CreatorActionExecutor {
            accepted_at: now() + Duration::minutes(4),
            calls: 0,
        };
        let mut verifier = CreatorActionVerifier {
            observed_at: now() + Duration::minutes(5),
        };
        let result = service.execute_effect(
            &mut broker,
            &ids.project,
            &ids.mission,
            &effect_id,
            &mut executor,
            &mut verifier,
            now() + Duration::minutes(4),
        );

        assert!(matches!(
            result,
            Err(ApplicationError::Broker(BrokerError::Permission(
                PermissionFailure::CreatorContactPermissionLost
            )))
        ));
        assert_eq!(executor.calls, 0);
    }

